CREATE OR REPLACE FUNCTION public.create_access_code_for_employee(input_tenant_id uuid, input_employee_id uuid, valid_days integer DEFAULT 365)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  new_code text;
  tries integer := 0;
begin
  loop
    new_code := public.generate_six_digit_code();

    exit when not exists (
      select 1
      from public.access_codes ac
      where ac.tenant_id = input_tenant_id
        and ac.code = new_code
    );

    tries := tries + 1;

    if tries > 30 then
      raise exception 'Konnte keinen eindeutigen Mitarbeiter:innen-Zugangscode erzeugen.';
    end if;
  end loop;

  insert into public.access_codes (
    tenant_id,
    code,
    code_type,
    employee_id,
    status,
    valid_until,
    created_by
  )
  values (
    input_tenant_id,
    new_code,
    'employee',
    input_employee_id,
    'active',
    now() + make_interval(days => valid_days),
    public.current_profile_id()
  );

  return new_code;
end;
$function$

CREATE OR REPLACE FUNCTION public.platform_prepare_account_operation(p_nonce uuid, p_tenant_id uuid, p_tenant_user_id uuid, p_action text, p_new_email text, p_reason text, p_authorization_confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_user public.tenant_users%ROWTYPE; v_op public.platform_account_operations%ROWTYPE; v_email text:=lower(trim(p_new_email)); v_auth_email text;
BEGIN
  PERFORM public.platform_assert_capability('tenants.write');
       -- tenant_access_company_active
       PERFORM 1 FROM public.platform_tenants WHERE tenant_id=p_tenant_id AND status='active' FOR SHARE;
       IF NOT FOUND THEN RAISE EXCEPTION 'access_action_invalid' USING ERRCODE='22023'; END IF;
  PERFORM public.platform_assert_reason(p_reason);
  IF p_authorization_confirmed IS DISTINCT FROM true THEN RAISE EXCEPTION 'account_authorization_required' USING ERRCODE='22023'; END IF;
  IF p_nonce IS NULL OR p_tenant_user_id IS NULL OR p_action IS NULL OR p_action NOT IN ('email_change','password_recovery','welcome_resend')
    OR length(trim(p_reason))>1000 THEN RAISE EXCEPTION 'account_request_invalid' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_nonce::text,61006));
  SELECT * INTO v_op FROM public.platform_account_operations WHERE id=p_nonce FOR UPDATE;
  IF FOUND THEN
    IF v_op.actor_user_id<>auth.uid() OR v_op.tenant_id<>p_tenant_id OR v_op.tenant_user_id<>p_tenant_user_id
      OR v_op.action<>p_action OR v_op.new_email IS DISTINCT FROM nullif(v_email,'') OR v_op.reason<>trim(p_reason)
    THEN RAISE EXCEPTION 'request_payload_changed' USING ERRCODE='22023'; END IF;
    RETURN jsonb_build_object('id',v_op.id,'state',v_op.state,'result',v_op.result);
  END IF;
  SELECT * INTO v_user FROM public.tenant_users WHERE id=p_tenant_user_id AND tenant_id=p_tenant_id FOR UPDATE;
  IF NOT FOUND OR v_user.auth_user_id IS NULL OR v_user.status<>'active' OR v_user.archived_at IS NOT NULL
    OR v_user.employee_id IS NOT NULL OR v_user.role_key IN ('employee','client')
  THEN RAISE EXCEPTION 'account_not_active' USING ERRCODE='22023'; END IF;
  SELECT lower(email) INTO v_auth_email FROM auth.users WHERE id=v_user.auth_user_id AND deleted_at IS NULL;
  IF v_auth_email IS NULL OR v_auth_email IS DISTINCT FROM lower(v_user.email)
    THEN RAISE EXCEPTION 'account_identity_mismatch' USING ERRCODE='22023'; END IF;
  IF p_action='email_change' THEN
    IF v_email IS NULL OR length(v_email)>254 OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' OR v_email=v_auth_email
      THEN RAISE EXCEPTION 'account_email_invalid' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM public.tenant_users WHERE auth_user_id=v_user.auth_user_id AND tenant_id<>p_tenant_id)
      OR EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=v_user.auth_user_id AND tenant_id IS DISTINCT FROM p_tenant_id)
      OR EXISTS(SELECT 1 FROM public.platform_users WHERE user_id=v_user.auth_user_id)
    THEN RAISE EXCEPTION 'account_shared_identity' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM auth.users WHERE lower(email)=v_email AND id<>v_user.auth_user_id AND deleted_at IS NULL)
      THEN RAISE EXCEPTION 'account_email_in_use' USING ERRCODE='23505'; END IF;
  ELSIF nullif(v_email,'') IS NOT NULL THEN RAISE EXCEPTION 'account_request_invalid' USING ERRCODE='22023'; END IF;
  IF p_action='welcome_resend' AND v_user.role_key<>'owner' THEN RAISE EXCEPTION 'welcome_owner_required' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM public.platform_account_operations WHERE auth_user_id=v_user.auth_user_id AND state IN ('prepared','processing','needs_review'))
    THEN RAISE EXCEPTION 'account_update_needs_review' USING ERRCODE='55000'; END IF;
  PERFORM 1 FROM public.registration_welcome_outbox WHERE tenant_user_id=v_user.id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.registration_welcome_outbox WHERE tenant_user_id=v_user.id AND state='sending' AND lease_until>now())
    THEN RAISE EXCEPTION 'account_mail_in_progress' USING ERRCODE='55000'; END IF;
  IF p_action IN ('email_change','welcome_resend') THEN
    UPDATE public.registration_welcome_outbox SET state='cancelled',lease_token=NULL,lease_until=NULL,updated_at=now()
      WHERE tenant_user_id=v_user.id AND state<>'sent';
  END IF;
  INSERT INTO public.platform_account_operations(id,actor_user_id,tenant_id,tenant_user_id,auth_user_id,action,old_email,new_email,reason)
    VALUES(p_nonce,auth.uid(),p_tenant_id,v_user.id,v_user.auth_user_id,p_action,v_auth_email,nullif(v_email,''),trim(p_reason)) RETURNING * INTO v_op;
  PERFORM public.platform_write_audit_log('tenant.account.requested','tenant_user',v_user.id,p_tenant_id,
    NULL,jsonb_build_object('operation',p_nonce,'action',p_action),trim(p_reason));
  RETURN jsonb_build_object('id',v_op.id,'state',v_op.state);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_assign_tenant_tariff(p_tenant_id uuid, p_plan_key text, p_reason text, p_billing_interval text DEFAULT 'monthly'::text, p_custom_monthly_cents integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_result jsonb;
BEGIN
  PERFORM public.platform_assert_capability('plans.write'); PERFORM public.platform_assert_reason(p_reason);
  IF p_billing_interval IS NULL OR p_billing_interval NOT IN ('monthly','yearly') OR p_custom_monthly_cents<0
    THEN RAISE EXCEPTION 'invalid_contract_values' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.platform_tenants WHERE tenant_id=p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE='P0002'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.platform_plans WHERE plan_key=p_plan_key AND status='active')
    THEN RAISE EXCEPTION 'plan_not_found' USING ERRCODE='P0002'; END IF;
  UPDATE public.platform_tenant_plans SET status='cancelled',ends_at=now(),updated_at=now() WHERE tenant_id=p_tenant_id AND status='paused';
  v_result:=public.platform_assign_plan(p_tenant_id,p_plan_key,p_reason,p_billing_interval,p_custom_monthly_cents);
  UPDATE public.platform_tenant_plans SET currency=(SELECT currency FROM public.platform_plans WHERE plan_key=p_plan_key) WHERE id=(v_result->>'id')::uuid RETURNING to_jsonb(platform_tenant_plans.*) INTO v_result;
  RETURN v_result;
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_tenant_contract(p_tenant_id uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_before jsonb; v_after jsonb;
BEGIN
  PERFORM public.platform_assert_capability('plans.write'); PERFORM public.platform_assert_reason(p_reason);
  IF p_status IS NULL OR p_status NOT IN ('active','paused','cancelled') THEN RAISE EXCEPTION 'invalid_contract_status' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.platform_tenants WHERE tenant_id=p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE='P0002'; END IF;
  SELECT to_jsonb(tp) INTO v_before FROM public.platform_tenant_plans tp WHERE tenant_id=p_tenant_id AND status IN ('active','paused') ORDER BY created_at DESC,id DESC LIMIT 1 FOR UPDATE;
  IF v_before IS NULL THEN RAISE EXCEPTION 'contract_not_found' USING ERRCODE='P0002'; END IF;
  UPDATE public.platform_tenant_plans SET status=p_status,ends_at=CASE WHEN p_status='cancelled' THEN now() ELSE NULL END,updated_at=now()
    WHERE id=(v_before->>'id')::uuid RETURNING to_jsonb(platform_tenant_plans.*) INTO v_after;
  PERFORM public.platform_write_audit_log('subscription.'||CASE p_status WHEN 'active' THEN 'reactivated' WHEN 'paused' THEN 'suspended' ELSE 'cancelled' END,
    'platform_tenant_plan',(v_after->>'id')::uuid,p_tenant_id,v_before,v_after,p_reason);
  RETURN v_after;
END; $function$

CREATE OR REPLACE FUNCTION public.platform_record_tenant_credit(p_nonce uuid, p_tenant_id uuid, p_amount_cents integer, p_reason text, p_entry_type text DEFAULT 'credit'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_entry public.platform_credit_ledger%ROWTYPE; v_balance integer; v_delta integer;
BEGIN
  PERFORM public.platform_assert_capability('billing.write'); PERFORM public.platform_assert_reason(p_reason);
  IF p_nonce IS NULL OR p_amount_cents IS NULL OR p_amount_cents<=0 OR p_entry_type IS NULL OR p_entry_type NOT IN ('credit','debit')
    THEN RAISE EXCEPTION 'invalid_credit_values' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_nonce::text,61007));
  SELECT * INTO v_entry FROM public.platform_credit_ledger WHERE id=p_nonce;
  IF FOUND THEN
    IF v_entry.tenant_id<>p_tenant_id OR v_entry.entry_type<>p_entry_type OR v_entry.amount_cents<>p_amount_cents
      OR v_entry.actor_user_id<>auth.uid() OR v_entry.reason<>trim(p_reason)
    THEN RAISE EXCEPTION 'request_payload_changed' USING ERRCODE='22023'; END IF;
    RETURN to_jsonb(v_entry);
  END IF;
  INSERT INTO public.platform_tenant_credits(tenant_id) VALUES(p_tenant_id) ON CONFLICT DO NOTHING;
  SELECT balance_cents INTO v_balance FROM public.platform_tenant_credits WHERE tenant_id=p_tenant_id FOR UPDATE;
  v_delta:=CASE WHEN p_entry_type='credit' THEN p_amount_cents ELSE -p_amount_cents END;
  IF v_balance::bigint+v_delta<0 OR v_balance::bigint+v_delta>2147483647 THEN RAISE EXCEPTION 'invalid_credit_balance' USING ERRCODE='22023'; END IF;
  UPDATE public.platform_tenant_credits SET balance_cents=v_balance+v_delta,updated_at=now() WHERE tenant_id=p_tenant_id;
  INSERT INTO public.platform_credit_ledger(id,tenant_id,entry_type,amount_cents,balance_after,reason,actor_user_id)
    VALUES(p_nonce,p_tenant_id,p_entry_type,p_amount_cents,v_balance+v_delta,trim(p_reason),auth.uid()) RETURNING * INTO v_entry;
  PERFORM public.platform_write_audit_log('credit.booked','platform_credit_ledger',v_entry.id,p_tenant_id,
    jsonb_build_object('balance_cents',v_balance),jsonb_build_object('balance_cents',v_entry.balance_after),trim(p_reason));
  RETURN to_jsonb(v_entry);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_create_plan(p_plan_key text, p_plan_name text, p_reason text, p_description text DEFAULT NULL::text, p_monthly_price_cents integer DEFAULT 0, p_yearly_price_cents integer DEFAULT 0, p_currency text DEFAULT 'EUR'::text, p_is_public boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_plan public.platform_plans%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('plans.write'); PERFORM public.platform_assert_reason(p_reason);
  IF p_plan_key IS NULL OR p_plan_key !~ '^[a-z][a-z0-9_]{2,63}$' OR p_plan_name IS NULL OR length(trim(p_plan_name)) NOT BETWEEN 2 AND 120
    OR p_currency IS DISTINCT FROM 'EUR' OR p_monthly_price_cents IS DISTINCT FROM 0 OR p_yearly_price_cents IS DISTINCT FROM 0
    THEN RAISE EXCEPTION 'invalid_plan_values' USING ERRCODE='22023'; END IF;
  INSERT INTO public.platform_plans(plan_key,plan_name,description,monthly_price_cents,yearly_price_cents,currency,is_public)
    VALUES(p_plan_key,trim(p_plan_name),nullif(trim(p_description),''),0,0,'EUR',coalesce(p_is_public,false)) RETURNING * INTO v_plan;
  PERFORM public.platform_write_audit_log('plan.created','platform_plan',v_plan.id,NULL,NULL,to_jsonb(v_plan),p_reason);
  RETURN to_jsonb(v_plan);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_plan(p_plan_key text, p_reason text, p_plan_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_is_public boolean DEFAULT NULL::boolean, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_before public.platform_plans%ROWTYPE; v_after public.platform_plans%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('plans.write'); PERFORM public.platform_assert_reason(p_reason);
  IF (p_plan_name IS NOT NULL AND length(trim(p_plan_name)) NOT BETWEEN 2 AND 120)
    OR (p_status IS NOT NULL AND p_status NOT IN ('active','inactive','archived')) THEN RAISE EXCEPTION 'invalid_plan_values' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_before FROM public.platform_plans WHERE plan_key=p_plan_key FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found' USING ERRCODE='P0002'; END IF;
  UPDATE public.platform_plans SET plan_name=coalesce(trim(p_plan_name),plan_name),description=coalesce(p_description,description),
    is_public=coalesce(p_is_public,is_public),status=coalesce(p_status,status),updated_at=now() WHERE id=v_before.id RETURNING * INTO v_after;
  PERFORM public.platform_write_audit_log('plan.updated','platform_plan',v_after.id,NULL,to_jsonb(v_before),to_jsonb(v_after),p_reason);
  RETURN to_jsonb(v_after);
END; $function$

CREATE OR REPLACE FUNCTION public.seed_tenant_assist_service_catalog(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_rate NUMERIC(10, 2);
  v_catalog_id UUID;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.tenant_service_catalog
    WHERE tenant_id = p_tenant_id AND module_key = 'assist'
  ) THEN
    RETURN;
  END IF;

  SELECT default_hourly_rate INTO v_rate
  FROM public.tenant_billing_settings
  WHERE tenant_id = p_tenant_id;

  v_rate := COALESCE(v_rate, 38.00);

  INSERT INTO public.tenant_service_catalog (
    tenant_id, module_key, service_key, name, description, unit, category, sort_order
  ) VALUES
    (p_tenant_id, 'assist', 'assist.alltagsbegleitung', 'Alltagsbegleitung',
     'Individuelle Alltagsbegleitung und Betreuung', 'hour', 'service', 10),
    (p_tenant_id, 'assist', 'assist.entlastung_45b', 'Entlastungsleistung §45b SGB XI',
     'Entlastungsleistung nach § 45b SGB XI', 'hour', 'service', 20),
    (p_tenant_id, 'assist', 'assist.verhinderungspflege_39', 'Verhinderungspflege §39 SGB XI',
     'Verhinderungspflege nach § 39 SGB XI', 'hour', 'service', 30),
    (p_tenant_id, 'assist', 'assist.haushaltshilfe_38', 'Haushaltshilfe §38 SGB V',
     'Haushaltshilfe nach § 38 SGB V', 'hour', 'service', 40),
    (p_tenant_id, 'assist', 'assist.travel.km', 'Fahrtkosten (km)',
     'Kilometerpauschale Assist-Fahrten', 'km', 'travel', 100),
    (p_tenant_id, 'assist', 'assist.surcharge.weekend', 'Wochenend-Zuschlag',
     'Zuschlag für Leistungen am Wochenende', 'percent', 'surcharge', 110)
  ON CONFLICT (tenant_id, service_key) DO NOTHING;

  SELECT id INTO v_catalog_id
  FROM public.tenant_service_catalog
  WHERE tenant_id = p_tenant_id AND service_key = 'assist.alltagsbegleitung';

  IF v_catalog_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.tenant_service_prices WHERE catalog_id = v_catalog_id AND is_default = TRUE
  ) THEN
    INSERT INTO public.tenant_service_prices (
      tenant_id, catalog_id, price_net, tax_rate, tax_mode, valid_from, is_default
    ) VALUES (
      p_tenant_id, v_catalog_id, v_rate, 0, 'exempt_4_16', CURRENT_DATE, TRUE
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.seed_tenant_billing_handoff_defaults(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_type_id UUID;
BEGIN
  INSERT INTO public.tenant_client_billing_handoff_settings (
    tenant_id, default_currency, default_unit, default_invoice_mode,
    require_signature, require_approval, allow_self_payer_fallback
  ) VALUES (
    p_tenant_id, 'EUR', 'hour', 'preview_only', TRUE, TRUE, TRUE
  )
  ON CONFLICT (tenant_id) DO NOTHING;

  FOR v_type_id IN
    SELECT id FROM public.tenant_client_service_types WHERE tenant_id = p_tenant_id
  LOOP
    INSERT INTO public.tenant_service_type_billing_rules (
      tenant_id, service_type_id, default_unit, default_billing_target_type,
      require_budget, require_signature, require_approval, is_active
    ) VALUES (
      p_tenant_id, v_type_id, 'hour', 'cost_carrier', TRUE, TRUE, TRUE, TRUE
    )
    ON CONFLICT (tenant_id, service_type_id) DO NOTHING;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_manage_tenant_access(p_tenant_id uuid, p_action text, p_expected_status text, p_expected_updated_at timestamp with time zone, p_confirmation text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_before public.platform_tenants%ROWTYPE; v_after public.platform_tenants%ROWTYPE; v_status text; v_audit text; v_message text;
BEGIN
  PERFORM public.platform_assert_capability('tenants.suspend');
  IF p_reason IS NULL OR length(trim(p_reason)) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'access_reason_invalid' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_before FROM public.platform_tenants WHERE tenant_id=p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE='P0002'; END IF;
  IF p_expected_status IS DISTINCT FROM v_before.status OR p_expected_updated_at IS DISTINCT FROM v_before.updated_at
    THEN RAISE EXCEPTION 'access_record_changed' USING ERRCODE='40001'; END IF;
  CASE
    WHEN p_action='suspend' AND v_before.status='active' THEN v_status:='suspended';v_audit:='tenant.suspended';v_message:='Das Unternehmen ist gesperrt.';
    WHEN p_action='unsuspend' AND v_before.status IN ('suspended','locked') THEN v_status:='active';v_audit:='tenant.unsuspended';v_message:='Das Unternehmen ist entsperrt. Einzeln deaktivierte Konten bleiben deaktiviert.';
    WHEN p_action='deactivate' AND v_before.status IN ('active','suspended','locked') THEN v_status:='terminated';v_audit:='tenant.deactivated';v_message:='Das Unternehmen ist deaktiviert. Die Daten bleiben erhalten.';
    WHEN p_action='reactivate' AND v_before.status='terminated' THEN v_status:='active';v_audit:='tenant.reactivated';v_message:='Das Unternehmen ist reaktiviert. Einzeln deaktivierte Konten bleiben deaktiviert.';
    WHEN p_action='delete' AND v_before.status IN ('active','suspended','locked','terminated') THEN v_status:='deleted_soft';v_audit:='tenant.deleted';v_message:='Das Unternehmen wurde in die Übersicht „Gelöscht“ verschoben. Die Daten bleiben erhalten.';
    WHEN p_action='restore' AND v_before.status='deleted_soft' THEN v_status:='terminated';v_audit:='tenant.restored';v_message:='Das Unternehmen ist wiederhergestellt und bleibt bis zur Reaktivierung deaktiviert.';
    ELSE RAISE EXCEPTION 'access_action_invalid' USING ERRCODE='22023';
  END CASE;
  IF (p_action='suspend' AND trim(coalesce(p_confirmation,''))<>'SPERREN')
    OR (p_action='deactivate' AND trim(coalesce(p_confirmation,''))<>'DEAKTIVIEREN')
    OR (p_action='delete' AND trim(coalesce(p_confirmation,''))<>trim(v_before.tenant_name))
    THEN RAISE EXCEPTION 'access_confirmation_required' USING ERRCODE='22023'; END IF;
  IF v_status<>'active' THEN
    -- Same lock order as account preparation: company, account, outbox.
    PERFORM 1 FROM public.tenant_users WHERE tenant_id=p_tenant_id ORDER BY id FOR UPDATE;
    IF EXISTS(SELECT 1 FROM public.platform_account_operations WHERE tenant_id=p_tenant_id AND state IN ('prepared','processing','needs_review'))
      THEN RAISE EXCEPTION 'account_update_needs_review' USING ERRCODE='55000'; END IF;
    PERFORM 1 FROM public.registration_welcome_outbox WHERE tenant_id=p_tenant_id ORDER BY id FOR UPDATE;
    IF EXISTS(SELECT 1 FROM public.registration_welcome_outbox WHERE tenant_id=p_tenant_id AND state='sending' AND lease_until>now())
      THEN RAISE EXCEPTION 'account_mail_in_progress' USING ERRCODE='55000'; END IF;
    UPDATE public.registration_welcome_outbox SET state='cancelled',lease_token=NULL,lease_until=NULL,updated_at=now()
      WHERE tenant_id=p_tenant_id AND state IN ('pending','failed');
  END IF;
  UPDATE public.platform_tenants SET status=v_status,updated_at=clock_timestamp(),
    suspended_at=CASE WHEN v_status='suspended' THEN now() WHEN v_status='active' THEN NULL ELSE suspended_at END,
    terminated_at=CASE WHEN v_status IN ('terminated','deleted_soft') THEN now() WHEN v_status='active' THEN NULL ELSE terminated_at END
    WHERE tenant_id=p_tenant_id RETURNING * INTO v_after;
  PERFORM public.platform_write_audit_log(v_audit,'platform_tenant',v_after.id,p_tenant_id,to_jsonb(v_before),to_jsonb(v_after),trim(p_reason));
  RETURN jsonb_build_object('status',v_status,'message',v_message);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_manage_account_access(p_tenant_id uuid, p_tenant_user_id uuid, p_action text, p_expected_status text, p_expected_updated_at timestamp with time zone, p_confirmation text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_user public.tenant_users%ROWTYPE; v_after public.tenant_users%ROWTYPE; v_access public.platform_account_access_states%ROWTYPE;
  v_company_status text; v_state text; v_status text; v_message text; v_before jsonb; v_name text;
BEGIN
  PERFORM public.platform_assert_capability('tenants.suspend');
  IF p_reason IS NULL OR length(trim(p_reason)) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'access_reason_invalid' USING ERRCODE='22023'; END IF;
  SELECT status INTO v_company_status FROM public.platform_tenants WHERE tenant_id=p_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE='P0002'; END IF;
  IF v_company_status='deleted_soft' THEN RAISE EXCEPTION 'tenant_deleted_restore_first' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_user FROM public.tenant_users WHERE id=p_tenant_user_id AND tenant_id=p_tenant_id
    AND employee_id IS NULL AND role_key NOT IN ('employee','client') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'account_not_found' USING ERRCODE='P0002'; END IF;
  IF p_expected_status IS DISTINCT FROM v_user.status OR p_expected_updated_at IS DISTINCT FROM v_user.updated_at
    THEN RAISE EXCEPTION 'access_record_changed' USING ERRCODE='40001'; END IF;
  IF EXISTS(SELECT 1 FROM public.platform_account_operations WHERE auth_user_id=v_user.auth_user_id AND state IN ('prepared','processing','needs_review'))
    THEN RAISE EXCEPTION 'account_update_needs_review' USING ERRCODE='55000'; END IF;
  PERFORM 1 FROM public.registration_welcome_outbox WHERE tenant_user_id=v_user.id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.registration_welcome_outbox WHERE tenant_user_id=v_user.id AND state='sending' AND lease_until>now())
    THEN RAISE EXCEPTION 'account_mail_in_progress' USING ERRCODE='55000'; END IF;
  SELECT * INTO v_access FROM public.platform_account_access_states WHERE tenant_user_id=v_user.id FOR UPDATE;
  v_state:=coalesce(v_access.state,'active');
  v_before:=jsonb_build_object('account',to_jsonb(v_user),'access_state',v_state);
  v_name:=coalesce(nullif(trim(v_user.display_name),''),nullif(trim(v_user.email),''),'Verwaltungskonto');
  IF (p_action='deactivate' AND trim(coalesce(p_confirmation,''))<>'DEAKTIVIEREN')
    OR (p_action='delete' AND trim(coalesce(p_confirmation,''))<>v_name)
    THEN RAISE EXCEPTION 'access_confirmation_required' USING ERRCODE='22023'; END IF;
  IF p_action IN ('deactivate','delete') AND v_user.role_key='owner' AND v_user.status='active' AND v_state='active' AND v_company_status='active'
    AND NOT EXISTS(SELECT 1 FROM public.tenant_users u LEFT JOIN public.platform_account_access_states s ON s.tenant_user_id=u.id
      WHERE u.tenant_id=p_tenant_id AND u.id<>v_user.id AND u.role_key='owner' AND u.status='active' AND u.archived_at IS NULL
        AND coalesce(s.state,'active')='active')
    THEN RAISE EXCEPTION 'last_tenant_owner_protected' USING ERRCODE='55000'; END IF;
  INSERT INTO public.platform_account_access_states(tenant_user_id,tenant_id) VALUES(v_user.id,p_tenant_id) ON CONFLICT DO NOTHING;
  CASE
    WHEN p_action='deactivate' AND v_state='active' AND v_user.status IN ('active','pending_first_login','password_reset_required') AND v_user.archived_at IS NULL THEN
      UPDATE public.platform_account_access_states SET state='inactive',prior_status=v_user.status,updated_at=now() WHERE tenant_user_id=v_user.id;
      v_status:='blocked';v_message:='Das Konto ist für dieses Unternehmen deaktiviert.';
    WHEN p_action='reactivate' AND v_state='inactive' AND v_user.status='blocked' AND v_user.archived_at IS NULL THEN
      UPDATE public.platform_account_access_states SET state='active',updated_at=now() WHERE tenant_user_id=v_user.id;
      v_status:=v_access.prior_status;v_message:='Das Konto ist reaktiviert. Ein deaktiviertes Unternehmen bleibt unzugänglich.';
    WHEN p_action='delete' AND v_state IN ('active','inactive') AND v_user.archived_at IS NULL THEN
      UPDATE public.platform_account_access_states SET state='deleted',deleted_from_state=v_state,deleted_user_status=v_user.status,
        deleted_user_archived_at=v_user.archived_at,updated_at=now() WHERE tenant_user_id=v_user.id;
      v_status:='archived';v_message:='Der Zugang zu diesem Unternehmen wurde entfernt. Das Konto ist unter „Gelöschte Konten“ auffindbar.';
    WHEN p_action='restore' AND v_state='deleted' AND v_user.status='archived' THEN
      UPDATE public.platform_account_access_states SET state=v_access.deleted_from_state,updated_at=now() WHERE tenant_user_id=v_user.id;
      v_status:=v_access.deleted_user_status;v_message:=CASE WHEN v_access.deleted_from_state='inactive' THEN 'Das Konto ist wiederhergestellt und bleibt deaktiviert.' ELSE 'Das Konto ist mit seinem vorherigen Zustand wiederhergestellt.' END;
    ELSE RAISE EXCEPTION 'access_action_invalid' USING ERRCODE='22023';
  END CASE;
  UPDATE public.tenant_users SET status=v_status,updated_at=clock_timestamp(),
    archived_at=CASE WHEN p_action='delete' THEN now() WHEN p_action='restore' THEN v_access.deleted_user_archived_at ELSE archived_at END
    WHERE id=v_user.id RETURNING * INTO v_after;
  IF p_action IN ('deactivate','delete') THEN
    UPDATE public.registration_welcome_outbox SET state='cancelled',lease_token=NULL,lease_until=NULL,updated_at=now()
      WHERE tenant_user_id=v_user.id AND state IN ('pending','failed');
  END IF;
  SELECT state INTO v_state FROM public.platform_account_access_states WHERE tenant_user_id=v_user.id;
  PERFORM public.platform_write_audit_log('tenant.account.'||CASE p_action WHEN 'deactivate' THEN 'deactivated' WHEN 'reactivate' THEN 'reactivated' WHEN 'delete' THEN 'deleted' ELSE 'restored' END,
    'tenant_user',v_user.id,p_tenant_id,v_before,jsonb_build_object('account',to_jsonb(v_after),'access_state',v_state),trim(p_reason));
  RETURN jsonb_build_object('status',v_status,'message',v_message);
END; $function$

CREATE OR REPLACE FUNCTION public.create_access_code_for_client(input_tenant_id uuid, input_client_id uuid, valid_days integer DEFAULT 365)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  new_code text;
  tries integer := 0;
begin
  loop
    new_code := public.generate_six_digit_code();

    exit when not exists (
      select 1
      from public.access_codes ac
      where ac.tenant_id = input_tenant_id
        and ac.code = new_code
    );

    tries := tries + 1;

    if tries > 30 then
      raise exception 'Konnte keinen eindeutigen Klient:innen-Zugangscode erzeugen.';
    end if;
  end loop;

  insert into public.access_codes (
    tenant_id,
    code,
    code_type,
    client_id,
    status,
    valid_until,
    created_by
  )
  values (
    input_tenant_id,
    new_code,
    'client',
    input_client_id,
    'active',
    now() + make_interval(days => valid_days),
    public.current_profile_id()
  );

  return new_code;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tenant_id uuid;
  v_profile_id uuid;
  v_action public.audit_action_type;
  v_record_id uuid;
begin
  v_profile_id := public.current_profile_id();

  if tg_op = 'INSERT' then
    v_action := 'create';
    v_record_id := new.id;

    v_tenant_id := nullif(to_jsonb(new)->>'tenant_id', '')::uuid;

    insert into public.audit_logs (
      tenant_id,
      profile_id,
      action,
      table_name,
      record_id,
      title,
      description,
      new_data
    )
    values (
      v_tenant_id,
      v_profile_id,
      v_action,
      tg_table_name,
      v_record_id,
      'Datensatz erstellt',
      'Ein Datensatz wurde in ' || tg_table_name || ' erstellt.',
      to_jsonb(new)
    );

    return new;

  elsif tg_op = 'UPDATE' then
    v_action := 'update';
    v_record_id := new.id;

    v_tenant_id := nullif(to_jsonb(new)->>'tenant_id', '')::uuid;

    insert into public.audit_logs (
      tenant_id,
      profile_id,
      action,
      table_name,
      record_id,
      title,
      description,
      old_data,
      new_data
    )
    values (
      v_tenant_id,
      v_profile_id,
      v_action,
      tg_table_name,
      v_record_id,
      'Datensatz geändert',
      'Ein Datensatz wurde in ' || tg_table_name || ' geändert.',
      to_jsonb(old),
      to_jsonb(new)
    );

    return new;

  elsif tg_op = 'DELETE' then
    v_action := 'delete';
    v_record_id := old.id;

    v_tenant_id := nullif(to_jsonb(old)->>'tenant_id', '')::uuid;

    insert into public.audit_logs (
      tenant_id,
      profile_id,
      action,
      table_name,
      record_id,
      title,
      description,
      old_data
    )
    values (
      v_tenant_id,
      v_profile_id,
      v_action,
      tg_table_name,
      v_record_id,
      'Datensatz gelöscht',
      'Ein Datensatz wurde in ' || tg_table_name || ' gelöscht.',
      to_jsonb(old)
    );

    return old;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_invoice_number(input_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_prefix text;
  v_next integer;
  v_number text;
begin
  select
    coalesce(invoice_prefix, 'CS'),
    coalesce(next_invoice_number, 1)
  into v_prefix, v_next
  from public.tenant_billing_settings
  where tenant_id = input_tenant_id
  limit 1;

  if v_prefix is null then
    v_prefix := 'CS';
  end if;

  if v_next is null then
    v_next := 1;
  end if;

  v_number := v_prefix || '-' || to_char(current_date, 'YYYY') || '-' || lpad(v_next::text, 5, '0');

  update public.tenant_billing_settings
  set next_invoice_number = v_next + 1
  where tenant_id = input_tenant_id;

  return v_number;
end;
$function$

CREATE OR REPLACE FUNCTION public.platform_set_incident_resolution(p_id uuid, p_expected_last_seen_at timestamp with time zone, p_resolved boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_before platform_observation_private.incidents%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  PERFORM public.platform_assert_capability('system.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF length(p_reason)>1000 OR p_resolved IS NULL THEN RAISE EXCEPTION 'observation_invalid' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_before FROM platform_observation_private.incidents WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR p_expected_last_seen_at IS NULL OR v_before.last_seen_at<>p_expected_last_seen_at THEN
    RAISE EXCEPTION 'access_record_changed' USING ERRCODE='40001'; END IF;
  UPDATE platform_observation_private.incidents SET resolved=p_resolved,resolution=trim(p_reason),
    resolved_at=CASE WHEN p_resolved THEN now() ELSE NULL END WHERE id=p_id;
  PERFORM public.platform_write_audit_log('runtime.incident_status_changed','platform_runtime_incident',p_id,v_before.tenant_id,
    jsonb_build_object('resolved',v_before.resolved),jsonb_build_object('resolved',p_resolved),trim(p_reason));
END; $function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_role_id  UUID;
  v_raw_name TEXT;
  v_first    TEXT;
  v_last     TEXT;
BEGIN
  -- Rolle ermitteln
  SELECT id INTO v_role_id FROM public.roles WHERE key = 'owner' LIMIT 1;
  IF v_role_id IS NULL THEN
    SELECT id INTO v_role_id FROM public.roles ORDER BY created_at LIMIT 1;
  END IF;

  -- Namen aus Meta-Daten lesen
  v_raw_name := COALESCE(
    NULLIF(TRIM(NEW.raw_user_meta_data->>'full_name'), ''),
    NULLIF(TRIM(NEW.raw_user_meta_data->>'display_name'), ''),
    NULLIF(TRIM(NEW.raw_user_meta_data->>'name'), ''),
    split_part(NEW.email, '@', 1)
  );

  -- Namen in first_name / last_name aufteilen
  -- full_name ist GENERATED ALWAYS und darf NICHT explizit gesetzt werden
  v_first := split_part(v_raw_name, ' ', 1);
  v_last  := NULLIF(TRIM(SUBSTRING(v_raw_name FROM POSITION(' ' IN v_raw_name))), '');

  INSERT INTO public.profiles (
    auth_user_id,
    email,
    first_name,
    last_name,
    role_id,
    status
  )
  VALUES (
    NEW.id,
    NEW.email,
    v_first,
    v_last,
    v_role_id,
    'invited'
  )
  ON CONFLICT (auth_user_id) DO NOTHING;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_assist_visit_budget_executed(p_tenant_id uuid, p_visit_id uuid, p_actor_employee_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_updated INTEGER := 0;
  v_employee_id UUID;
BEGIN
  IF p_tenant_id IS NULL OR p_visit_id IS NULL THEN
    RAISE EXCEPTION 'mark_assist_visit_budget_executed: missing required parameters';
  END IF;

  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'mark_assist_visit_budget_executed: tenant mismatch';
  END IF;

  IF public.is_employee_portal_rls_context(p_tenant_id) THEN
    v_employee_id := public.resolve_current_employee_id();
    IF v_employee_id IS NULL THEN
      RAISE EXCEPTION 'mark_assist_visit_budget_executed: employee portal context without employee link';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.assignments a
      WHERE a.tenant_id = p_tenant_id
        AND a.id = p_visit_id
        AND a.employee_id = v_employee_id
    ) AND NOT EXISTS (
      SELECT 1
      FROM public.assist_visits av
      WHERE av.tenant_id = p_tenant_id
        AND av.id = p_visit_id
        AND av.employee_id = v_employee_id
    ) THEN
      RAISE EXCEPTION 'mark_assist_visit_budget_executed: assignment not assigned to current employee';
    END IF;
  ELSIF NOT (
    public.has_permission('clients.budgets.edit')
    OR public.has_permission('clients.billing_profile.edit')
    OR public.has_permission('office.clients.edit')
  ) THEN
    RAISE EXCEPTION 'mark_assist_visit_budget_executed: insufficient permissions';
  END IF;

  UPDATE public.client_budget_transactions
  SET lifecycle_status = 'durchgefuehrt'
  WHERE tenant_id = p_tenant_id
    AND reference_type = 'assist_visit'
    AND reference_id = p_visit_id
    AND transaction_type = 'reservation'
    AND (
      lifecycle_status IS NULL
      OR lifecycle_status IN ('geplant', 'durchgefuehrt')
    );

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated > 0 THEN
    UPDATE public.assist_visits
    SET
      billing_status = CASE
        WHEN billing_status IN ('none', 'preview') THEN 'reserved'
        ELSE billing_status
      END,
      updated_at = NOW()
    WHERE tenant_id = p_tenant_id
      AND (id = p_visit_id OR legacy_assignment_id = p_visit_id);
  END IF;

  RETURN v_updated;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_assist_visit_times_to_wfm(p_tenant_id uuid, p_visit_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_employee_id UUID;
  v_auth_user_id UUID;
  v_work_date DATE;
  v_session_id UUID;
  v_inserted INTEGER := 0;
  r RECORD;
  v_wfm_type TEXT;
  v_session_status TEXT;
  v_display_status TEXT;
BEGIN
  IF p_tenant_id IS NULL OR p_visit_id IS NULL THEN
    RAISE EXCEPTION 'sync_assist_visit_times_to_wfm: missing required parameters';
  END IF;

  IF NOT (
    p_tenant_id IS NOT DISTINCT FROM public.current_tenant_id()
    OR (
      auth.uid() IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.employee_portal_accounts epa
        WHERE epa.tenant_id = p_tenant_id
          AND epa.auth_user_id = auth.uid()
          AND epa.status = 'active'
      )
    )
    OR public.is_tenant_admin()
    OR public.has_permission('time.tracking.admin.correct')
  ) THEN
    RAISE EXCEPTION 'sync_assist_visit_times_to_wfm: tenant access denied';
  END IF;

  IF public.is_employee_portal_rls_context(p_tenant_id) THEN
    v_employee_id := public.resolve_current_employee_id();
    IF v_employee_id IS NULL THEN
      RAISE EXCEPTION 'sync_assist_visit_times_to_wfm: portal context without employee link';
    END IF;
  ELSIF NOT (
    public.has_permission('time.tracking.admin.correct')
    OR public.has_permission('time.tracking.own.start')
    OR public.is_tenant_admin()
  ) THEN
    RAISE EXCEPTION 'sync_assist_visit_times_to_wfm: insufficient permissions';
  END IF;

  IF v_employee_id IS NULL THEN
    SELECT COALESCE(av.employee_id, a.employee_id)
    INTO v_employee_id
    FROM public.assist_visits av
    FULL OUTER JOIN public.assignments a
      ON a.id = p_visit_id AND a.tenant_id = p_tenant_id
    WHERE (av.id = p_visit_id AND av.tenant_id = p_tenant_id)
       OR (a.id = p_visit_id AND a.tenant_id = p_tenant_id)
    LIMIT 1;
  END IF;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION 'sync_assist_visit_times_to_wfm: employee not resolved for visit';
  END IF;

  IF public.is_employee_portal_rls_context(p_tenant_id) THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.assignments a
      WHERE a.tenant_id = p_tenant_id
        AND a.id = p_visit_id
        AND a.employee_id = v_employee_id
    ) AND NOT EXISTS (
      SELECT 1
      FROM public.assist_visits av
      WHERE av.tenant_id = p_tenant_id
        AND av.id = p_visit_id
        AND av.employee_id = v_employee_id
    ) THEN
      RAISE EXCEPTION 'sync_assist_visit_times_to_wfm: visit not assigned to current employee';
    END IF;
  END IF;

  SELECT epa.auth_user_id INTO v_auth_user_id
  FROM public.employee_portal_accounts epa
  WHERE epa.tenant_id = p_tenant_id
    AND epa.employee_id = v_employee_id
  LIMIT 1;

  IF v_auth_user_id IS NULL THEN
    SELECT e.profile_id INTO v_auth_user_id
    FROM public.employees e
    WHERE e.tenant_id = p_tenant_id AND e.id = v_employee_id
    LIMIT 1;
  END IF;

  FOR r IN
    SELECT event_type, occurred_at
    FROM public.assist_time_events
    WHERE tenant_id = p_tenant_id
      AND visit_id = p_visit_id
    ORDER BY occurred_at ASC
  LOOP
    v_wfm_type := CASE r.event_type
      WHEN 'drive_start'   THEN 'visit_drive_start'
      WHEN 'drive_end'     THEN 'travel_end'
      WHEN 'arrive'        THEN 'visit_arrived'
      WHEN 'service_start' THEN 'visit_started'
      WHEN 'service_end'   THEN 'visit_ended'
      WHEN 'pause_start'   THEN 'pause_start'
      WHEN 'pause_end'     THEN 'pause_end'
      WHEN 'depart'        THEN 'visit_ended'
      ELSE NULL
    END;

    IF v_wfm_type IS NULL THEN
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.workforce_time_events e
      WHERE e.tenant_id = p_tenant_id
        AND e.employee_id = v_employee_id
        AND e.event_type = v_wfm_type
        AND e.reference_type = 'visit'
        AND e.reference_id = p_visit_id
    ) THEN
      CONTINUE;
    END IF;

    v_work_date := (r.occurred_at AT TIME ZONE 'Europe/Berlin')::date;

    SELECT ws.id INTO v_session_id
    FROM public.workforce_work_sessions ws
    WHERE ws.tenant_id = p_tenant_id
      AND ws.employee_id = v_employee_id
      AND ws.work_date = v_work_date
    LIMIT 1;

    v_session_status := CASE r.event_type
      WHEN 'drive_start'   THEN 'driving'
      WHEN 'arrive'        THEN 'on_visit'
      WHEN 'service_start' THEN 'on_visit'
      WHEN 'pause_start'   THEN 'paused'
      WHEN 'pause_end'     THEN 'on_visit'
      WHEN 'service_end'   THEN 'clocked_in'
      WHEN 'depart'        THEN 'clocked_in'
      WHEN 'drive_end'     THEN 'clocked_in'
      ELSE 'on_visit'
    END;

    v_display_status := CASE r.event_type
      WHEN 'drive_start'   THEN 'unterwegs'
      WHEN 'arrive'        THEN 'im_einsatz'
      WHEN 'service_start' THEN 'im_einsatz'
      WHEN 'pause_start'   THEN 'pause'
      WHEN 'pause_end'     THEN 'im_einsatz'
      WHEN 'service_end'   THEN 'buero'
      WHEN 'depart'        THEN 'buero'
      WHEN 'drive_end'     THEN 'buero'
      ELSE 'im_einsatz'
    END;

    IF v_session_id IS NULL THEN
      v_session_id := gen_random_uuid();
      INSERT INTO public.workforce_work_sessions (
        id, tenant_id, employee_id, user_id, work_date,
        status, work_mode, display_status,
        started_at, last_event_at, is_online,
        gross_minutes, net_minutes, pause_minutes, current_visit_id
      ) VALUES (
        v_session_id, p_tenant_id, v_employee_id, v_auth_user_id, v_work_date,
        v_session_status, 'field', v_display_status,
        r.occurred_at, r.occurred_at, r.event_type NOT IN ('service_end', 'depart'),
        0, 0, 0, p_visit_id
      );
    ELSE
      UPDATE public.workforce_work_sessions
      SET
        status = v_session_status,
        display_status = v_display_status,
        last_event_at = r.occurred_at,
        is_online = r.event_type NOT IN ('service_end', 'depart'),
        current_visit_id = COALESCE(current_visit_id, p_visit_id),
        updated_at = NOW()
      WHERE id = v_session_id;
    END IF;

    INSERT INTO public.workforce_time_events (
      id, tenant_id, employee_id, user_id,
      event_type, work_mode, source, occurred_at,
      session_id, reference_type, reference_id
    ) VALUES (
      gen_random_uuid(), p_tenant_id, v_employee_id, v_auth_user_id,
      v_wfm_type, 'field', 'assist', r.occurred_at,
      v_session_id, 'visit', p_visit_id
    );

    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN v_inserted;
END;
$function$

CREATE OR REPLACE FUNCTION public.wfm_finalize_correction_export(p_export_job_id uuid, p_items jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id   UUID;
  v_job         RECORD;
  v_actor       UUID;
  v_item        JSONB;
  v_old_item    RECORD;
  v_new_item_id UUID;
  v_review      RECORD;
  v_item_count  INTEGER := 0;
  v_old_seq     INTEGER;
  v_new_seq     INTEGER;
  v_new_ref_key TEXT;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: authentication required';
  END IF;

  v_tenant_id := public.current_tenant_id();
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: tenant context required';
  END IF;

  IF NOT (
    public.is_tenant_admin()
    OR public.has_permission('time.tracking.admin.export')
  ) THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: permission denied';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: p_items required';
  END IF;

  SELECT *
  INTO v_job
  FROM public.workforce_export_jobs
  WHERE id = p_export_job_id
    AND tenant_id = v_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: export job not found';
  END IF;

  IF v_job.export_type <> 'reviewed_time_correction' THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: not a correction export job';
  END IF;

  IF v_job.status <> 'validated' THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: job must be validated before finalize';
  END IF;

  IF v_job.correction_of_export_job_id IS NULL THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: correction_of_export_job_id required';
  END IF;

  IF v_job.correction_reason IS NULL OR length(trim(v_job.correction_reason)) < 10 THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: correction_reason required (min 10 chars)';
  END IF;

  IF v_job.export_scope IS DISTINCT FROM 'delta_correction' THEN
    RAISE EXCEPTION 'wfm_finalize_correction_export: export_scope must be delta_correction';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    IF v_item->>'review_id' IS NULL OR v_item->>'review_id' = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: review_id required';
    END IF;
    IF v_item->>'original_export_item_id' IS NULL OR v_item->>'original_export_item_id' = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: original_export_item_id required';
    END IF;
    IF v_item->>'logical_reference_key' IS NULL OR trim(v_item->>'logical_reference_key') = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: logical_reference_key required';
    END IF;
    IF v_item->>'new_reference_key' IS NULL OR trim(v_item->>'new_reference_key') = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: new_reference_key required';
    END IF;
    IF v_item->>'export_sequence' IS NULL THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: export_sequence required';
    END IF;
    IF v_item->'exported_payload' IS NULL THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: exported_payload required';
    END IF;
    IF v_item->'correction_payload_delta' IS NULL THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: correction_payload_delta required';
    END IF;
    IF v_item->>'previous_payload_hash' IS NULL OR trim(v_item->>'previous_payload_hash') = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: previous_payload_hash required';
    END IF;
    IF v_item->>'payload_hash' IS NULL OR trim(v_item->>'payload_hash') = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: payload_hash required';
    END IF;
    IF v_item->>'correction_reason' IS NULL OR length(trim(v_item->>'correction_reason')) < 10 THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: item correction_reason required (min 10 chars)';
    END IF;
    IF v_item->>'employee_id' IS NULL OR v_item->>'employee_id' = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: employee_id required';
    END IF;
    IF v_item->>'entry_kind' IS NULL OR v_item->>'entry_kind' = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: entry_kind required';
    END IF;
    IF v_item->>'period_date' IS NULL OR v_item->>'period_date' = '' THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: period_date required';
    END IF;
    IF v_item->>'minutes_total' IS NULL THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: minutes_total required';
    END IF;

    v_new_seq := (v_item->>'export_sequence')::INTEGER;
    IF v_new_seq < 2 THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: export_sequence must be >= 2 for corrections';
    END IF;

    v_new_ref_key := trim(v_item->>'new_reference_key');

    IF EXISTS (
      SELECT 1
      FROM public.workforce_time_export_items
      WHERE tenant_id = v_tenant_id
        AND reference_key = v_new_ref_key
    ) THEN
      RAISE EXCEPTION
        'wfm_finalize_correction_export: new_reference_key already exists: %',
        v_new_ref_key;
    END IF;

    SELECT *
    INTO v_review
    FROM public.workforce_time_entry_reviews
    WHERE id = (v_item->>'review_id')::UUID
      AND tenant_id = v_tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: review not found';
    END IF;

    IF v_review.export_status NOT IN ('exported', 'changed_after_export') THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: review must be exported or changed_after_export';
    END IF;

    SELECT *
    INTO v_old_item
    FROM public.workforce_time_export_items
    WHERE id = (v_item->>'original_export_item_id')::UUID
      AND tenant_id = v_tenant_id
      AND item_status = 'active'
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: active original item not found';
    END IF;

    IF v_old_item.logical_reference_key IS DISTINCT FROM trim(v_item->>'logical_reference_key') THEN
      RAISE EXCEPTION 'wfm_finalize_correction_export: logical_reference_key mismatch with original item';
    END IF;

    v_old_seq := v_old_item.export_sequence;
    IF v_new_seq <= v_old_seq THEN
      RAISE EXCEPTION
        'wfm_finalize_correction_export: export_sequence % must be greater than %',
        v_new_seq,
        v_old_seq;
    END IF;

    v_new_item_id := gen_random_uuid();

    UPDATE public.workforce_time_export_items
    SET
      item_status = 'superseded',
      superseded_at = NOW(),
      superseded_by = v_actor
    WHERE id = v_old_item.id;

    INSERT INTO public.workforce_time_export_items (
      id,
      tenant_id,
      export_job_id,
      review_id,
      employee_id,
      reference_id,
      reference_key,
      logical_reference_key,
      export_sequence,
      item_status,
      entry_kind,
      period_date,
      minutes_total,
      review_status_at_export,
      exported_payload,
      payload_hash,
      source_review_version_hash,
      previous_payload_hash,
      correction_reason,
      correction_payload_delta,
      supersedes_export_item_id,
      changed_after_export
    ) VALUES (
      v_new_item_id,
      v_tenant_id,
      p_export_job_id,
      (v_item->>'review_id')::UUID,
      (v_item->>'employee_id')::UUID,
      NULLIF(v_item->>'reference_id', '')::UUID,
      v_new_ref_key,
      trim(v_item->>'logical_reference_key'),
      v_new_seq,
      'active',
      v_item->>'entry_kind',
      (v_item->>'period_date')::date,
      (v_item->>'minutes_total')::INTEGER,
      'approved',
      v_item->'exported_payload',
      trim(v_item->>'payload_hash'),
      NULLIF(trim(v_item->>'source_review_version_hash'), ''),
      trim(v_item->>'previous_payload_hash'),
      trim(v_item->>'correction_reason'),
      v_item->'correction_payload_delta',
      v_old_item.id,
      FALSE
    );

    UPDATE public.workforce_time_export_items
    SET superseded_by_export_item_id = v_new_item_id
    WHERE id = v_old_item.id;

    UPDATE public.workforce_time_entry_reviews
    SET
      export_status = 'exported',
      changed_after_export = FALSE,
      changed_after_export_detected_at = NULL,
      changed_after_export_reason = NULL,
      latest_export_item_id = v_new_item_id,
      last_export_job_id = p_export_job_id,
      last_exported_at = NOW(),
      pending_reexport_job_id = NULL,
      export_version = export_version + 1
    WHERE id = (v_item->>'review_id')::UUID
      AND tenant_id = v_tenant_id;

    INSERT INTO public.workforce_time_review_actions (
      tenant_id,
      entry_review_id,
      action,
      prev_status,
      new_status,
      reason,
      comment,
      actor_id,
      source,
      metadata
    ) VALUES (
      v_tenant_id,
      (v_item->>'review_id')::UUID,
      'export_item_superseded',
      'approved',
      'approved',
      v_job.correction_reason,
      'Korrektur-Export: Item superseded',
      v_actor,
      'office',
      jsonb_build_object(
        'export_job_id', p_export_job_id,
        'old_item_id', v_old_item.id,
        'new_item_id', v_new_item_id,
        'logical_reference_key', trim(v_item->>'logical_reference_key'),
        'export_sequence', v_new_seq
      )
    );

    INSERT INTO public.workforce_time_review_actions (
      tenant_id,
      entry_review_id,
      action,
      prev_status,
      new_status,
      reason,
      comment,
      actor_id,
      source,
      metadata
    ) VALUES (
      v_tenant_id,
      (v_item->>'review_id')::UUID,
      'reexport_finalized',
      'approved',
      'approved',
      v_job.correction_reason,
      'Korrektur-Export finalisiert',
      v_actor,
      'office',
      jsonb_build_object('export_job_id', p_export_job_id)
    );

    v_item_count := v_item_count + 1;
  END LOOP;

  INSERT INTO public.workforce_time_review_actions (
    tenant_id,
    entry_review_id,
    action,
    prev_status,
    new_status,
    reason,
    comment,
    actor_id,
    source,
    metadata
  )
  SELECT DISTINCT
    v_tenant_id,
    (elem->>'review_id')::UUID,
    'correction_export_finalized',
    'approved',
    'approved',
    v_job.correction_reason,
    'Korrektur-Export-Job finalisiert',
    v_actor,
    'office',
    jsonb_build_object(
      'export_job_id', p_export_job_id,
      'correction_of_export_job_id', v_job.correction_of_export_job_id,
      'item_count', v_item_count
    )
  FROM jsonb_array_elements(p_items) AS elem;

  UPDATE public.workforce_export_jobs
  SET
    status = 'finalized',
    row_count = v_item_count,
    finalized_at = NOW(),
    finalized_by = v_actor,
    updated_at = NOW()
  WHERE id = p_export_job_id
    AND tenant_id = v_tenant_id;

  RETURN p_export_job_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_record_manual_payment(p_tenant_id uuid, p_invoice_id uuid, p_amount_cents integer, p_status text, p_reason text, p_payment_method text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.platform_payments%ROWTYPE;v_invoice public.platform_invoices%ROWTYPE;v_currency TEXT='EUR';
BEGIN
  PERFORM public.platform_assert_capability('payments.write');PERFORM public.platform_assert_reason(p_reason);
  IF p_amount_cents IS NULL OR p_amount_cents<=0 OR p_status IS NULL OR p_status NOT IN ('pending','succeeded','failed','cancelled','refunded','chargeback') THEN
    RAISE EXCEPTION 'invalid_payment_values' USING ERRCODE='22023';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.platform_tenants WHERE tenant_id=p_tenant_id) THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE='P0002';END IF;
  IF p_invoice_id IS NOT NULL THEN
    SELECT * INTO v_invoice FROM public.platform_invoices WHERE id=p_invoice_id FOR UPDATE;
    IF NOT FOUND OR v_invoice.tenant_id<>p_tenant_id THEN RAISE EXCEPTION 'invoice_tenant_mismatch' USING ERRCODE='23514';END IF;
    IF v_invoice.status IN ('cancelled','refunded','draft') THEN RAISE EXCEPTION 'invoice_not_payable' USING ERRCODE='23514';END IF;
    v_currency=v_invoice.currency;
  END IF;
  INSERT INTO public.platform_payments(tenant_id,invoice_id,provider,payment_method,status,amount_cents,currency,paid_at)
    VALUES(p_tenant_id,p_invoice_id,'manual',p_payment_method,p_status,p_amount_cents,v_currency,CASE WHEN p_status='succeeded' THEN now() ELSE NULL END)
    RETURNING * INTO v_row;
  PERFORM public.platform_write_audit_log('payment.recorded','platform_payment',v_row.id,p_tenant_id,NULL,to_jsonb(v_row),trim(p_reason));
  PERFORM public.platform_reconcile_console_invoice(p_invoice_id,trim(p_reason));
  RETURN to_jsonb(v_row);
END $function$

CREATE OR REPLACE FUNCTION public.platform_update_operator_user(p_platform_user_id uuid, p_role text, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_before public.platform_users%ROWTYPE;
  v_after public.platform_users%ROWTYPE;
  v_owner_count INTEGER;
BEGIN
  PERFORM public.platform_assert_capability('users.write');
  PERFORM public.platform_assert_reason(p_reason);
  PERFORM pg_advisory_xact_lock(hashtextextended('platform-owner-membership',0));

  IF p_role IS NULL OR p_role NOT IN ('platform_owner','platform_admin','platform_billing','platform_support','platform_developer','platform_readonly') THEN
    RAISE EXCEPTION 'invalid_platform_role' USING ERRCODE = '22023';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('active','disabled','revoked') THEN
    RAISE EXCEPTION 'invalid_platform_user_status' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_before FROM public.platform_users WHERE id = p_platform_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_user_not_found' USING ERRCODE = 'P0002'; END IF;

  IF v_before.role = 'platform_owner' AND v_before.status = 'active'
     AND (p_role <> 'platform_owner' OR p_status <> 'active') THEN
    SELECT count(*) INTO v_owner_count
    FROM public.platform_users
    WHERE role = 'platform_owner' AND status = 'active';
    IF v_owner_count <= 1 THEN
      RAISE EXCEPTION 'last_platform_owner_protected' USING ERRCODE = '23514';
    END IF;
  END IF;

  UPDATE public.platform_users
  SET role = p_role, status = p_status, updated_at = now()
  WHERE id = p_platform_user_id
  RETURNING * INTO v_after;

  PERFORM public.platform_write_audit_log(
    'platform_user.updated', 'platform_user', v_after.id, NULL,
    jsonb_build_object('role', v_before.role, 'status', v_before.status),
    jsonb_build_object('role', v_after.role, 'status', v_after.status),
    trim(p_reason)
  );
  RETURN jsonb_build_object('ok', TRUE, 'id', v_after.id, 'role', v_after.role, 'status', v_after.status);
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_register_release(p_environment text, p_version_label text, p_commit_sha text, p_status text, p_deployment_url text, p_migration_version text, p_checks jsonb, p_notes text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.platform_release_deployments%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('system.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF p_environment NOT IN ('preview','staging','production') THEN RAISE EXCEPTION 'invalid_environment' USING ERRCODE='22023'; END IF;
  IF p_status NOT IN ('planned','building','ready','failed','rolled_back') THEN RAISE EXCEPTION 'invalid_release_status' USING ERRCODE='22023'; END IF;
  IF length(trim(coalesce(p_version_label,''))) = 0 THEN RAISE EXCEPTION 'version_required' USING ERRCODE='22023'; END IF;

  INSERT INTO public.platform_release_deployments(
    environment, version_label, commit_sha, status, deployment_url,
    migration_version, checks, notes
  ) VALUES (
    p_environment, trim(p_version_label), nullif(trim(p_commit_sha),''), p_status,
    nullif(trim(p_deployment_url),''), nullif(trim(p_migration_version),''),
    coalesce(p_checks,'{}'::jsonb), nullif(trim(p_notes),'')
  ) RETURNING * INTO v_row;

  PERFORM public.platform_write_audit_log(
    'release.registered', 'platform_release', v_row.id, NULL, NULL,
    jsonb_build_object('environment',v_row.environment,'version',v_row.version_label,'status',v_row.status),
    trim(p_reason)
  );
  RETURN to_jsonb(v_row);
END;
$function$

CREATE OR REPLACE FUNCTION public.start_client_offboarding(p_tenant_id uuid, p_client_id uuid, p_termination_kind text, p_notice_date date, p_effective_date date, p_last_service_date date DEFAULT NULL::date, p_reason_category text DEFAULT NULL::text, p_internal_reason text DEFAULT NULL::text, p_external_reason text DEFAULT NULL::text, p_portal_closure_mode text DEFAULT 'effective_date'::text, p_portal_grace_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_legal_hold boolean DEFAULT false, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case public.client_offboarding_cases%ROWTYPE;
BEGIN
  PERFORM public.client_offboarding_assert_admin(p_tenant_id);
  IF p_notice_date IS NULL OR p_effective_date IS NULL OR p_termination_kind IS NULL
     OR NULLIF(BTRIM(p_reason_category),'') IS NULL OR NULLIF(BTRIM(p_internal_reason),'') IS NULL THEN
    RAISE EXCEPTION 'Pflichtangaben zur Kündigung sind unvollständig.';
  END IF;
  IF p_termination_kind IN ('ordinary_by_provider','extraordinary_by_provider')
     AND NULLIF(BTRIM(p_external_reason),'') IS NULL THEN
    RAISE EXCEPTION 'Bei einer Kündigung durch den Leistungserbringer ist eine sachliche externe Begründung Pflicht.';
  END IF;
  IF p_effective_date < p_notice_date AND p_termination_kind NOT IN ('extraordinary_by_client','extraordinary_by_provider','deceased') THEN
    RAISE EXCEPTION 'Das Beendigungsdatum darf bei einer ordentlichen Beendigung nicht vor dem Zugang liegen.';
  END IF;
  IF p_last_service_date IS NOT NULL AND p_last_service_date > p_effective_date THEN
    RAISE EXCEPTION 'Der letzte Leistungstag darf nicht nach dem Beendigungsdatum liegen.';
  END IF;
  IF p_portal_closure_mode = 'read_only_grace' AND p_portal_grace_until IS NULL THEN
    RAISE EXCEPTION 'Für die Portal-Nachfrist ist ein Endzeitpunkt erforderlich.';
  END IF;
  IF p_portal_closure_mode = 'read_only_grace' AND p_portal_grace_until::DATE < p_effective_date THEN
    RAISE EXCEPTION 'Die Portal-Nachfrist darf nicht vor dem Beendigungsdatum enden.';
  END IF;

  SELECT * INTO v_case
  FROM public.client_offboarding_cases
  WHERE tenant_id=p_tenant_id AND client_id=p_client_id AND status<>'completed'
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.client_offboarding_cases(
      tenant_id,client_id,status,termination_kind,notice_date,effective_date,last_service_date,
      reason_category,internal_reason,external_reason,portal_closure_mode,portal_grace_until,
      legal_hold,responsible_user_id,started_at
    ) VALUES(
      p_tenant_id,p_client_id,'in_progress',p_termination_kind,p_notice_date,p_effective_date,
      p_last_service_date,BTRIM(p_reason_category),BTRIM(p_internal_reason),NULLIF(BTRIM(p_external_reason),''),
      p_portal_closure_mode,p_portal_grace_until,p_legal_hold,p_actor_id,NOW()
    ) RETURNING * INTO v_case;
  ELSE
    UPDATE public.client_offboarding_cases SET
      status='in_progress', termination_kind=p_termination_kind, notice_date=p_notice_date,
      effective_date=p_effective_date, last_service_date=p_last_service_date,
      reason_category=BTRIM(p_reason_category), internal_reason=BTRIM(p_internal_reason),
      external_reason=NULLIF(BTRIM(p_external_reason),''), portal_closure_mode=p_portal_closure_mode,
      portal_grace_until=p_portal_grace_until, legal_hold=p_legal_hold,
      final_protocol=NULL,
      responsible_user_id=COALESCE(responsible_user_id,p_actor_id),
      started_at=COALESCE(started_at,NOW()), updated_at=NOW()
    WHERE id=v_case.id RETURNING * INTO v_case;
  END IF;

  PERFORM public.client_offboarding_seed_actions(v_case.id,p_tenant_id,p_client_id);
  UPDATE public.client_offboarding_actions SET status='pending',completed_at=NULL,completed_by=NULL,
    notes='Durch geänderte Kündigungsdaten erneut zu prüfen',updated_at=NOW()
  WHERE case_id=v_case.id AND action_key='create_final_protocol';
  INSERT INTO public.client_offboarding_audit_events(case_id,tenant_id,client_id,action,detail,metadata,actor_id)
  VALUES(v_case.id,p_tenant_id,p_client_id,'termination_recorded','Kündigung und Offboarding verbindlich gestartet',
    jsonb_build_object('termination_kind',p_termination_kind,'notice_date',p_notice_date,'effective_date',p_effective_date),p_actor_id);
  RETURN jsonb_build_object('case_id',v_case.id,'status',v_case.status);
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_client_offboarding_action(p_tenant_id uuid, p_client_id uuid, p_action_key text, p_status text, p_notes text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_case_id UUID;
BEGIN
  PERFORM public.client_offboarding_assert_admin(p_tenant_id);
  IF p_action_key IN ('lock_portal_access','create_final_protocol','archive_client_record') THEN
    RAISE EXCEPTION 'Dieser Schritt darf nur über die verbindliche Systemaktion abgeschlossen werden.';
  END IF;
  IF p_status NOT IN ('pending','in_progress','completed','not_applicable','blocked') THEN
    RAISE EXCEPTION 'Ungültiger Maßnahmenstatus.';
  END IF;
  SELECT id INTO v_case_id FROM public.client_offboarding_cases
  WHERE tenant_id=p_tenant_id AND client_id=p_client_id AND status<>'completed'
  ORDER BY created_at DESC LIMIT 1;
  IF v_case_id IS NULL THEN RAISE EXCEPTION 'Offboarding wurde noch nicht gestartet.'; END IF;
  UPDATE public.client_offboarding_actions SET status=p_status,notes=NULLIF(BTRIM(p_notes),''),
    completed_at=CASE WHEN p_status IN ('completed','not_applicable') THEN NOW() ELSE NULL END,
    completed_by=CASE WHEN p_status IN ('completed','not_applicable') THEN p_actor_id ELSE NULL END,updated_at=NOW()
  WHERE case_id=v_case_id AND action_key=p_action_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unbekannter Offboarding-Schritt.'; END IF;
  UPDATE public.client_offboarding_cases SET final_protocol=NULL,updated_at=NOW() WHERE id=v_case_id;
  UPDATE public.client_offboarding_actions SET status='pending',completed_at=NULL,completed_by=NULL,
    notes='Durch geänderte Abschlussmaßnahme erneut zu erzeugen',updated_at=NOW()
  WHERE case_id=v_case_id AND action_key='create_final_protocol';
  INSERT INTO public.client_offboarding_audit_events(case_id,tenant_id,client_id,action,detail,metadata,actor_id)
  VALUES(v_case_id,p_tenant_id,p_client_id,'action_updated',p_action_key||' → '||p_status,
    jsonb_build_object('notes',p_notes),p_actor_id);
  RETURN jsonb_build_object('case_id',v_case_id,'action_key',p_action_key,'status',p_status);
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_client_offboarding_protocol(p_tenant_id uuid, p_client_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case public.client_offboarding_cases%ROWTYPE;
  v_blockers JSONB;
  v_protocol JSONB;
BEGIN
  PERFORM public.client_offboarding_assert_admin(p_tenant_id);
  SELECT * INTO v_case FROM public.client_offboarding_cases
  WHERE tenant_id=p_tenant_id AND client_id=p_client_id AND status<>'completed'
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Offboarding wurde noch nicht gestartet.'; END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('key',check_key,'message',message,'count',object_count)),'[]'::JSONB)
  INTO v_blockers FROM public.client_offboarding_checks
  WHERE case_id=v_case.id AND severity='required' AND status='failed' AND check_key<>'final_protocol';
  IF jsonb_array_length(v_blockers)>0 THEN
    RAISE EXCEPTION 'Abschlussprotokoll blockiert: %',v_blockers::TEXT;
  END IF;

  v_protocol=jsonb_build_object(
    'version','CareSuite-Client-Offboarding-R17',
    'case_id',v_case.id,'tenant_id',p_tenant_id,'client_id',p_client_id,
    'generated_at',NOW(),'generated_by',p_actor_id,
    'termination_kind',v_case.termination_kind,'notice_date',v_case.notice_date,
    'effective_date',v_case.effective_date,'last_service_date',v_case.last_service_date,
    'reason_category',v_case.reason_category,'legal_hold',v_case.legal_hold,
    'checks',(SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.check_key),'[]'::JSONB) FROM public.client_offboarding_checks c WHERE c.case_id=v_case.id),
    'actions',(SELECT COALESCE(jsonb_agg(to_jsonb(a) ORDER BY a.action_key),'[]'::JSONB) FROM public.client_offboarding_actions a WHERE a.case_id=v_case.id)
  );
  UPDATE public.client_offboarding_cases SET final_protocol=v_protocol,updated_at=NOW() WHERE id=v_case.id;
  UPDATE public.client_offboarding_actions SET status='completed',completed_at=NOW(),completed_by=p_actor_id,
    notes='Revisionssicherer Abschluss-Snapshot erzeugt',updated_at=NOW()
  WHERE case_id=v_case.id AND action_key='create_final_protocol';
  INSERT INTO public.client_offboarding_audit_events(case_id,tenant_id,client_id,action,detail,metadata,actor_id)
  VALUES(v_case.id,p_tenant_id,p_client_id,'protocol_generated','Revisionssicherer Abschluss-Snapshot erzeugt',v_protocol,p_actor_id);
  RETURN jsonb_build_object('case_id',v_case.id,'generated',TRUE);
END;
$function$

CREATE OR REPLACE FUNCTION public.lock_client_offboarding_portal(p_tenant_id uuid, p_client_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_case_id UUID;
BEGIN
  PERFORM public.client_offboarding_assert_admin(p_tenant_id);
  SELECT id INTO v_case_id FROM public.client_offboarding_cases
  WHERE tenant_id=p_tenant_id AND client_id=p_client_id AND status<>'completed'
  ORDER BY created_at DESC LIMIT 1;
  IF v_case_id IS NULL THEN RAISE EXCEPTION 'Offboarding wurde noch nicht gestartet.'; END IF;

  UPDATE public.client_offboarding_cases SET final_protocol=NULL,updated_at=NOW() WHERE id=v_case_id;
  UPDATE public.client_offboarding_actions SET status='pending',completed_at=NULL,completed_by=NULL,
    notes='Nach Portalsperre erneut zu erzeugen',updated_at=NOW()
  WHERE case_id=v_case_id AND action_key='create_final_protocol';

  IF to_regclass('public.client_portal_access') IS NOT NULL THEN
    UPDATE public.client_portal_access SET portal_enabled=FALSE,updated_at=NOW()
    WHERE tenant_id=p_tenant_id AND client_id=p_client_id;
  END IF;
  IF to_regclass('public.portal_push_devices') IS NOT NULL THEN
    UPDATE public.portal_push_devices SET enabled=FALSE,invalidated_at=NOW(),
      last_error='Klient:innen-Offboarding',updated_at=NOW()
    WHERE tenant_id=p_tenant_id AND client_id=p_client_id AND enabled=TRUE;
  END IF;
  UPDATE public.client_offboarding_actions SET status='completed',completed_at=NOW(),
    completed_by=p_actor_id,notes='Portalzugänge und Push-Geräte gesperrt',updated_at=NOW()
  WHERE case_id=v_case_id AND action_key='lock_portal_access';
  INSERT INTO public.client_offboarding_audit_events(case_id,tenant_id,client_id,action,detail,actor_id)
  VALUES(v_case_id,p_tenant_id,p_client_id,'portal_locked','Portalzugänge und Push-Geräte gesperrt',p_actor_id);
  RETURN jsonb_build_object('case_id',v_case_id,'portal_locked',TRUE);
END;
$function$

CREATE OR REPLACE FUNCTION public.support_claim_ticket(p_ticket_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_operator uuid;
BEGIN
  IF NOT public.platform_has_capability('support.write') OR NOT public.support_can_read_ticket(p_ticket_id) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  SELECT id INTO v_operator FROM public.platform_users WHERE user_id=auth.uid() AND status='active';
  UPDATE public.support_workspace_tickets SET assigned_to=v_operator,updated_at=now() WHERE id=p_ticket_id;
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event,details) VALUES(p_ticket_id,auth.uid(),'ticket.assigned',jsonb_build_object('operator',v_operator));
END; $function$

CREATE OR REPLACE FUNCTION public.wfm_apply_clock_action(p_tenant_id uuid, p_employee_id uuid, p_action text, p_work_mode text, p_session_status text, p_display_status text, p_event_type text, p_source text DEFAULT 'portal'::text, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session public.workforce_work_sessions%ROWTYPE;
  v_work_date DATE := (p_occurred_at AT TIME ZONE 'Europe/Berlin')::DATE;
  v_last_clock_out TIMESTAMPTZ;
  v_block_started_at TIMESTAMPTZ;
  v_pause_started_at TIMESTAMPTZ;
  v_pause_ended_at TIMESTAMPTZ;
  v_pause_minutes INTEGER;
  v_gross_minutes INTEGER;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Anmeldung erforderlich.' USING ERRCODE = '42501';
  END IF;

  IF p_employee_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = p_employee_id AND e.tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'Mitarbeitendenzuordnung ist ungültig.' USING ERRCODE = '42501';
  END IF;

  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht mit der Sitzung überein.';
  END IF;

  IF p_action IS NULL OR p_action NOT IN ('clock_in', 'pause', 'resume', 'switch', 'clock_out') THEN
    RAISE EXCEPTION 'Unbekannte Arbeitszeitaktion.';
  END IF;

  IF p_source IS NULL OR p_source NOT IN ('portal', 'office', 'assist', 'system', 'import', 'correction') THEN
    RAISE EXCEPTION 'Unzulässige Quelle.';
  END IF;

  -- Portal accounts have their own authenticated employee link, not an Office profile.
  -- Keep Office's explicit action permissions; portal actors can only stamp for themselves.
  IF (CASE WHEN public.current_portal_type() IS NOT NULL
                 OR public.is_employee_portal_rls_context(p_tenant_id) THEN
    p_source = 'portal'
    AND public.is_employee_portal_rls_context(p_tenant_id)
    AND p_employee_id = public.resolve_current_employee_id()
  ELSE
    (
      p_employee_id = public.resolve_current_employee_id()
      AND (
        (p_action = 'clock_in' AND public.has_permission('time.tracking.own.start'))
        OR (p_action = 'pause' AND public.has_permission('time.tracking.own.pause'))
        OR (p_action = 'resume' AND public.has_permission('time.tracking.own.resume'))
        OR (p_action = 'switch' AND public.has_permission('time.tracking.own.switch'))
        OR (p_action = 'clock_out' AND public.has_permission('time.tracking.own.close'))
      )
    )
    OR public.has_permission('time.tracking.admin.correct')
    OR public.is_tenant_admin()
  END) IS NOT TRUE THEN
    RAISE EXCEPTION 'Keine Berechtigung für diese Arbeitszeitaktion.' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.workforce_work_sessions (
    tenant_id, employee_id, user_id, work_date, status, work_mode,
    display_status, started_at, ended_at, last_event_at, is_online
  )
  SELECT
    p_tenant_id, p_employee_id, auth.uid(), v_work_date,
    'offline', 'none', 'offline',
    NULL, NULL, NULL, FALSE
  WHERE p_action = 'clock_in'
  ON CONFLICT (tenant_id, employee_id, work_date) DO NOTHING;

  SELECT * INTO v_session
  FROM public.workforce_work_sessions
  WHERE tenant_id = p_tenant_id
    AND employee_id = p_employee_id
    AND work_date = v_work_date
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Kein Arbeitstag für diese Aktion vorhanden.';
  END IF;

  IF p_action = 'clock_in' AND v_session.status NOT IN ('offline', 'ended') THEN
    RAISE EXCEPTION 'Es läuft bereits ein Arbeitstag.';
  ELSIF p_action = 'pause' AND v_session.status IN ('offline', 'ended', 'paused') THEN
    RAISE EXCEPTION 'Kein aktiver Arbeitstag zum Pausieren.';
  ELSIF p_action = 'resume' AND v_session.status <> 'paused' THEN
    RAISE EXCEPTION 'Kein pausierter Arbeitstag zum Fortsetzen.';
  ELSIF p_action = 'switch' AND v_session.status IN ('offline', 'ended', 'paused') THEN
    RAISE EXCEPTION 'Kein aktiver Arbeitstag für den Tätigkeitswechsel.';
  ELSIF p_action = 'clock_out' AND v_session.status IN ('offline', 'ended') THEN
    RAISE EXCEPTION 'Kein Arbeitstag zum Abschließen.';
  END IF;

  INSERT INTO public.workforce_time_events (
    tenant_id, employee_id, user_id, event_type, work_mode, source,
    occurred_at, session_id, created_by, metadata
  ) VALUES (
    p_tenant_id, p_employee_id, auth.uid(), p_event_type, p_work_mode, p_source,
    p_occurred_at, v_session.id, auth.uid(),
    jsonb_build_object('atomic_action', p_action, 'integrity_release', 'WFM-R1')
  );

  IF p_action = 'clock_in' THEN
    UPDATE public.workforce_work_sessions
    SET status = p_session_status,
        work_mode = p_work_mode,
        display_status = p_display_status,
        started_at = coalesce(started_at, p_occurred_at),
        ended_at = NULL,
        last_event_at = p_occurred_at,
        is_online = TRUE,
        updated_at = now()
    WHERE id = v_session.id;

  ELSIF p_action = 'pause' THEN
    UPDATE public.workforce_work_sessions
    SET status = 'paused',
        display_status = 'pause',
        last_event_at = p_occurred_at,
        is_online = TRUE,
        updated_at = now()
    WHERE id = v_session.id;

  ELSIF p_action = 'resume' THEN
    SELECT max(occurred_at) FILTER (WHERE event_type = 'pause_start'),
           max(occurred_at) FILTER (WHERE event_type = 'pause_end')
    INTO v_pause_started_at, v_pause_ended_at
    FROM public.workforce_time_events
    WHERE tenant_id = p_tenant_id AND session_id = v_session.id;

    v_pause_minutes := v_session.pause_minutes;
    IF v_pause_started_at IS NOT NULL
       AND (v_pause_ended_at IS NULL OR v_pause_started_at < v_pause_ended_at) THEN
      v_pause_minutes := v_pause_minutes + greatest(
        0,
        floor(extract(epoch FROM (p_occurred_at - v_pause_started_at)) / 60)::INTEGER
      );
    END IF;

    UPDATE public.workforce_work_sessions
    SET status = p_session_status,
        work_mode = p_work_mode,
        display_status = p_display_status,
        pause_minutes = v_pause_minutes,
        last_event_at = p_occurred_at,
        is_online = TRUE,
        updated_at = now()
    WHERE id = v_session.id;

  ELSIF p_action = 'switch' THEN
    UPDATE public.workforce_work_sessions
    SET status = p_session_status,
        work_mode = p_work_mode,
        display_status = p_display_status,
        last_event_at = p_occurred_at,
        is_online = TRUE,
        updated_at = now()
    WHERE id = v_session.id;

  ELSIF p_action = 'clock_out' THEN
    SELECT max(occurred_at) INTO v_last_clock_out
    FROM public.workforce_time_events
    WHERE tenant_id = p_tenant_id
      AND session_id = v_session.id
      AND event_type = 'clock_out'
      AND occurred_at < p_occurred_at;

    SELECT min(occurred_at) INTO v_block_started_at
    FROM public.workforce_time_events
    WHERE tenant_id = p_tenant_id
      AND session_id = v_session.id
      AND event_type IN (
        'clock_in', 'office_check_in', 'homeoffice_start', 'visit_started',
        'standby_start', 'training_start', 'meeting_start', 'travel_start'
      )
      AND (v_last_clock_out IS NULL OR occurred_at > v_last_clock_out)
      AND occurred_at <= p_occurred_at;

    v_gross_minutes := v_session.gross_minutes + greatest(
      0,
      floor(extract(epoch FROM (p_occurred_at - coalesce(v_block_started_at, v_session.last_event_at, p_occurred_at))) / 60)::INTEGER
    );
    v_pause_minutes := v_session.pause_minutes;

    IF v_session.status = 'paused' THEN
      SELECT max(occurred_at) INTO v_pause_started_at
      FROM public.workforce_time_events
      WHERE tenant_id = p_tenant_id
        AND session_id = v_session.id
        AND event_type = 'pause_start'
        AND occurred_at <= p_occurred_at;
      IF v_pause_started_at IS NOT NULL THEN
        v_pause_minutes := v_pause_minutes + greatest(
          0,
          floor(extract(epoch FROM (p_occurred_at - v_pause_started_at)) / 60)::INTEGER
        );
      END IF;
    END IF;

    v_pause_minutes := least(v_pause_minutes, v_gross_minutes);
    UPDATE public.workforce_work_sessions
    SET status = 'ended',
        display_status = 'feierabend',
        ended_at = p_occurred_at,
        last_event_at = p_occurred_at,
        is_online = FALSE,
        gross_minutes = v_gross_minutes,
        pause_minutes = v_pause_minutes,
        net_minutes = greatest(0, v_gross_minutes - v_pause_minutes),
        updated_at = now()
    WHERE id = v_session.id;
  END IF;

  RETURN jsonb_build_object('ok', TRUE, 'session_id', v_session.id, 'work_date', v_work_date);
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_set_tenant_module(p_tenant_id uuid, p_module_key text, p_status text, p_reason text, p_is_trial boolean DEFAULT false, p_trial_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_before JSONB;
  v_after JSONB;
  v_requires TEXT[];
  v_missing TEXT;
BEGIN
  IF NOT public.platform_has_capability('modules.write') THEN
    RAISE EXCEPTION 'platform_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT requires_module_keys INTO v_requires
  FROM public.platform_modules WHERE module_key = p_module_key;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'module_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_status IN ('enabled', 'beta_enabled', 'trial') AND array_length(v_requires, 1) > 0 THEN
    SELECT req INTO v_missing
    FROM unnest(v_requires) AS req
    WHERE NOT EXISTS (
      SELECT 1 FROM public.platform_tenant_modules ptm
      WHERE ptm.tenant_id = p_tenant_id
        AND ptm.module_key = req
        AND ptm.status IN ('enabled', 'beta_enabled', 'trial')
    )
    LIMIT 1;

    IF v_missing IS NOT NULL THEN
      RAISE EXCEPTION 'module_dependency_missing:%', v_missing USING ERRCODE = '23503';
    END IF;
  END IF;

  SELECT row_to_json(ptm)::jsonb INTO v_before
  FROM public.platform_tenant_modules ptm
  WHERE ptm.tenant_id = p_tenant_id AND ptm.module_key = p_module_key;

  INSERT INTO public.platform_tenant_modules (
    tenant_id, module_key, status, enabled_at, disabled_at,
    is_trial, trial_ends_at, manual_override, override_reason, enabled_by, disabled_by
  ) VALUES (
    p_tenant_id, p_module_key, p_status,
    CASE WHEN p_status IN ('enabled', 'beta_enabled', 'trial') THEN NOW() ELSE NULL END,
    CASE WHEN p_status = 'disabled' THEN NOW() ELSE NULL END,
    p_is_trial, p_trial_ends_at, TRUE, p_reason,
    CASE WHEN p_status IN ('enabled', 'beta_enabled', 'trial') THEN auth.uid() ELSE NULL END,
    CASE WHEN p_status = 'disabled' THEN auth.uid() ELSE NULL END
  )
  ON CONFLICT (tenant_id, module_key) DO UPDATE SET
    status = EXCLUDED.status,
    enabled_at = EXCLUDED.enabled_at,
    disabled_at = EXCLUDED.disabled_at,
    is_trial = EXCLUDED.is_trial,
    trial_ends_at = EXCLUDED.trial_ends_at,
    manual_override = TRUE,
    override_reason = EXCLUDED.override_reason,
    enabled_by = EXCLUDED.enabled_by,
    disabled_by = EXCLUDED.disabled_by,
    updated_at = NOW();

  SELECT row_to_json(ptm)::jsonb INTO v_after
  FROM public.platform_tenant_modules ptm
  WHERE ptm.tenant_id = p_tenant_id AND ptm.module_key = p_module_key;

  PERFORM public.platform_write_audit_log(
    CASE WHEN p_status = 'disabled' THEN 'module.disabled' ELSE 'module.enabled' END,
    'platform_tenant_module',
    (v_after->>'id')::uuid,
    p_tenant_id,
    v_before,
    v_after,
    p_reason
  );

  RETURN v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_assign_plan(p_tenant_id uuid, p_plan_key text, p_reason text, p_billing_interval text DEFAULT 'monthly'::text, p_custom_monthly_cents integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_plan public.platform_plans%ROWTYPE;
  v_before JSONB;
  v_after JSONB;
  v_new_id UUID;
BEGIN
  IF NOT public.platform_has_capability('plans.write') THEN
    RAISE EXCEPTION 'platform_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_plan FROM public.platform_plans WHERE plan_key = p_plan_key;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'plan_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT row_to_json(tp)::jsonb INTO v_before
  FROM public.platform_tenant_plans tp
  WHERE tp.tenant_id = p_tenant_id AND tp.status = 'active'
  LIMIT 1;

  UPDATE public.platform_tenant_plans
  SET status = 'cancelled', updated_at = NOW()
  WHERE tenant_id = p_tenant_id AND status = 'active';

  INSERT INTO public.platform_tenant_plans (
    tenant_id, plan_key, status, billing_interval,
    monthly_price_cents, yearly_price_cents, assigned_by
  ) VALUES (
    p_tenant_id, p_plan_key, 'active', p_billing_interval,
    COALESCE(p_custom_monthly_cents, v_plan.monthly_price_cents),
    v_plan.yearly_price_cents,
    auth.uid()
  )
  RETURNING id INTO v_new_id;

  UPDATE public.platform_tenants
  SET plan_key = p_plan_key, updated_at = NOW()
  WHERE tenant_id = p_tenant_id;

  SELECT row_to_json(tp)::jsonb INTO v_after
  FROM public.platform_tenant_plans tp WHERE tp.id = v_new_id;

  PERFORM public.platform_write_audit_log(
    'plan.assigned', 'platform_tenant_plan', v_new_id, p_tenant_id,
    v_before, v_after, p_reason
  );

  RETURN v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_assign_discount(p_tenant_id uuid, p_discount_key text, p_reason text, p_starts_at timestamp with time zone DEFAULT now(), p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_after JSONB;
BEGIN
  IF NOT public.platform_has_capability('discounts.write') THEN
    RAISE EXCEPTION 'platform_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.platform_tenant_discounts (tenant_id, discount_key, status, starts_at, ends_at, applied_by, reason)
  VALUES (p_tenant_id, p_discount_key, 'active', p_starts_at, p_ends_at, auth.uid(), p_reason)
  ON CONFLICT (tenant_id, discount_key) DO UPDATE SET
    status = 'active', starts_at = EXCLUDED.starts_at, ends_at = EXCLUDED.ends_at,
    applied_by = auth.uid(), reason = EXCLUDED.reason, updated_at = NOW()
  RETURNING row_to_json(platform_tenant_discounts)::jsonb INTO v_after;

  PERFORM public.platform_write_audit_log(
    'discount.assigned', 'platform_tenant_discount', (v_after->>'id')::uuid,
    p_tenant_id, NULL, v_after, p_reason
  );

  RETURN v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_remove_discount(p_tenant_id uuid, p_discount_key text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_before JSONB;
  v_after JSONB;
BEGIN
  IF NOT public.platform_has_capability('discounts.write') THEN
    RAISE EXCEPTION 'platform_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT row_to_json(d)::jsonb INTO v_before
  FROM public.platform_tenant_discounts d
  WHERE d.tenant_id = p_tenant_id AND d.discount_key = p_discount_key;

  UPDATE public.platform_tenant_discounts
  SET status = 'revoked', updated_at = NOW()
  WHERE tenant_id = p_tenant_id AND discount_key = p_discount_key
  RETURNING row_to_json(platform_tenant_discounts)::jsonb INTO v_after;

  PERFORM public.platform_write_audit_log(
    'discount.removed', 'platform_tenant_discount', (v_after->>'id')::uuid,
    p_tenant_id, v_before, v_after, p_reason
  );

  RETURN v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_end_support_session(p_session_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_before JSONB;
  v_after JSONB;
  v_tenant_id UUID;
BEGIN
  IF NOT public.platform_has_capability('support.write') THEN
    RAISE EXCEPTION 'platform_forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT row_to_json(s)::jsonb, s.tenant_id INTO v_before, v_tenant_id
  FROM public.platform_support_sessions s WHERE s.id = p_session_id;

  UPDATE public.platform_support_sessions
  SET status = 'closed', ends_at = NOW()
  WHERE id = p_session_id
  RETURNING row_to_json(platform_support_sessions)::jsonb INTO v_after;

  PERFORM public.platform_write_audit_log(
    'support_session.ended', 'platform_support_session', p_session_id,
    v_tenant_id, v_before, v_after, p_reason
  );

  RETURN v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_portal_request_wfm_absence(p_tenant_id uuid, p_absence_type text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_all_day boolean DEFAULT true, p_requested_days numeric DEFAULT NULL::numeric, p_employee_note text DEFAULT ''::text)
 RETURNS SETOF workforce_absences
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_employee_id UUID;
  v_absence public.workforce_absences;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Nicht angemeldet.' USING ERRCODE = '42501';
  END IF;
  IF p_tenant_id IS NULL OR p_starts_at IS NULL OR p_ends_at IS NULL OR p_ends_at < p_starts_at THEN
    RAISE EXCEPTION 'Ungültiger Abwesenheitszeitraum.' USING ERRCODE = '22023';
  END IF;

  v_employee_id := public.resolve_employee_id_for_tenant(p_tenant_id);
  IF v_employee_id IS NULL OR NOT public.is_active_employee_portal_actor(p_tenant_id) THEN
    RAISE EXCEPTION 'Portalzugang ist keinem aktiven Mitarbeitenden zugeordnet.' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.workforce_absences (
    tenant_id, employee_id, absence_type, status, starts_at, ends_at,
    all_day, requested_days, employee_note, internal_note, created_by
  ) VALUES (
    p_tenant_id, v_employee_id, p_absence_type, 'requested', p_starts_at, p_ends_at,
    COALESCE(p_all_day, TRUE), p_requested_days, COALESCE(p_employee_note, ''), '', auth.uid()
  ) RETURNING * INTO v_absence;

  INSERT INTO public.workforce_approvals (
    tenant_id, employee_id, approval_type, status, reference_type,
    reference_id, requested_by, payload
  ) VALUES (
    p_tenant_id,
    v_employee_id,
    CASE WHEN p_absence_type = 'vacation' THEN 'vacation' ELSE 'absence' END,
    'pending',
    'workforce_absence',
    v_absence.id,
    auth.uid(),
    jsonb_build_object(
      'absenceType', p_absence_type,
      'startsAt', p_starts_at,
      'endsAt', p_ends_at
    )
  );

  RETURN NEXT v_absence;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_portal_withdraw_wfm_absence(p_tenant_id uuid, p_absence_id uuid)
 RETURNS SETOF workforce_absences
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_employee_id UUID;
  v_absence public.workforce_absences;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Nicht angemeldet.' USING ERRCODE = '42501';
  END IF;
  v_employee_id := public.resolve_employee_id_for_tenant(p_tenant_id);
  IF v_employee_id IS NULL OR NOT public.is_active_employee_portal_actor(p_tenant_id) THEN
    RAISE EXCEPTION 'Portalzugang ist keinem aktiven Mitarbeitenden zugeordnet.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.workforce_absences
  SET status = 'cancelled', updated_at = NOW()
  WHERE id = p_absence_id
    AND tenant_id = p_tenant_id
    AND employee_id = v_employee_id
    AND status = 'requested'
  RETURNING * INTO v_absence;

  IF v_absence.id IS NULL THEN
    RAISE EXCEPTION 'Antrag nicht gefunden oder bereits bearbeitet.' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.workforce_approvals
  SET status = 'cancelled', updated_at = NOW()
  WHERE tenant_id = p_tenant_id
    AND employee_id = v_employee_id
    AND reference_type = 'workforce_absence'
    AND reference_id = p_absence_id
    AND status = 'pending';

  RETURN NEXT v_absence;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_create_discount(p_discount_key text, p_name text, p_discount_type text, p_value numeric, p_description text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.platform_discounts%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('discounts.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF trim(coalesce(p_discount_key,'')) !~ '^[a-z0-9_-]{3,}$' THEN RAISE EXCEPTION 'invalid_discount_key' USING ERRCODE='22023'; END IF;
  IF length(trim(coalesce(p_name,''))) < 2 THEN RAISE EXCEPTION 'discount_name_required' USING ERRCODE='22023'; END IF;
  IF p_discount_type NOT IN ('percentage','fixed_amount','free_months','lifetime_discount','beta_discount','manual_credit','goodwill_credit','partner_discount') THEN RAISE EXCEPTION 'invalid_discount_type' USING ERRCODE='22023'; END IF;
  IF p_value IS NULL OR p_value < 0 THEN RAISE EXCEPTION 'invalid_discount_value' USING ERRCODE='22023'; END IF;
  INSERT INTO public.platform_discounts(discount_key,name,description,discount_type,percentage,amount_cents,free_months,created_by)
  VALUES(trim(p_discount_key),trim(p_name),nullif(trim(p_description),''),p_discount_type,
    CASE WHEN p_discount_type IN ('percentage','lifetime_discount','beta_discount','partner_discount') THEN p_value ELSE NULL END,
    CASE WHEN p_discount_type IN ('fixed_amount','manual_credit','goodwill_credit') THEN round(p_value)::INTEGER ELSE NULL END,
    CASE WHEN p_discount_type='free_months' THEN round(p_value)::INTEGER ELSE NULL END, auth.uid())
  RETURNING * INTO v_row;
  PERFORM public.platform_write_audit_log('discount.created','platform_discount',v_row.id,NULL,NULL,to_jsonb(v_row),trim(p_reason));
  RETURN to_jsonb(v_row);
END $function$

CREATE OR REPLACE FUNCTION public.platform_create_manual_invoice(p_tenant_id uuid, p_total_cents integer, p_tax_cents integer, p_due_date date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.platform_invoices%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('billing.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF p_total_cents <= 0 OR p_tax_cents < 0 OR p_tax_cents > p_total_cents THEN RAISE EXCEPTION 'invalid_invoice_amounts' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.platform_tenants WHERE tenant_id=p_tenant_id) THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE='P0002'; END IF;
  INSERT INTO public.platform_invoices(tenant_id,invoice_number,provider,status,subtotal_cents,tax_cents,total_cents,due_date,issued_at)
  VALUES(p_tenant_id,'CS-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),'manual','open',p_total_cents-p_tax_cents,p_tax_cents,p_total_cents,p_due_date,now())
  RETURNING * INTO v_row;
  PERFORM public.platform_write_audit_log('invoice.created','platform_invoice',v_row.id,p_tenant_id,NULL,to_jsonb(v_row),trim(p_reason));
  RETURN to_jsonb(v_row);
END $function$

CREATE OR REPLACE FUNCTION public.create_care_quality_deviation(p_client_id uuid, p_care_plan_id uuid, p_payload jsonb)
 RETURNS care_quality_deviations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.care_quality_deviations; t UUID:=public.current_tenant_id();
BEGIN
 IF NOT public.has_permission('pflege.deviations.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 IF p_client_id IS NOT NULL AND NOT public.is_active_pfleger_client(p_client_id) THEN RAISE EXCEPTION 'Kein aktiver Pflegefall.' USING ERRCODE='23514'; END IF;
 IF trim(COALESCE(p_payload->>'title',''))='' OR trim(COALESCE(p_payload->>'description',''))='' THEN RAISE EXCEPTION 'Titel und Beschreibung sind erforderlich.' USING ERRCODE='23514'; END IF;
 INSERT INTO public.care_quality_deviations(tenant_id,client_id,care_plan_id,source_type,source_id,category,severity,title,description,
  immediate_action,recurring_problem,created_by,created_by_name,updated_by,updated_by_name)
 VALUES(t,p_client_id,p_care_plan_id,COALESCE(NULLIF(p_payload->>'sourceType',''),'other'),NULLIF(p_payload->>'sourceId','')::UUID,
  trim(p_payload->>'category'),COALESCE(NULLIF(p_payload->>'severity',''),'medium'),trim(p_payload->>'title'),trim(p_payload->>'description'),
  COALESCE(p_payload->>'immediateAction',''),COALESCE((p_payload->>'recurringProblem')::BOOLEAN,FALSE),public.clinical_actor_id(),public.clinical_actor_name(),public.clinical_actor_id(),public.clinical_actor_name()) RETURNING * INTO r;
 INSERT INTO public.care_audit_events(tenant_id,client_id,care_plan_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name)
 VALUES(t,p_client_id,p_care_plan_id,'care_quality_deviation',r.id,'identified','Qualitätsabweichung festgestellt.',to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.platform_create_addon(p_addon_key text, p_addon_name text, p_reason text, p_description text DEFAULT NULL::text, p_monthly_price_cents integer DEFAULT 0, p_yearly_price_cents integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_addon public.platform_addons%ROWTYPE; v_version_id UUID;
BEGIN
  PERFORM public.platform_assert_capability('plans.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF p_addon_key !~ '^[a-z][a-z0-9_]{2,63}$' THEN RAISE EXCEPTION 'invalid_addon_key'; END IF;
  INSERT INTO public.platform_addons (addon_key, addon_name, description)
  VALUES (p_addon_key, BTRIM(p_addon_name), NULLIF(BTRIM(p_description), '')) RETURNING * INTO v_addon;
