$function$

CREATE OR REPLACE FUNCTION public.platform_update_addon(p_addon_key text, p_reason text, p_addon_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before JSONB; v_after JSONB;
BEGIN
  PERFORM public.platform_assert_capability('plans.write');
  PERFORM public.platform_assert_reason(p_reason);
  SELECT to_jsonb(a) INTO v_before FROM public.platform_addons a WHERE a.addon_key = p_addon_key;
  IF v_before IS NULL THEN RAISE EXCEPTION 'addon_not_found' USING ERRCODE = 'P0002'; END IF;
  UPDATE public.platform_addons SET
    addon_name = COALESCE(NULLIF(BTRIM(p_addon_name), ''), addon_name),
    description = CASE WHEN p_description IS NULL THEN description ELSE NULLIF(BTRIM(p_description), '') END,
    status = COALESCE(p_status, status), updated_at = NOW()
  WHERE addon_key = p_addon_key RETURNING to_jsonb(platform_addons) INTO v_after;
  PERFORM public.platform_write_audit_log('addon.updated', 'platform_addon', (v_after->>'id')::uuid, NULL, v_before, v_after, p_reason);
  RETURN v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_create_addon_version(p_addon_key text, p_reason text, p_monthly_price_cents integer, p_yearly_price_cents integer, p_effective_from timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_next INTEGER; v_new public.platform_addon_versions%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('plans.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF NOT EXISTS (SELECT 1 FROM public.platform_addons WHERE addon_key = p_addon_key) THEN
    RAISE EXCEPTION 'addon_not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next FROM public.platform_addon_versions WHERE addon_key = p_addon_key;
  UPDATE public.platform_addon_versions SET status = 'superseded', effective_until = p_effective_from
  WHERE addon_key = p_addon_key AND status = 'active';
  INSERT INTO public.platform_addon_versions (addon_key, version_number, monthly_price_cents, yearly_price_cents, effective_from)
  VALUES (p_addon_key, v_next, GREATEST(p_monthly_price_cents, 0), GREATEST(p_yearly_price_cents, 0), p_effective_from)
  RETURNING * INTO v_new;
  PERFORM public.platform_write_audit_log('addon.version_created', 'platform_addon_version', v_new.id, NULL, NULL, to_jsonb(v_new), p_reason);
  RETURN to_jsonb(v_new);
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_assign_addon_to_tenant(p_tenant_id uuid, p_addon_key text, p_reason text, p_billing_interval text DEFAULT 'monthly'::text, p_price_override_cents integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_version_id UUID; v_row public.platform_tenant_addons%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('plans.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF p_billing_interval NOT IN ('monthly', 'yearly') THEN RAISE EXCEPTION 'invalid_billing_interval'; END IF;
  SELECT av.id INTO v_version_id FROM public.platform_addon_versions av
  WHERE av.addon_key = p_addon_key AND av.status = 'active' ORDER BY av.version_number DESC LIMIT 1;
  IF v_version_id IS NULL THEN RAISE EXCEPTION 'active_addon_version_not_found' USING ERRCODE = 'P0002'; END IF;
  INSERT INTO public.platform_tenant_addons (
    tenant_id, addon_key, addon_version_id, status, billing_interval, price_override_cents, assigned_by, reason
  ) VALUES (p_tenant_id, p_addon_key, v_version_id, 'active', p_billing_interval, p_price_override_cents, auth.uid(), p_reason)
  ON CONFLICT (tenant_id, addon_key) DO UPDATE SET
    addon_version_id = EXCLUDED.addon_version_id, status = 'active', billing_interval = EXCLUDED.billing_interval,
    price_override_cents = EXCLUDED.price_override_cents, ends_at = NULL, assigned_by = EXCLUDED.assigned_by,
    reason = EXCLUDED.reason, updated_at = NOW()
  RETURNING * INTO v_row;
  INSERT INTO public.platform_tenant_addon_events (tenant_addon_id, tenant_id, event_type, payload, actor_user_id, reason)
  VALUES (v_row.id, p_tenant_id, 'assigned', jsonb_build_object('addonKey', p_addon_key), auth.uid(), p_reason);
  IF to_regprocedure('public.platform_recalculate_tenant_entitlements(uuid,text)') IS NOT NULL THEN
    EXECUTE 'SELECT public.platform_recalculate_tenant_entitlements($1, $2)' USING p_tenant_id, p_reason;
  END IF;
  PERFORM public.platform_write_audit_log('addon.assigned', 'platform_tenant_addon', v_row.id, p_tenant_id, NULL, to_jsonb(v_row), p_reason);
  RETURN to_jsonb(v_row);
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_remove_addon_from_tenant(p_tenant_id uuid, p_addon_key text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before JSONB; v_row_id UUID;
BEGIN
  PERFORM public.platform_assert_capability('plans.write');
  PERFORM public.platform_assert_reason(p_reason);
  SELECT to_jsonb(ta), ta.id INTO v_before, v_row_id FROM public.platform_tenant_addons ta
  WHERE ta.tenant_id = p_tenant_id AND ta.addon_key = p_addon_key;
  UPDATE public.platform_tenant_addons SET status = 'cancelled', ends_at = NOW(), updated_at = NOW()
  WHERE tenant_id = p_tenant_id AND addon_key = p_addon_key AND status = 'active';
  IF v_row_id IS NOT NULL THEN
    INSERT INTO public.platform_tenant_addon_events (tenant_addon_id, tenant_id, event_type, payload, actor_user_id, reason)
    VALUES (v_row_id, p_tenant_id, 'removed', jsonb_build_object('addonKey', p_addon_key), auth.uid(), p_reason);
  END IF;
  IF to_regprocedure('public.platform_recalculate_tenant_entitlements(uuid,text)') IS NOT NULL THEN
    EXECUTE 'SELECT public.platform_recalculate_tenant_entitlements($1, $2)' USING p_tenant_id, p_reason;
  END IF;
  PERFORM public.platform_write_audit_log('addon.removed', 'platform_tenant_addon', v_row_id, p_tenant_id, v_before, NULL, p_reason);
  RETURN jsonb_build_object('removed', v_before IS NOT NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_update_tenant_record(p_tenant_id uuid, p_reason text, p_legal_name text DEFAULT NULL::text, p_slug text DEFAULT NULL::text, p_primary_contact_name text DEFAULT NULL::text, p_primary_contact_email text DEFAULT NULL::text, p_primary_contact_phone text DEFAULT NULL::text, p_billing_email text DEFAULT NULL::text, p_support_email text DEFAULT NULL::text, p_country text DEFAULT 'DE'::text, p_timezone text DEFAULT 'Europe/Berlin'::text, p_environment_mode text DEFAULT NULL::text, p_environment_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before JSONB; v_after JSONB;
BEGIN
  PERFORM public.platform_assert_capability('tenants.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF p_environment_mode NOT IN ('production', 'pilot', 'demo', 'sandbox', 'internal_test') THEN
    RAISE EXCEPTION 'invalid_environment_mode' USING ERRCODE = '22023';
  END IF;
  SELECT to_jsonb(pt) INTO v_before FROM public.platform_tenants pt WHERE pt.tenant_id = p_tenant_id FOR UPDATE;
  IF v_before IS NULL THEN RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = 'P0002'; END IF;
  UPDATE public.platform_tenants SET
    legal_name = NULLIF(BTRIM(p_legal_name), ''), slug = NULLIF(BTRIM(p_slug), ''),
    primary_contact_name = NULLIF(BTRIM(p_primary_contact_name), ''),
    primary_contact_email = NULLIF(BTRIM(p_primary_contact_email), ''),
    primary_contact_phone = NULLIF(BTRIM(p_primary_contact_phone), ''),
    billing_email = NULLIF(BTRIM(p_billing_email), ''), support_email = NULLIF(BTRIM(p_support_email), ''),
    country = COALESCE(NULLIF(UPPER(BTRIM(p_country)), ''), 'DE'),
    timezone = COALESCE(NULLIF(BTRIM(p_timezone), ''), 'Europe/Berlin'), updated_at = NOW()
  WHERE tenant_id = p_tenant_id;
  INSERT INTO public.tenant_environment_settings (
    tenant_id, mode, is_pilot_tenant, provider_sandbox_only, notes
  ) VALUES (
    p_tenant_id, p_environment_mode, p_environment_mode = 'pilot',
    p_environment_mode IN ('demo', 'sandbox', 'internal_test', 'pilot'), NULLIF(BTRIM(p_environment_notes), '')
  ) ON CONFLICT (tenant_id) DO UPDATE SET
    mode = EXCLUDED.mode, is_pilot_tenant = EXCLUDED.is_pilot_tenant,
    provider_sandbox_only = EXCLUDED.provider_sandbox_only, notes = EXCLUDED.notes, updated_at = NOW();
  SELECT to_jsonb(pt) || jsonb_build_object('environmentMode', tes.mode, 'environmentNotes', tes.notes)
  INTO v_after FROM public.platform_tenants pt JOIN public.tenant_environment_settings tes ON tes.tenant_id = pt.tenant_id
  WHERE pt.tenant_id = p_tenant_id;
  PERFORM public.platform_write_audit_log('tenant.record_updated', 'platform_tenant', (v_before->>'id')::uuid,
    p_tenant_id, v_before, v_after, p_reason);
  RETURN v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_wfm_team_meeting(p_tenant_id uuid, p_meeting_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_meeting public.workforce_team_meetings%ROWTYPE;
  v_booked INTEGER := 0;
BEGIN
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht mit der Sitzung ├╝berein.';
  END IF;
  IF NOT (public.has_permission('time.settings.manage') OR public.is_tenant_admin()) THEN
    RAISE EXCEPTION 'Keine Berechtigung zum Abschlie├ƒen des Team-Meetings.';
  END IF;

  SELECT * INTO v_meeting
  FROM public.workforce_team_meetings
  WHERE tenant_id = p_tenant_id AND id = p_meeting_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Team-Meeting nicht gefunden.';
  END IF;
  IF v_meeting.status = 'cancelled' THEN
    RAISE EXCEPTION 'Abgesagtes Team-Meeting kann nicht gebucht werden.';
  END IF;

  IF v_meeting.counts_as_work_time THEN
    WITH attendees_to_book AS (
      SELECT attendee.employee_id
      FROM public.workforce_team_meeting_attendees attendee
      WHERE attendee.tenant_id = p_tenant_id
        AND attendee.meeting_id = p_meeting_id
        AND attendee.booked_at IS NULL
      FOR UPDATE
    ), inserted_events AS (
      INSERT INTO public.workforce_time_events (
        tenant_id, employee_id, event_type, work_mode, source,
        occurred_at, note, metadata, created_by
      )
      SELECT
        p_tenant_id,
        attendee.employee_id,
        event.event_type,
        'office',
        'office',
        event.occurred_at,
        v_meeting.title,
        jsonb_build_object('meeting_id', p_meeting_id, 'source', 'team_meeting'),
        p_actor_id
      FROM attendees_to_book attendee
      CROSS JOIN LATERAL (
        VALUES
          ('meeting_start'::TEXT, v_meeting.starts_at),
          ('meeting_end'::TEXT, v_meeting.ends_at)
      ) AS event(event_type, occurred_at)
      RETURNING employee_id
    )
    SELECT COUNT(DISTINCT employee_id) INTO v_booked FROM inserted_events;

    UPDATE public.workforce_team_meeting_attendees
    SET attendance_status = 'attended', booked_at = now()
    WHERE tenant_id = p_tenant_id
      AND meeting_id = p_meeting_id
      AND booked_at IS NULL;
  END IF;

  UPDATE public.workforce_team_meetings
  SET status = 'completed', updated_at = now()
  WHERE tenant_id = p_tenant_id AND id = p_meeting_id;

  RETURN jsonb_build_object('ok', TRUE, 'booked_attendees', v_booked);
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_decide_payroll_statement(p_statement_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS payroll_month_statements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  row public.payroll_month_statements;
  own_employee UUID := public.resolve_current_employee_id();
BEGIN
  IF p_decision NOT IN ('confirm','reject') THEN
    RAISE EXCEPTION 'Ungültige Entscheidung.';
  END IF;
  SELECT * INTO row FROM public.payroll_month_statements
  WHERE id = p_statement_id FOR UPDATE;
  IF row.id IS NULL OR row.tenant_id <> public.current_tenant_id() OR row.employee_id <> own_employee THEN
    RAISE EXCEPTION 'Abrechnung nicht gefunden oder nicht berechtigt.';
  END IF;
  IF row.status <> 'published' THEN
    RAISE EXCEPTION 'Diese Abrechnung kann nicht mehr beantwortet werden.';
  END IF;
  IF p_decision = 'reject' AND char_length(trim(COALESCE(p_reason,''))) < 10 THEN
    RAISE EXCEPTION 'Bitte geben Sie einen konkreten Ablehnungsgrund mit mindestens 10 Zeichen an.';
  END IF;

  UPDATE public.payroll_month_statements SET
    status = CASE WHEN p_decision = 'confirm' THEN 'confirmed' ELSE 'rejected' END,
    employee_decision_reason = CASE WHEN p_decision = 'reject' THEN trim(p_reason) ELSE NULL END,
    confirmed_at = CASE WHEN p_decision = 'confirm' THEN NOW() ELSE NULL END,
    rejected_at = CASE WHEN p_decision = 'reject' THEN NOW() ELSE NULL END,
    updated_at = NOW()
  WHERE id = p_statement_id RETURNING * INTO row;

  INSERT INTO public.payroll_month_audit_log
    (tenant_id, statement_id, employee_id, action, actor_id, summary, metadata)
  VALUES
    (row.tenant_id, row.id, row.employee_id,
     CASE WHEN p_decision = 'confirm' THEN 'employee_confirmed' ELSE 'employee_rejected' END,
     auth.uid(),
     CASE WHEN p_decision = 'confirm' THEN 'Mitarbeitende:r hat die Monatsübersicht bestätigt.' ELSE 'Mitarbeitende:r hat die Monatsübersicht abgelehnt.' END,
     jsonb_build_object('reason', p_reason, 'version', row.version));
  RETURN row;
END;
$function$

CREATE OR REPLACE FUNCTION public.transition_care_assessment(p_assessment_id uuid, p_new_status text, p_actor_name text DEFAULT ''::text)
 RETURNS care_assessments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.care_assessments;
  old_status TEXT;
  topic_count INTEGER;
  risk_errors INTEGER;
  uncovered INTEGER;
  snapshot JSONB;
BEGIN
  SELECT * INTO v FROM public.care_assessments
  WHERE id = p_assessment_id AND tenant_id = public.current_tenant_id() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SIS / Assessment wurde nicht gefunden.'; END IF;
  IF NOT public.can_manage_care_assessment(v.subject_type) THEN RAISE EXCEPTION 'Keine Berechtigung.'; END IF;
  old_status := v.status;
  SELECT COUNT(*) INTO topic_count FROM public.care_assessment_topics
    WHERE assessment_id = v.id AND (trim(resources) <> '' OR trim(impairments) <> '' OR trim(professional_assessment) <> '');
  SELECT COUNT(*) INTO risk_errors FROM public.care_assessment_risks
    WHERE assessment_id = v.id AND risk_state IN ('unclear','present')
      AND (trim(professional_rationale) = '' OR trim(counseling_provided) = '');
  SELECT COUNT(*) INTO uncovered FROM public.care_assessment_risks r
    WHERE r.assessment_id = v.id AND r.risk_state IN ('unclear','present')
      AND NOT EXISTS (SELECT 1 FROM public.care_assessment_measures m
        WHERE m.assessment_id = r.assessment_id AND m.related_risk_key = r.risk_key
          AND m.status IN ('planned','active'));
  IF p_new_status IN ('professional_review','approved') THEN
    IF trim(v.person_statement) = '' AND v.statement_source <> 'not_possible' THEN RAISE EXCEPTION 'Originalton fehlt.'; END IF;
    IF trim(v.professional_summary) = '' THEN RAISE EXCEPTION 'Gesamteinsch├ñtzung fehlt.'; END IF;
    IF topic_count < 6 THEN RAISE EXCEPTION 'Nicht alle sechs Themenfelder sind eingesch├ñtzt.'; END IF;
    IF risk_errors > 0 THEN RAISE EXCEPTION 'Risiken sind nicht vollst├ñndig begr├╝ndet oder beraten.'; END IF;
    IF uncovered > 0 THEN RAISE EXCEPTION 'Risiken besitzen keine aktive Ma├ƒnahme.'; END IF;
  END IF;
  IF p_new_status = 'approved' AND (old_status <> 'professional_review' OR v.next_review_at IS NULL) THEN
    RAISE EXCEPTION 'Freigabe erfordert fachliche Pr├╝fung und Pr├╝ftermin.';
  END IF;
  UPDATE public.care_assessments SET
    status = p_new_status,
    completed_at = CASE WHEN p_new_status IN ('professional_review','approved') THEN COALESCE(completed_at,NOW()) ELSE completed_at END,
    approved_at = CASE WHEN p_new_status = 'approved' THEN NOW() ELSE approved_at END,
    effective_at = CASE WHEN p_new_status = 'approved' THEN COALESCE(effective_at,NOW()) ELSE effective_at END,
    approver_profile_id = CASE WHEN p_new_status = 'approved' THEN auth.uid() ELSE approver_profile_id END,
    approver_name_snapshot = CASE WHEN p_new_status = 'approved' THEN COALESCE(NULLIF(p_actor_name,''),approver_name_snapshot) ELSE approver_name_snapshot END,
    qpr_rating = CASE WHEN p_new_status = 'approved' THEN 'A' ELSE qpr_rating END,
    completeness_percent = CASE WHEN p_new_status IN ('professional_review','approved') THEN 100 ELSE completeness_percent END,
    updated_by = auth.uid(), updated_at = NOW()
  WHERE id = v.id RETURNING * INTO v;
  snapshot := jsonb_build_object(
    'assessment', to_jsonb(v),
    'topics', COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM public.care_assessment_topics t WHERE t.assessment_id=v.id),'[]'),
    'risks', COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM public.care_assessment_risks r WHERE r.assessment_id=v.id),'[]'),
    'measures', COALESCE((SELECT jsonb_agg(to_jsonb(m)) FROM public.care_assessment_measures m WHERE m.assessment_id=v.id),'[]')
  );
  INSERT INTO public.care_assessment_versions (
    tenant_id, assessment_id, version, transition_from, transition_to, snapshot, created_by, actor_name
  ) VALUES (v.tenant_id,v.id,v.version,old_status,p_new_status,snapshot,auth.uid(),COALESCE(p_actor_name,''))
  ON CONFLICT (assessment_id,version,transition_to) DO UPDATE SET snapshot=EXCLUDED.snapshot, actor_name=EXCLUDED.actor_name;
  RETURN v;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_request_assist_visit_signature(p_visit_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.assist_visits%ROWTYPE; v_request_id uuid;
BEGIN
  IF NOT public.has_permission('assist.execution.manage') THEN RAISE EXCEPTION 'Keine Berechtigung'; END IF;
  IF length(trim(coalesce(p_reason,''))) = 0 THEN RAISE EXCEPTION 'Begr├╝ndung ist erforderlich'; END IF;
  SELECT * INTO v FROM public.assist_visits WHERE id=p_visit_id AND tenant_id=public.current_tenant_id() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden'; END IF;
  SELECT id INTO v_request_id FROM public.assist_visit_signature_requests
   WHERE tenant_id=v.tenant_id AND visit_id=v.id AND status='open';
  IF v_request_id IS NULL THEN
    INSERT INTO public.assist_visit_signature_requests(
      tenant_id,visit_id,client_id,service_date,service_name,planned_start_at,planned_end_at,
      actual_start_at,actual_end_at,proof_preview)
    VALUES(v.tenant_id,v.id,v.client_id,v.assignment_date,coalesce(nullif(v.service_name,''),v.title),
      v.planned_start_at,v.planned_end_at,v.actual_start_at,v.actual_end_at,
      jsonb_build_object('visit_id',v.id,'service_date',v.assignment_date,'service',coalesce(nullif(v.service_name,''),v.title),
        'planned_start_at',v.planned_start_at,'planned_end_at',v.planned_end_at,
        'actual_start_at',v.actual_start_at,'actual_end_at',v.actual_end_at)) RETURNING id INTO v_request_id;
    UPDATE public.assist_visits SET proof_status='pending', updated_by=auth.uid(), updated_at=now() WHERE id=v.id;
    INSERT INTO public.assist_visit_admin_audit(tenant_id,visit_id,action,new_value,reason)
    VALUES(v.tenant_id,v.id,'signature_requested',jsonb_build_object('request_id',v_request_id),p_reason);
  END IF;
  RETURN v_request_id;
END $function$

CREATE OR REPLACE FUNCTION public.admin_update_assist_visit_task(p_visit_id uuid, p_task_id uuid, p_status text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_old text;
BEGIN
  IF NOT public.has_permission('assist.execution.manage') THEN RAISE EXCEPTION 'Keine Berechtigung'; END IF;
  IF p_status NOT IN ('open','done','partial','not_requested','not_possible','cancelled','deferred') THEN RAISE EXCEPTION 'Ung├╝ltiger Aufgabenstatus'; END IF;
  IF length(trim(coalesce(p_reason,'')))=0 THEN RAISE EXCEPTION 'Begr├╝ndung ist erforderlich'; END IF;
  SELECT v.tenant_id,t.status INTO v_tenant,v_old FROM public.assist_visits v JOIN public.assist_visit_tasks t
    ON t.visit_id=v.id AND t.tenant_id=v.tenant_id WHERE v.id=p_visit_id AND t.id=p_task_id
    AND v.tenant_id=public.current_tenant_id() FOR UPDATE OF t;
  IF NOT FOUND THEN RAISE EXCEPTION 'Aufgabe nicht gefunden'; END IF;
  UPDATE public.assist_visit_tasks SET status=p_status,
    not_done_reason=CASE WHEN p_status='done' THEN NULL ELSE p_reason END,
    completed_at=CASE WHEN p_status='done' THEN now() ELSE NULL END,updated_at=now() WHERE id=p_task_id AND tenant_id=v_tenant;
  INSERT INTO public.assist_visit_admin_audit(tenant_id,visit_id,action,previous_value,new_value,reason)
  VALUES(v_tenant,p_visit_id,'task_updated',jsonb_build_object('task_id',p_task_id,'status',v_old),jsonb_build_object('task_id',p_task_id,'status',p_status),p_reason);
END $function$

CREATE OR REPLACE FUNCTION public.admin_bulk_update_assist_visit_tasks(p_visit_id uuid, p_updates jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_visit public.assist_visits%ROWTYPE;
  v_assignment_id UUID;
  v_item JSONB;
  v_source_id UUID;
  v_visit_task_id UUID;
  v_assignment_task_id UUID;
  v_title TEXT;
  v_sort_order INTEGER;
  v_status TEXT;
  v_assignment_status TEXT;
  v_old_visit_status TEXT;
  v_old_assignment_status TEXT;
  v_old_visible_status TEXT;
  v_changed BOOLEAN;
  v_match JSONB;
  v_updated INTEGER := 0;
  v_skipped INTEGER := 0;
BEGIN
  IF NOT (
    public.is_tenant_admin()
    OR public.has_permission('assist.execution.manage')
  ) THEN
    RAISE EXCEPTION 'Keine Berechtigung für administrative Nachbearbeitung';
  END IF;

  IF length(trim(coalesce(p_reason, ''))) = 0 THEN
    RAISE EXCEPTION 'Begründung ist erforderlich';
  END IF;

  IF p_updates IS NULL
     OR jsonb_typeof(p_updates) <> 'array'
     OR jsonb_array_length(p_updates) = 0 THEN
    RAISE EXCEPTION 'Keine Aufgabenänderungen übergeben';
  END IF;

  SELECT *
  INTO v_visit
  FROM public.assist_visits
  WHERE id = p_visit_id
    AND tenant_id = public.current_tenant_id()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Einsatz nicht gefunden';
  END IF;

  v_assignment_id := coalesce(v_visit.legacy_assignment_id, v_visit.id);

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_updates)
  LOOP
    v_source_id := NULL;
    v_visit_task_id := NULL;
    v_assignment_task_id := NULL;
    v_title := NULL;
    v_sort_order := NULL;
    v_old_visit_status := NULL;
    v_old_assignment_status := NULL;
    v_changed := FALSE;

    BEGIN
      v_source_id := nullif(v_item->>'task_id', '')::UUID;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Ungültige Aufgaben-ID';
    END;
    v_status := v_item->>'status';

    IF v_source_id IS NULL OR v_status NOT IN (
      'open', 'done', 'partial', 'not_requested',
      'not_possible', 'cancelled', 'deferred'
    ) THEN
      RAISE EXCEPTION 'Ungültiger Aufgabenstatus';
    END IF;

    SELECT t.id, t.title, t.sort_order, t.status
    INTO v_visit_task_id, v_title, v_sort_order, v_old_visit_status
    FROM public.assist_visit_tasks t
    WHERE t.tenant_id = v_visit.tenant_id
      AND t.visit_id = v_visit.id
      AND t.id = v_source_id
    FOR UPDATE;

    IF v_visit_task_id IS NULL THEN
      SELECT t.id, t.title, t.sort_order, t.status
      INTO v_assignment_task_id, v_title, v_sort_order, v_old_assignment_status
      FROM public.assignment_tasks t
      WHERE t.tenant_id = v_visit.tenant_id
        AND t.assignment_id = v_assignment_id
        AND t.id = v_source_id
      FOR UPDATE;
    END IF;

    IF v_visit_task_id IS NULL AND v_assignment_task_id IS NULL THEN
      INSERT INTO public.assist_visit_admin_audit (
        tenant_id, visit_id, action, previous_value, new_value, reason
      ) VALUES (
        v_visit.tenant_id,
        v_visit.id,
        'stale_task_reference_discarded',
        jsonb_build_object('source_task_id', v_source_id),
        jsonb_build_object('discarded', TRUE),
        trim(p_reason)
      );
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    v_match := public.resolve_admin_visit_task_ids(v_visit.id,v_source_id);
    v_visit_task_id := (v_match->>'visit_task_id')::uuid;
    v_assignment_task_id := (v_match->>'assignment_task_id')::uuid;
    SELECT status INTO v_old_visit_status FROM public.assist_visit_tasks
    WHERE tenant_id=v_visit.tenant_id AND visit_id=v_visit.id AND id=v_visit_task_id;
    SELECT status INTO v_old_assignment_status FROM public.assignment_tasks
    WHERE tenant_id=v_visit.tenant_id AND assignment_id=v_assignment_id AND id=v_assignment_task_id;

    v_assignment_status := CASE v_status
      WHEN 'not_possible' THEN 'not_done'
      WHEN 'deferred' THEN 'not_done'
      ELSE v_status
    END;
    v_old_visible_status := coalesce(
      v_old_visit_status,
      CASE v_old_assignment_status
        WHEN 'not_done' THEN 'not_possible'
        ELSE v_old_assignment_status
      END
    );

    IF v_visit_task_id IS NOT NULL
       AND v_old_visit_status IS DISTINCT FROM v_status THEN
      UPDATE public.assist_visit_tasks
      SET
        status = v_status,
        not_done_reason = CASE WHEN v_status = 'done' THEN NULL ELSE trim(p_reason) END,
        completed_at = CASE WHEN v_status = 'done' THEN coalesce(completed_at, now()) ELSE NULL END,
        updated_at = now()
      WHERE id = v_visit_task_id
        AND visit_id = v_visit.id
        AND tenant_id = v_visit.tenant_id;
      v_changed := TRUE;
    END IF;

    IF v_assignment_task_id IS NOT NULL
       AND v_old_assignment_status IS DISTINCT FROM v_assignment_status THEN
      UPDATE public.assignment_tasks
      SET
        status = v_assignment_status,
        not_done_reason = CASE WHEN v_status = 'done' THEN NULL ELSE trim(p_reason) END,
        updated_at = now()
      WHERE id = v_assignment_task_id
        AND assignment_id = v_assignment_id
        AND tenant_id = v_visit.tenant_id;
      v_changed := TRUE;
    END IF;

    IF v_changed THEN
      INSERT INTO public.assist_visit_admin_audit (
        tenant_id, visit_id, action, previous_value, new_value, reason
      ) VALUES (
        v_visit.tenant_id,
        v_visit.id,
        'task_updated_reconciled',
        jsonb_build_object(
          'source_task_id', v_source_id,
          'visit_task_id', v_visit_task_id,
          'assignment_task_id', v_assignment_task_id,
          'title', v_title,
          'status', v_old_visible_status
        ),
        jsonb_build_object(
          'source_task_id', v_source_id,
          'visit_task_id', v_visit_task_id,
          'assignment_task_id', v_assignment_task_id,
          'title', v_title,
          'status', v_status
        ),
        trim(p_reason)
      );
      v_updated := v_updated + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', TRUE,
    'updated', v_updated,
    'skipped', v_skipped
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_bodymap_start_review(p_variant_id text, p_asset_path text, p_asset_sha256 text, p_source_commit_sha text, p_reviewer_name text, p_reviewer_qualification text, p_review_scope text, p_checklist_version integer, p_checklist_snapshot jsonb, p_items jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_review_id UUID;
  v_item JSONB;
BEGIN
  IF NOT public.platform_bodymap_can_write_review() THEN
    RAISE EXCEPTION 'bodymap_review_write_forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_asset_sha256 !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'invalid_asset_sha256' USING ERRCODE = '22023';
  END IF;
  IF length(trim(p_reviewer_name)) < 2 THEN
    RAISE EXCEPTION 'reviewer_name_required' USING ERRCODE = '22023';
  END IF;

  UPDATE public.bodymap_medical_review_runs
  SET status = 'superseded', updated_at = NOW()
  WHERE variant_id = p_variant_id
    AND status IN ('draft', 'in_review', 'changes_required')
    AND asset_sha256 <> p_asset_sha256;

  INSERT INTO public.bodymap_medical_review_runs (
    variant_id, asset_path, asset_sha256, source_commit_sha,
    checklist_version, status, reviewer_name, reviewer_qualification,
    review_scope, checklist_snapshot
  ) VALUES (
    p_variant_id, p_asset_path, p_asset_sha256, p_source_commit_sha,
    p_checklist_version, 'in_review', trim(p_reviewer_name),
    trim(COALESCE(p_reviewer_qualification, '')),
    trim(COALESCE(p_review_scope, '')), COALESCE(p_checklist_snapshot, '[]'::jsonb)
  ) RETURNING id INTO v_review_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
  LOOP
    INSERT INTO public.bodymap_medical_review_items (
      review_id, criterion_id, category, result, notes, evidence
    ) VALUES (
      v_review_id, v_item->>'criterionId', v_item->>'category',
      COALESCE(v_item->>'result', 'pending'), COALESCE(v_item->>'notes', ''),
      COALESCE(v_item->'evidence', '[]'::jsonb)
    );
  END LOOP;

  INSERT INTO public.bodymap_medical_review_events (
    review_id, variant_id, event_type, actor_role, after
  ) VALUES (
    v_review_id, p_variant_id, 'review_started', public.platform_current_role(),
    jsonb_build_object('assetSha256', p_asset_sha256, 'sourceCommitSha', p_source_commit_sha)
  );
  PERFORM public.platform_write_audit_log(
    'bodymap.review.started', 'bodymap_medical_review', v_review_id, NULL, NULL,
    jsonb_build_object('variantId', p_variant_id, 'assetSha256', p_asset_sha256),
    'Medizinische Bodymap-Prüfung gestartet'
  );
  RETURN v_review_id;
END
$function$

CREATE OR REPLACE FUNCTION public.platform_bodymap_save_review(p_review_id uuid, p_reviewer_name text, p_reviewer_qualification text, p_review_scope text, p_status text, p_items jsonb, p_issues jsonb, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run public.bodymap_medical_review_runs%ROWTYPE;
  v_item JSONB;
  v_issue JSONB;
BEGIN
  IF NOT public.platform_bodymap_can_write_review() THEN
    RAISE EXCEPTION 'bodymap_review_write_forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_run FROM public.bodymap_medical_review_runs WHERE id = p_review_id FOR UPDATE;
  IF v_run.id IS NULL THEN RAISE EXCEPTION 'review_not_found'; END IF;
  IF v_run.status IN ('approved', 'revoked', 'superseded') THEN
    RAISE EXCEPTION 'immutable_review_decision';
  END IF;
  IF p_status NOT IN ('draft', 'in_review', 'changes_required') THEN
    RAISE EXCEPTION 'invalid_review_status';
  END IF;

  UPDATE public.bodymap_medical_review_runs SET
    reviewer_name = trim(p_reviewer_name),
    reviewer_qualification = trim(COALESCE(p_reviewer_qualification, '')),
    review_scope = trim(COALESCE(p_review_scope, '')),
    status = p_status,
    submitted_at = CASE WHEN p_status = 'changes_required' THEN NOW() ELSE submitted_at END,
    updated_at = NOW()
  WHERE id = p_review_id;

  DELETE FROM public.bodymap_medical_review_items WHERE review_id = p_review_id;
  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb))
  LOOP
    INSERT INTO public.bodymap_medical_review_items (
      review_id, criterion_id, category, result, notes, evidence
    ) VALUES (
      p_review_id, v_item->>'criterionId', v_item->>'category',
      COALESCE(v_item->>'result', 'pending'), COALESCE(v_item->>'notes', ''),
      COALESCE(v_item->'evidence', '[]'::jsonb)
    );
  END LOOP;

  DELETE FROM public.bodymap_medical_review_issues WHERE review_id = p_review_id;
  FOR v_issue IN SELECT value FROM jsonb_array_elements(COALESCE(p_issues, '[]'::jsonb))
  LOOP
    INSERT INTO public.bodymap_medical_review_issues (
      review_id, anatomical_zone_id, view_id, severity, status, title,
      description, surface_point, evidence, resolution
    ) VALUES (
      p_review_id, NULLIF(v_issue->>'anatomicalZoneId', ''),
      NULLIF(v_issue->>'viewId', ''), v_issue->>'severity',
      COALESCE(v_issue->>'status', 'open'), v_issue->>'title',
      COALESCE(v_issue->>'description', ''), v_issue->'surfacePoint',
      COALESCE(v_issue->'evidence', '[]'::jsonb), NULLIF(v_issue->>'resolution', '')
    );
  END LOOP;

  INSERT INTO public.bodymap_medical_review_events (
    review_id, variant_id, event_type, actor_role, before, after, reason
  ) VALUES (
    p_review_id, v_run.variant_id, 'review_saved', public.platform_current_role(),
    jsonb_build_object('status', v_run.status),
    jsonb_build_object('status', p_status, 'itemCount', jsonb_array_length(COALESCE(p_items, '[]'::jsonb)), 'issueCount', jsonb_array_length(COALESCE(p_issues, '[]'::jsonb))),
    p_reason
  );
  PERFORM public.platform_write_audit_log(
    'bodymap.review.saved', 'bodymap_medical_review', p_review_id, NULL,
    jsonb_build_object('status', v_run.status), jsonb_build_object('status', p_status), p_reason
  );
  RETURN TRUE;
END
$function$

CREATE OR REPLACE FUNCTION public.platform_bodymap_approve_review(p_review_id uuid, p_expected_criteria integer, p_current_asset_sha256 text, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run public.bodymap_medical_review_runs%ROWTYPE;
  v_completed INTEGER;
  v_blocking_items INTEGER;
  v_blocking_issues INTEGER;
BEGIN
  IF public.platform_current_role() <> 'platform_owner' THEN
    RAISE EXCEPTION 'bodymap_final_approval_owner_only' USING ERRCODE = '42501';
  END IF;
  IF length(trim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'approval_reason_required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_run FROM public.bodymap_medical_review_runs WHERE id = p_review_id FOR UPDATE;
  IF v_run.id IS NULL THEN RAISE EXCEPTION 'review_not_found'; END IF;
  IF v_run.asset_sha256 <> p_current_asset_sha256 THEN
    RAISE EXCEPTION 'asset_changed_review_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT count(*), count(*) FILTER (WHERE result IN ('pending', 'major', 'blocker'))
  INTO v_completed, v_blocking_items
  FROM public.bodymap_medical_review_items WHERE review_id = p_review_id;
  SELECT count(*) INTO v_blocking_issues
  FROM public.bodymap_medical_review_issues
  WHERE review_id = p_review_id AND status = 'open' AND severity IN ('major', 'blocker');

  IF v_completed <> p_expected_criteria OR v_blocking_items > 0 OR v_blocking_issues > 0 THEN
    RAISE EXCEPTION 'review_quality_gate_failed';
  END IF;

  UPDATE public.bodymap_medical_review_runs
  SET status = 'superseded', updated_at = NOW()
  WHERE variant_id = v_run.variant_id AND status = 'approved' AND id <> p_review_id;
  UPDATE public.bodymap_medical_review_runs SET
    status = 'approved', decision_reason = trim(p_reason), submitted_at = NOW(),
    approved_at = NOW(), approved_by = auth.uid(), updated_at = NOW()
  WHERE id = p_review_id;

  INSERT INTO public.bodymap_medical_review_events (
    review_id, variant_id, event_type, actor_role, before, after, reason
  ) VALUES (
    p_review_id, v_run.variant_id, 'review_approved', public.platform_current_role(),
    jsonb_build_object('status', v_run.status),
    jsonb_build_object('status', 'approved', 'assetSha256', v_run.asset_sha256),
    trim(p_reason)
  );
  PERFORM public.platform_write_audit_log(
    'bodymap.review.approved', 'bodymap_medical_review', p_review_id, NULL,
    jsonb_build_object('status', v_run.status),
    jsonb_build_object('status', 'approved', 'variantId', v_run.variant_id, 'assetSha256', v_run.asset_sha256),
    trim(p_reason)
  );
  RETURN TRUE;
END
$function$

CREATE OR REPLACE FUNCTION public.platform_bodymap_revoke_review(p_review_id uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run public.bodymap_medical_review_runs%ROWTYPE;
BEGIN
  IF public.platform_current_role() <> 'platform_owner' THEN
    RAISE EXCEPTION 'bodymap_revoke_owner_only' USING ERRCODE = '42501';
  END IF;
  IF length(trim(COALESCE(p_reason, ''))) < 5 THEN
    RAISE EXCEPTION 'revoke_reason_required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_run FROM public.bodymap_medical_review_runs WHERE id = p_review_id FOR UPDATE;
  IF v_run.status <> 'approved' THEN RAISE EXCEPTION 'only_approved_review_can_be_revoked'; END IF;
  UPDATE public.bodymap_medical_review_runs SET
    status = 'revoked', decision_reason = trim(p_reason), revoked_at = NOW(),
    revoked_by = auth.uid(), updated_at = NOW()
  WHERE id = p_review_id;
  INSERT INTO public.bodymap_medical_review_events (
    review_id, variant_id, event_type, actor_role, before, after, reason
  ) VALUES (
    p_review_id, v_run.variant_id, 'review_revoked', public.platform_current_role(),
    jsonb_build_object('status', 'approved'), jsonb_build_object('status', 'revoked'), trim(p_reason)
  );
  PERFORM public.platform_write_audit_log(
    'bodymap.review.revoked', 'bodymap_medical_review', p_review_id, NULL,
    jsonb_build_object('status', 'approved'), jsonb_build_object('status', 'revoked'), trim(p_reason)
  );
  RETURN TRUE;
END
$function$

CREATE OR REPLACE FUNCTION public.caresuite_sync_message_thread_unread_counters()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  old_office INTEGER := 0;
  old_portal INTEGER := 0;
  new_office INTEGER := 0;
  new_portal INTEGER := 0;
  target_thread_id UUID;
  target_tenant_id UUID;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT office_unread, portal_unread
      INTO old_office, old_portal
      FROM public.caresuite_message_unread_contribution(
        OLD.sender_profile_id,
        OLD.sender_client_id,
        OLD.sender_employee_id,
        OLD.is_internal_note,
        OLD.is_system_message,
        OLD.read_at
      );
  END IF;

  IF TG_OP <> 'DELETE' THEN
    SELECT office_unread, portal_unread
      INTO new_office, new_portal
      FROM public.caresuite_message_unread_contribution(
        NEW.sender_profile_id,
        NEW.sender_client_id,
        NEW.sender_employee_id,
        NEW.is_internal_note,
        NEW.is_system_message,
        NEW.read_at
      );
  END IF;

  target_thread_id := COALESCE(NEW.thread_id, OLD.thread_id);
  target_tenant_id := COALESCE(NEW.tenant_id, OLD.tenant_id);

  UPDATE public.message_threads
     SET office_unread_count = GREATEST(0, office_unread_count + new_office - old_office),
         portal_unread_count = GREATEST(0, portal_unread_count + new_portal - old_portal),
         updated_at = NOW()
   WHERE id = target_thread_id
     AND tenant_id = target_tenant_id;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_complete_assist_visit_follow_up(p_visit_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v public.assist_visits%ROWTYPE;
  v_signature_deferred BOOLEAN := FALSE;
  v_actor UUID := public.resolve_current_profile_id();
BEGIN
  IF NOT (public.is_tenant_admin() OR public.has_permission('assist.execution.manage')) THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  IF length(trim(coalesce(p_reason, ''))) = 0 THEN
    RAISE EXCEPTION 'Begründung ist erforderlich';
  END IF;

  SELECT * INTO v
  FROM public.assist_visits
  WHERE id = p_visit_id AND tenant_id = public.current_tenant_id()
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden'; END IF;
  IF v.actual_start_at IS NULL OR v.actual_end_at IS NULL OR coalesce(v.duration_minutes, 0) <= 0 THEN
    RAISE EXCEPTION 'Gültige Ist-Zeiten fehlen';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.assist_visit_tasks
    WHERE tenant_id = v.tenant_id AND visit_id = v.id
      AND is_required AND status = 'open'
  ) THEN
    RAISE EXCEPTION 'Pflichtaufgaben sind noch offen';
  END IF;
  IF v.documentation_status <> 'complete' THEN
    RAISE EXCEPTION 'Dokumentation ist nicht vollständig';
  END IF;

  IF v.proof_status NOT IN ('signed', 'verified') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.assist_visit_signature_requests
      WHERE tenant_id = v.tenant_id AND visit_id = v.id AND status = 'open'
      UNION ALL
      SELECT 1 FROM public.assist_visit_proofs
      WHERE tenant_id = v.tenant_id AND visit_id = v.id
        AND portal_visible = TRUE
        AND portal_release_status = 'pending_client_signature'
    ) INTO v_signature_deferred;
    IF NOT v_signature_deferred THEN
      RAISE EXCEPTION 'Signatur oder verifizierter Nachweis fehlt';
    END IF;
  END IF;

  UPDATE public.assist_visits
  SET
    execution_status = 'completed',
    canonical_status = 'completed',
    billing_status = CASE WHEN v_signature_deferred THEN 'blocked' ELSE 'ready' END,
    finished_at = coalesce(finished_at, actual_end_at),
    updated_by = v_actor,
    updated_at = now()
  WHERE id = v.id AND tenant_id = v.tenant_id;

  INSERT INTO public.assist_visit_admin_audit (
    tenant_id, visit_id, action, previous_value, new_value, reason
  ) VALUES (
    v.tenant_id, v.id, 'follow_up_completed',
    jsonb_build_object('canonical_status', v.canonical_status),
    jsonb_build_object(
      'canonical_status', 'completed',
      'signature_deferred_to_client_portal', v_signature_deferred,
      'billing_status', CASE WHEN v_signature_deferred THEN 'blocked' ELSE 'ready' END
    ),
    trim(p_reason)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_append_assist_visit_documentation(p_visit_id uuid, p_content text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v public.assist_visits%ROWTYPE;
  v_old TEXT;
  v_actor UUID := public.resolve_current_profile_id();
BEGIN
  IF NOT (public.is_tenant_admin() OR public.has_permission('assist.execution.manage')) THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  IF length(trim(coalesce(p_content, ''))) = 0
     OR length(trim(coalesce(p_reason, ''))) = 0 THEN
    RAISE EXCEPTION 'Dokumentation und Begründung sind erforderlich';
  END IF;

  SELECT * INTO v
  FROM public.assist_visits
  WHERE id = p_visit_id AND tenant_id = public.current_tenant_id()
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden'; END IF;

  SELECT short_description INTO v_old
  FROM public.assist_visit_documentation
  WHERE tenant_id = v.tenant_id AND visit_id = v.id
  FOR UPDATE;

  INSERT INTO public.assist_visit_documentation (
    tenant_id, visit_id, short_description, special_notes,
    submitted_at, submitted_by, metadata
  ) VALUES (
    v.tenant_id, v.id, trim(p_content), trim(p_content),
    now(), v_actor, jsonb_build_object('administrative_reason', trim(p_reason))
  )
  ON CONFLICT (tenant_id, visit_id) DO UPDATE SET
    short_description = CASE
      WHEN NULLIF(trim(public.assist_visit_documentation.short_description), '') IS NULL
        THEN trim(p_content)
      ELSE public.assist_visit_documentation.short_description
    END,
    special_notes = concat_ws(
      E'\n\n',
      public.assist_visit_documentation.special_notes,
      '[Administrative Ergänzung ' || to_char(now(), 'YYYY-MM-DD HH24:MI') || '] ' || trim(p_content)
    ),
    submitted_at = now(),
    submitted_by = v_actor,
    metadata = public.assist_visit_documentation.metadata ||
      jsonb_build_object('last_administrative_reason', trim(p_reason)),
    updated_at = now();

  UPDATE public.assist_visits
  SET documentation_status = 'complete', updated_by = v_actor, updated_at = now()
  WHERE id = v.id AND tenant_id = v.tenant_id;

  INSERT INTO public.assist_visit_admin_audit (
    tenant_id, visit_id, action, previous_value, new_value, reason
  ) VALUES (
    v.tenant_id, v.id, 'documentation_appended',
    jsonb_build_object('short_description', v_old),
    jsonb_build_object('content', trim(p_content)), trim(p_reason)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_deferred_signature_client_document(p_tenant_id uuid, p_proof_id uuid, p_client_id uuid, p_title text, p_actor_profile_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor UUID := public.resolve_current_profile_id();
  v_title TEXT;
BEGIN
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht überein';
  END IF;
  IF NOT (public.is_tenant_admin() OR public.has_permission('assist.execution.manage')) THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Angemeldetes Verwaltungsprofil konnte nicht zugeordnet werden';
  END IF;
  IF p_actor_profile_id IS NOT NULL AND p_actor_profile_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Verwaltungsprofil stimmt nicht mit der Sitzung überein';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.assist_visit_proofs p
    JOIN public.assist_visits v
      ON v.tenant_id = p.tenant_id AND v.id = p.visit_id
    WHERE p.tenant_id = p_tenant_id
      AND p.id = p_proof_id
      AND v.client_id = p_client_id
      AND p.portal_visible = TRUE
      AND p.portal_release_status = 'pending_client_signature'
  ) THEN
    RAISE EXCEPTION 'Signaturanforderung ist nicht eindeutig dem Klienten zugeordnet';
  END IF;

  v_title := coalesce(nullif(trim(p_title), ''), 'Leistungsnachweis')
    || ' — Unterschrift ausstehend';

  INSERT INTO public.client_documents (
    id, tenant_id, client_id, title, file_name, mime_type, category,
    storage_path, portal_visible, status, sensitivity, source, uploaded_by,
    signed_at, signature_required, updated_at
  ) VALUES (
    p_proof_id, p_tenant_id, p_client_id, v_title,
    'unterschrift-' || p_proof_id::text || '.pending', 'application/pdf',
    'leistungsnachweis', NULL, TRUE, 'aktiv', 'care', 'assist_visit_proof',
    v_actor, NULL, TRUE, now()
  )
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    file_name = EXCLUDED.file_name,
    storage_path = NULL,
    portal_visible = TRUE,
    status = 'aktiv',
    category = 'leistungsnachweis',
    signed_at = NULL,
    signature_required = TRUE,
    source = 'assist_visit_proof',
    uploaded_by = v_actor,
    updated_at = now();

  RETURN p_proof_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_request_deferred_signature_admin_approval(p_tenant_id uuid, p_visit_id uuid, p_employee_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.assist_visits%ROWTYPE;
  v_current_employee uuid;
  v_request_id uuid;
  v_client_name text;
  v_employee_name text;
  v_documentation text;
BEGIN
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandantenzugriff verweigert';
  END IF;

  v_current_employee := public.resolve_current_employee_id();
  IF v_current_employee IS NULL OR v_current_employee IS DISTINCT FROM p_employee_id THEN
    RAISE EXCEPTION 'Mitarbeitenden-Zuordnung ungültig';
  END IF;
  IF length(trim(coalesce(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION 'Bitte begründen Sie die Weiterleitung mit mindestens 10 Zeichen';
  END IF;

  SELECT * INTO v
    FROM public.assist_visits
   WHERE id = p_visit_id
     AND tenant_id = p_tenant_id
     AND employee_id = p_employee_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden'; END IF;
  IF v.actual_end_at IS NULL THEN RAISE EXCEPTION 'Der Einsatz ist noch nicht beendet'; END IF;
  IF coalesce(v.documentation_status, '') <> 'complete' THEN
    RAISE EXCEPTION 'Dokumentation ist noch nicht vollständig';
  END IF;

  SELECT id INTO v_request_id
    FROM public.assist_visit_signature_requests
   WHERE tenant_id = p_tenant_id
     AND visit_id = p_visit_id
     AND status = 'pending_admin_approval';
  IF v_request_id IS NOT NULL THEN RETURN v_request_id; END IF;

  SELECT trim(concat_ws(' ', first_name, last_name)) INTO v_client_name
    FROM public.clients WHERE id = v.client_id AND tenant_id = p_tenant_id;
  SELECT trim(concat_ws(' ', first_name, last_name)) INTO v_employee_name
    FROM public.employees WHERE id = p_employee_id AND tenant_id = p_tenant_id;
  SELECT coalesce(nullif(trim(short_description), ''), nullif(trim(special_notes), ''))
    INTO v_documentation
    FROM public.assist_visit_documentation
   WHERE tenant_id = p_tenant_id AND visit_id = p_visit_id;

  INSERT INTO public.assist_visit_signature_requests(
    tenant_id, visit_id, client_id, employee_id, request_reason, status, service_date, service_name,
    planned_start_at, planned_end_at, actual_start_at, actual_end_at, proof_preview
  ) VALUES (
    p_tenant_id, p_visit_id, v.client_id, p_employee_id, trim(p_reason), 'pending_admin_approval',
    v.assignment_date, coalesce(nullif(v.service_name, ''), v.title),
    v.planned_start_at, v.planned_end_at, v.actual_start_at, v.actual_end_at,
    jsonb_build_object(
      'visit_id', v.id,
      'service_date', v.assignment_date,
      'service', coalesce(nullif(v.service_name, ''), v.title),
      'client_name', coalesce(nullif(v_client_name, ''), 'Klient:in'),
      'employee_name', coalesce(nullif(v_employee_name, ''), 'Mitarbeiter:in'),
      'request_reason', trim(p_reason),
      'planned_start_at', v.planned_start_at,
      'planned_end_at', v.planned_end_at,
      'actual_start_at', v.actual_start_at,
      'actual_end_at', v.actual_end_at,
      'documentation', coalesce(v_documentation, '')
    )
  ) RETURNING id INTO v_request_id;

  INSERT INTO public.assist_visit_admin_audit(tenant_id, visit_id, action, new_value, reason)
  VALUES (
    p_tenant_id, p_visit_id, 'deferred_signature_approval_requested',
    jsonb_build_object('request_id', v_request_id, 'employee_id', p_employee_id),
    'Mitarbeitende Person beantragt Portal-Unterschrift'
  );
  RETURN v_request_id;
END $function$

CREATE OR REPLACE FUNCTION public.admin_decide_deferred_signature_approval(p_request_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.assist_visit_signature_requests%ROWTYPE;
  v_profile_id uuid;
  v_status text;
BEGIN
  IF NOT public.has_permission('assist.execution.manage') THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Ungültige Entscheidung';
  END IF;
  IF p_decision = 'rejected' AND length(trim(coalesce(p_reason, ''))) = 0 THEN
    RAISE EXCEPTION 'Bei Ablehnung ist eine Begründung erforderlich';
  END IF;

  SELECT * INTO r
    FROM public.assist_visit_signature_requests
   WHERE id = p_request_id AND tenant_id = public.current_tenant_id()
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Freigabeanfrage nicht gefunden'; END IF;
  IF r.status IN ('approved', 'rejected') THEN
    RETURN jsonb_build_object('request_id', r.id, 'visit_id', r.visit_id, 'status', r.status);
  END IF;
  IF r.status <> 'pending_admin_approval' THEN RAISE EXCEPTION 'Anfrage ist nicht entscheidbar'; END IF;

  IF p_decision = 'approved' AND NOT EXISTS (
    SELECT 1 FROM public.assist_visit_proofs p
     WHERE p.tenant_id = r.tenant_id AND p.visit_id = r.visit_id
       AND p.portal_visible = true
       AND p.portal_release_status = 'pending_client_signature'
  ) THEN
    RAISE EXCEPTION 'Portal-Veröffentlichung wurde noch nicht bestätigt';
  END IF;

  v_profile_id := public.resolve_current_profile_id();
  v_status := p_decision;
  UPDATE public.assist_visit_signature_requests
     SET status = v_status,
         decision_by_profile_id = v_profile_id,
         decision_at = now(),
         decision_reason = nullif(trim(coalesce(p_reason, '')), '')
   WHERE id = r.id;

  IF p_decision = 'approved' THEN
    UPDATE public.assist_visits
       SET execution_status = 'completed', canonical_status = 'completed',
           proof_status = 'pending', billing_status = 'blocked',
           finished_at = coalesce(finished_at, actual_end_at),
           updated_by = v_profile_id, updated_at = now()
     WHERE id = r.visit_id AND tenant_id = r.tenant_id;
    UPDATE public.assignments
       SET status = 'completed', updated_at = now()
     WHERE id = coalesce(
       (SELECT legacy_assignment_id FROM public.assist_visits
         WHERE id = r.visit_id AND tenant_id = r.tenant_id),
       r.visit_id
     ) AND tenant_id = r.tenant_id;
    UPDATE public.assist_visit_execution_state
       SET current_step = 'completed', assignment_status = 'abgeschlossen',
           documentation_complete = true, signature_complete = false,
           proof_generated = false, finalized_at = now(), updated_at = now(),
           metadata = metadata || jsonb_build_object('signature_deferred_to_client_portal', true)
     WHERE visit_id = r.visit_id AND tenant_id = r.tenant_id;
  END IF;

  INSERT INTO public.assist_visit_admin_audit(tenant_id, visit_id, action, previous_value, new_value, reason)
  VALUES (
    r.tenant_id, r.visit_id,
    CASE WHEN p_decision = 'approved'
      THEN 'deferred_signature_approval_approved'
      ELSE 'deferred_signature_approval_rejected' END,
    jsonb_build_object('status', r.status),
    jsonb_build_object('status', v_status, 'request_id', r.id),
    coalesce(nullif(trim(coalesce(p_reason, '')), ''), 'Durch Verwaltung genehmigt')
  );
  RETURN jsonb_build_object('request_id', r.id, 'visit_id', r.visit_id, 'status', v_status);
END $function$

CREATE OR REPLACE FUNCTION public.set_client_vital_sign_configuration(p_client_id uuid, p_vital_key text, p_enabled boolean, p_limits jsonb DEFAULT '{}'::jsonb, p_schedule jsonb DEFAULT '{}'::jsonb)
 RETURNS client_vital_sign_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant UUID := public.current_tenant_id(); v_actor UUID := public.resolve_current_profile_id(); v_result public.client_vital_sign_settings;
BEGIN
  IF NOT public.vital_actor_can_configure() THEN RAISE EXCEPTION 'Keine Berechtigung zur Vitalwert-Konfiguration.'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.clients c WHERE c.id=p_client_id AND c.tenant_id=v_tenant) THEN RAISE EXCEPTION 'Klient:in nicht gefunden.'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.vital_sign_catalog WHERE key=p_vital_key AND is_active) THEN RAISE EXCEPTION 'Unbekannte Messart.'; END IF;
  INSERT INTO public.client_vital_sign_settings(tenant_id,client_id,vital_key,enabled,limits,schedule,created_by,updated_by)
  VALUES(v_tenant,p_client_id,p_vital_key,p_enabled,COALESCE(p_limits,'{}'),COALESCE(p_schedule,'{}'),v_actor,v_actor)
  ON CONFLICT(tenant_id,client_id,vital_key) DO UPDATE SET enabled=EXCLUDED.enabled,limits=EXCLUDED.limits,schedule=EXCLUDED.schedule,updated_by=v_actor,updated_at=clock_timestamp()
  RETURNING * INTO v_result;
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.record_vital_sign_measurement(p_client_id uuid, p_vital_key text, p_values jsonb, p_context jsonb DEFAULT '{}'::jsonb, p_note text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text)
 RETURNS vital_sign_measurements
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant UUID := public.current_tenant_id(); v_catalog public.vital_sign_catalog;
  v_actor UUID := public.resolve_current_profile_id();
  v_setting public.client_vital_sign_settings; v_enabled BOOLEAN; v_name TEXT; v_display TEXT;
  v_flag TEXT := 'unrated'; v_item RECORD; v_limit JSONB; v_number NUMERIC;
  v_result public.vital_sign_measurements;
BEGIN
  IF NOT public.vital_actor_can_record() THEN RAISE EXCEPTION 'Keine Berechtigung zur Vitalwerterfassung.'; END IF;
  IF p_source NOT IN ('manual','device','import') THEN RAISE EXCEPTION 'Ungültige Datenquelle.'; END IF;
  IF jsonb_typeof(p_values) <> 'object' OR p_values='{}'::JSONB THEN RAISE EXCEPTION 'Messwert fehlt.'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.clients c WHERE c.id=p_client_id AND c.tenant_id=v_tenant) THEN RAISE EXCEPTION 'Klient:in nicht gefunden.'; END IF;
  SELECT * INTO v_catalog FROM public.vital_sign_catalog WHERE key=p_vital_key AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unbekannte Messart.'; END IF;
  SELECT * INTO v_setting FROM public.client_vital_sign_settings WHERE tenant_id=v_tenant AND client_id=p_client_id AND vital_key=p_vital_key;
  v_enabled := COALESCE(v_setting.enabled,v_catalog.default_enabled);
  IF NOT v_enabled THEN RAISE EXCEPTION 'Dieser Vitalwert ist für die Klient:in deaktiviert.'; END IF;
  SELECT COALESCE(NULLIF(p.display_name,''),p.email,'Unbekannt') INTO v_name
    FROM public.profiles p WHERE p.id=v_actor AND p.tenant_id=v_tenant;
  IF v_name IS NULL THEN RAISE EXCEPTION 'Mitarbeiterprofil konnte nicht zugeordnet werden.'; END IF;

  v_display := CASE
    WHEN p_vital_key IN ('blood_pressure','arterial_pressure') THEN concat(COALESCE(p_values->>'systolic','—'),'/',COALESCE(p_values->>'diastolic','—'),CASE WHEN p_values?'map' THEN concat(' (MAP ',p_values->>'map',')') ELSE '' END)
    WHEN p_vital_key='gcs' THEN concat('GCS ',COALESCE(p_values->>'total','—'),' (E',COALESCE(p_values->>'eyes','—'),' V',COALESCE(p_values->>'verbal','—'),' M',COALESCE(p_values->>'motor','—'),')')
    WHEN p_vital_key='fluid_balance' THEN concat(CASE WHEN COALESCE((p_values->>'balance')::NUMERIC,0)>=0 THEN '+' ELSE '' END,COALESCE(p_values->>'balance','—'))
    WHEN p_vital_key='pupils' THEN concat('L ',COALESCE(p_values->>'leftSize','—'),' / R ',COALESCE(p_values->>'rightSize','—'))
    ELSE COALESCE(p_values->>'value',(SELECT value FROM jsonb_each_text(p_values) LIMIT 1),'—') END;

  IF v_setting.id IS NOT NULL AND v_setting.limits <> '{}'::JSONB THEN
    v_flag := 'within_configured_range';
    FOR v_item IN SELECT key,value FROM jsonb_each_text(p_values) LOOP
      BEGIN v_number := v_item.value::NUMERIC; EXCEPTION WHEN invalid_text_representation THEN CONTINUE; END;
      v_limit := v_setting.limits->v_item.key;
      IF v_limit IS NOT NULL AND ((v_limit?'min' AND v_number < (v_limit->>'min')::NUMERIC) OR (v_limit?'max' AND v_number > (v_limit->>'max')::NUMERIC)) THEN
        v_flag := 'outside_configured_range'; EXIT;
      END IF;
    END LOOP;
  END IF;

  INSERT INTO public.vital_sign_measurements(tenant_id,client_id,vital_key,values,display_value,unit,context,note,source,flag_status,recorded_by,recorded_by_name)
  VALUES(v_tenant,p_client_id,p_vital_key,p_values,v_display,v_catalog.default_unit,COALESCE(p_context,'{}'),NULLIF(trim(p_note),''),p_source,v_flag,v_actor,v_name)
  RETURNING * INTO v_result;

  INSERT INTO public.client_timeline_events(tenant_id,client_id,event_type,icon,title,subtitle,status,actor_name,is_internal,metadata)
  VALUES(v_tenant,p_client_id,'pflegeplan','💓',concat(v_catalog.label,' erfasst'),concat(v_display,CASE WHEN v_catalog.default_unit='' THEN '' ELSE concat(' ',v_catalog.default_unit) END),
    CASE WHEN v_flag='outside_configured_range' THEN 'fehlerhaft' ELSE 'aktiv' END,v_name,TRUE,jsonb_build_object('measurementId',v_result.id,'vitalKey',p_vital_key,'flagStatus',v_flag));

  IF v_flag='outside_configured_range' THEN
    INSERT INTO public.vital_sign_events(tenant_id,client_id,measurement_id,summary,payload,created_by)
    VALUES(v_tenant,p_client_id,v_result.id,concat(v_catalog.label,': außerhalb des klientenbezogen konfigurierten Bereichs'),jsonb_build_object('values',p_values,'limits',v_setting.limits,'doctorContactSuggestion',TRUE),v_actor);
    IF to_regclass('public.internal_tasks') IS NOT NULL THEN
      INSERT INTO public.internal_tasks(tenant_id,task_type,status,priority,title,description,created_by_user_id,linked_entity_type,linked_entity_id,source,is_internal_only,employee_visible)
      VALUES(v_tenant,'vital.out_of_range','open','high',concat('Vitalwert prüfen: ',v_catalog.label),concat(v_display,' ',v_catalog.default_unit,' · Ärztlichen Kontakt nach fachlicher Einschätzung prüfen.'),auth.uid(),'client',p_client_id,'vital_signs',TRUE,FALSE);
    END IF;
  END IF;
  RETURN v_result;
END $function$

