CREATE OR REPLACE FUNCTION public.create_care_plan_evaluation(p_care_plan_id uuid, p_payload jsonb)
 RETURNS care_plan_evaluations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant UUID := public.current_tenant_id();
  v_client UUID;
  v_result public.care_plan_evaluations;
  v_outcome TEXT := COALESCE(NULLIF(p_payload->>'outcome', ''), 'not_assessable');
BEGIN
  IF NOT (public.can_manage_pfleger_core() OR public.has_permission('pflege.evaluations.manage')) THEN
    RAISE EXCEPTION 'Keine Berechtigung zum Dokumentieren von Evaluationen.' USING ERRCODE = '42501';
  END IF;

  SELECT client_id INTO v_client
  FROM public.care_plans
  WHERE id = p_care_plan_id AND tenant_id = v_tenant
  FOR UPDATE;

  IF v_client IS NULL OR NOT public.is_active_pfleger_client(v_client) THEN
    RAISE EXCEPTION 'Evaluation gesperrt: kein aktiver Pflegefall.' USING ERRCODE = '23514';
  END IF;
  IF v_outcome NOT IN ('effective','partly_effective','not_effective','deteriorated','not_assessable') THEN
    RAISE EXCEPTION 'Ungültiges Evaluationsergebnis.' USING ERRCODE = '23514';
  END IF;
  IF trim(COALESCE(p_payload->>'observedEffect','')) = ''
     OR trim(COALESCE(p_payload->>'professionalConclusion','')) = '' THEN
    RAISE EXCEPTION 'Beobachtete Wirkung und fachliche Schlussfolgerung sind erforderlich.' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.care_plan_evaluations (
    tenant_id, client_id, care_plan_id, outcome, observed_effect, person_feedback,
    professional_conclusion, changes_required, requires_plan_update, evaluated_at,
    next_evaluation_at, evaluator_profile_id, evaluator_name_snapshot
  ) VALUES (
    v_tenant, v_client, p_care_plan_id, v_outcome, trim(p_payload->>'observedEffect'),
    COALESCE(p_payload->>'personFeedback',''), trim(p_payload->>'professionalConclusion'),
    COALESCE(p_payload->>'changesRequired',''),
    COALESCE((p_payload->>'requiresPlanUpdate')::BOOLEAN, FALSE),
    COALESCE(NULLIF(p_payload->>'evaluatedAt','')::TIMESTAMPTZ, clock_timestamp()),
    NULLIF(p_payload->>'nextEvaluationAt','')::TIMESTAMPTZ,
    auth.uid(), COALESCE(NULLIF(trim(p_payload->>'actorName'),''), 'Pflegefachperson')
  ) RETURNING * INTO v_result;

  UPDATE public.care_plans
  SET review_due_at = v_result.next_evaluation_at,
      evaluation_notes = v_result.professional_conclusion,
      updated_by = auth.uid(), updated_at = clock_timestamp()
  WHERE id = p_care_plan_id AND tenant_id = v_tenant;

  UPDATE public.care_plan_items
  SET next_evaluation_date = v_result.next_evaluation_at::DATE,
      updated_by = auth.uid(), updated_at = clock_timestamp()
  WHERE care_plan_id = p_care_plan_id AND tenant_id = v_tenant
    AND status IN ('active','paused');

  INSERT INTO public.care_audit_events (
    tenant_id, client_id, care_plan_id, entity_type, entity_id, action,
    summary, after_data, actor_id, actor_name
  ) VALUES (
    v_tenant, v_client, p_care_plan_id, 'care_plan_evaluation', v_result.id,
    'create', 'Pflegeplan-Wirksamkeit evaluiert.', to_jsonb(v_result), auth.uid(),
    v_result.evaluator_name_snapshot
  );
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.create_care_quality_visit(p_client_id uuid, p_care_plan_id uuid, p_payload jsonb)
 RETURNS care_quality_visits
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant UUID := public.current_tenant_id();
  v_result public.care_quality_visits;
  v_type TEXT := COALESCE(NULLIF(p_payload->>'visitType',''), 'professional');
  v_status TEXT := COALESCE(NULLIF(p_payload->>'status',''), 'completed');
BEGIN
  IF NOT (public.can_manage_pfleger_core() OR public.has_permission('pflege.visits.manage')) THEN
    RAISE EXCEPTION 'Keine Berechtigung zum Dokumentieren von Pflegevisiten.' USING ERRCODE = '42501';
  END IF;
  IF NOT public.is_active_pfleger_client(p_client_id) THEN
    RAISE EXCEPTION 'Pflegevisite gesperrt: kein aktiver Pflegefall.' USING ERRCODE = '23514';
  END IF;
  IF p_care_plan_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.care_plans
    WHERE id = p_care_plan_id AND tenant_id = v_tenant AND client_id = p_client_id
  ) THEN
    RAISE EXCEPTION 'Pflegeplan gehört nicht zum gewählten Pflegefall.' USING ERRCODE = '23514';
  END IF;
  IF trim(COALESCE(p_payload->>'scope','')) = '' THEN
    RAISE EXCEPTION 'Prüfumfang der Pflegevisite ist erforderlich.' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.care_quality_visits (
    tenant_id, client_id, care_plan_id, visit_type, status, scheduled_at, conducted_at,
    scope, findings, deviations, agreed_actions, person_feedback, next_visit_at,
    visitor_profile_id, visitor_name_snapshot
  ) VALUES (
    v_tenant, p_client_id, p_care_plan_id, v_type, v_status,
    NULLIF(p_payload->>'scheduledAt','')::TIMESTAMPTZ,
    CASE WHEN v_status = 'completed' THEN
      COALESCE(NULLIF(p_payload->>'conductedAt','')::TIMESTAMPTZ, clock_timestamp())
    ELSE NULLIF(p_payload->>'conductedAt','')::TIMESTAMPTZ END,
    trim(p_payload->>'scope'), COALESCE(p_payload->>'findings',''),
    COALESCE(p_payload->>'deviations',''), COALESCE(p_payload->>'agreedActions',''),
    COALESCE(p_payload->>'personFeedback',''), NULLIF(p_payload->>'nextVisitAt','')::TIMESTAMPTZ,
    auth.uid(), COALESCE(NULLIF(trim(p_payload->>'actorName'),''), 'Pflegefachperson')
  ) RETURNING * INTO v_result;

  INSERT INTO public.care_audit_events (
    tenant_id, client_id, care_plan_id, entity_type, entity_id, action,
    summary, after_data, actor_id, actor_name
  ) VALUES (
    v_tenant, p_client_id, p_care_plan_id, 'care_quality_visit', v_result.id,
    'create', 'Pflegevisite dokumentiert.', to_jsonb(v_result), auth.uid(),
    v_result.visitor_name_snapshot
  );
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.review_care_risk(p_risk_id uuid, p_payload jsonb)
 RETURNS care_assessment_risks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.care_assessment_risks; before_row JSONB; client_id UUID; t UUID:=public.current_tenant_id();
 state_value TEXT:=COALESCE(NULLIF(p_payload->>'state',''),'unclear'); urgency_value TEXT:=COALESCE(NULLIF(p_payload->>'urgency',''),'routine');
BEGIN
 IF NOT public.has_permission('pflege.risks.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 IF state_value NOT IN('none','unclear','present','controlled') OR urgency_value NOT IN('routine','timely','urgent','immediate') THEN
  RAISE EXCEPTION 'Ungültiger Risiko- oder Dringlichkeitsstatus.' USING ERRCODE='23514';
 END IF;
 SELECT to_jsonb(cr),ca.subject_id INTO before_row,client_id FROM public.care_assessment_risks cr
 JOIN public.care_assessments ca ON ca.id=cr.assessment_id AND ca.tenant_id=cr.tenant_id
 WHERE cr.id=p_risk_id AND cr.tenant_id=t AND ca.subject_type='client' FOR UPDATE OF cr;
 IF client_id IS NULL OR NOT public.is_active_pfleger_client(client_id) THEN RAISE EXCEPTION 'Kein aktiver Pflegefall.' USING ERRCODE='23514'; END IF;
 IF trim(COALESCE(p_payload->>'professionalRationale',''))='' THEN RAISE EXCEPTION 'Fachliche Begründung ist erforderlich.' USING ERRCODE='23514'; END IF;
 UPDATE public.care_assessment_risks SET risk_state=state_value,urgency=urgency_value,
  evidence=COALESCE(p_payload->>'evidence',''),protective_factors=COALESCE(p_payload->>'protectiveFactors',''),
  professional_rationale=trim(p_payload->>'professionalRationale'),counseling_provided=COALESCE(p_payload->>'counselingProvided',''),
  person_decision=COALESCE(p_payload->>'personDecision',''),refusal_documented=COALESCE((p_payload->>'refusalDocumented')::BOOLEAN,FALSE),
  next_review_at=NULLIF(p_payload->>'nextReviewAt','')::TIMESTAMPTZ,updated_at=clock_timestamp()
 WHERE id=p_risk_id AND tenant_id=t RETURNING * INTO r;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,before_data,after_data,actor_id,actor_name)
 VALUES(t,client_id,'care_risk',r.id,'review','Pflege-Risiko fachlich überprüft.',before_row,to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.review_care_plan_measure(p_item_id uuid, p_payload jsonb)
 RETURNS care_plan_measure_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE review_row public.care_plan_measure_reviews; care_plan_id UUID; client_id UUID; t UUID:=public.current_tenant_id();
 decision_value TEXT:=COALESCE(NULLIF(p_payload->>'decision',''),'continue'); next_status TEXT;
BEGIN
 IF NOT public.has_permission('pflege.measures.review') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 SELECT i.care_plan_id,p.client_id INTO care_plan_id,client_id FROM public.care_plan_items i JOIN public.care_plans p ON p.id=i.care_plan_id AND p.tenant_id=i.tenant_id
 WHERE i.id=p_item_id AND i.tenant_id=t FOR UPDATE OF i;
 IF client_id IS NULL OR NOT public.is_active_pfleger_client(client_id) THEN RAISE EXCEPTION 'Kein aktiver Pflegefall.' USING ERRCODE='23514'; END IF;
 IF decision_value NOT IN('continue','change','pause','complete') THEN RAISE EXCEPTION 'Ungültige Maßnahmenentscheidung.' USING ERRCODE='23514'; END IF;
 IF trim(COALESCE(p_payload->>'observedEffect',''))='' OR trim(COALESCE(p_payload->>'professionalRationale',''))='' THEN
  RAISE EXCEPTION 'Wirkung und fachliche Begründung sind erforderlich.' USING ERRCODE='23514';
 END IF;
 next_status:=CASE decision_value WHEN 'pause' THEN 'paused' WHEN 'complete' THEN 'completed' ELSE 'active' END;
 INSERT INTO public.care_plan_measure_reviews(tenant_id,client_id,care_plan_id,care_plan_item_id,decision,observed_effect,
  person_feedback,professional_rationale,changed_intervention,changed_frequency,next_evaluation_at,reviewer_profile_id,reviewer_name_snapshot)
 VALUES(t,client_id,care_plan_id,p_item_id,decision_value,trim(p_payload->>'observedEffect'),COALESCE(p_payload->>'personFeedback',''),
  trim(p_payload->>'professionalRationale'),COALESCE(p_payload->>'changedIntervention',''),COALESCE(p_payload->>'changedFrequency',''),
  NULLIF(p_payload->>'nextEvaluationAt','')::TIMESTAMPTZ,public.clinical_actor_id(),public.clinical_actor_name()) RETURNING * INTO review_row;
 UPDATE public.care_plan_items SET status=next_status,
  intervention=CASE WHEN decision_value='change' AND trim(COALESCE(p_payload->>'changedIntervention',''))<>'' THEN trim(p_payload->>'changedIntervention') ELSE intervention END,
  frequency=CASE WHEN decision_value='change' AND trim(COALESCE(p_payload->>'changedFrequency',''))<>'' THEN trim(p_payload->>'changedFrequency') ELSE frequency END,
  next_evaluation_date=NULLIF(p_payload->>'nextEvaluationAt','')::DATE,updated_by=auth.uid(),updated_at=clock_timestamp()
 WHERE id=p_item_id AND tenant_id=t;
 INSERT INTO public.care_audit_events(tenant_id,client_id,care_plan_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name)
 VALUES(t,client_id,care_plan_id,'care_plan_measure_review',review_row.id,decision_value,'Pflegemaßnahme fortgeschrieben.',to_jsonb(review_row),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN review_row;
END $function$

CREATE OR REPLACE FUNCTION public.advance_care_quality_deviation(p_deviation_id uuid, p_payload jsonb)
 RETURNS care_quality_deviations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.care_quality_deviations; old JSONB; t UUID:=public.current_tenant_id(); new_status TEXT:=p_payload->>'status';
BEGIN
 IF NOT public.has_permission('pflege.deviations.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 IF new_status NOT IN('assessed','in_progress','effectiveness_check','closed','cancelled') THEN RAISE EXCEPTION 'Ungültiger Folgestatus.' USING ERRCODE='23514'; END IF;
 SELECT to_jsonb(d) INTO old FROM public.care_quality_deviations d WHERE id=p_deviation_id AND tenant_id=t FOR UPDATE;
 IF old IS NULL THEN RAISE EXCEPTION 'Abweichung nicht gefunden.'; END IF;
 UPDATE public.care_quality_deviations SET status=new_status,root_cause=COALESCE(p_payload->>'rootCause',root_cause),
  corrective_action=COALESCE(p_payload->>'correctiveAction',corrective_action),responsible_name=COALESCE(p_payload->>'responsibleName',responsible_name),
  due_at=COALESCE(NULLIF(p_payload->>'dueAt','')::TIMESTAMPTZ,due_at),effectiveness_result=COALESCE(p_payload->>'effectivenessResult',effectiveness_result),
  effectiveness_checked_at=CASE WHEN new_status='closed' THEN clock_timestamp() ELSE effectiveness_checked_at END,
  closed_at=CASE WHEN new_status='closed' THEN clock_timestamp() ELSE NULL END,updated_by=public.clinical_actor_id(),updated_by_name=public.clinical_actor_name()
 WHERE id=p_deviation_id AND tenant_id=t RETURNING * INTO r;
 INSERT INTO public.care_audit_events(tenant_id,client_id,care_plan_id,entity_type,entity_id,action,summary,before_data,after_data,actor_id,actor_name)
 VALUES(t,r.client_id,r.care_plan_id,'care_quality_deviation',r.id,new_status,'Qualitätsabweichung fortgeschrieben.',old,to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.create_pfleger_service_proof(p_client_id uuid, p_payload jsonb)
 RETURNS pfleger_service_proofs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.pfleger_service_proofs; t UUID:=public.current_tenant_id(); start_value TIMESTAMPTZ:=(p_payload->>'startedAt')::TIMESTAMPTZ; end_value TIMESTAMPTZ:=(p_payload->>'endedAt')::TIMESTAMPTZ;
 basis TEXT:=p_payload->>'legalBasis'; amount_value INTEGER:=COALESCE((p_payload->>'grossAmountCents')::INTEGER,0);
BEGIN
 IF NOT public.has_permission('pflege.proofs.create') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 IF NOT public.is_active_pfleger_client(p_client_id) THEN RAISE EXCEPTION 'Kein aktiver Pflegefall.' USING ERRCODE='23514'; END IF;
 IF end_value<=start_value OR start_value::DATE<>(p_payload->>'serviceDate')::DATE THEN RAISE EXCEPTION 'Leistungszeit ist ungültig.' USING ERRCODE='23514'; END IF;
 IF basis NOT IN('sgb_v','sgb_xi','private','mixed') OR trim(COALESCE(p_payload->>'serviceCode',''))='' OR trim(COALESCE(p_payload->>'performanceNote',''))='' THEN RAISE EXCEPTION 'Leistungsart, Rechtsgrundlage und Durchführungsnachweis sind erforderlich.' USING ERRCODE='23514'; END IF;
 IF basis IN('sgb_v','mixed') AND trim(COALESCE(p_payload->>'prescriptionReference',''))='' THEN RAISE EXCEPTION 'SGB-V-Anteile benötigen einen Verordnungsbezug.' USING ERRCODE='23514'; END IF;
 INSERT INTO public.pfleger_service_proofs(tenant_id,client_id,documentation_entry_id,service_date,started_at,ended_at,duration_minutes,service_code,service_label,legal_basis,prescription_reference,cost_carrier_name,cost_carrier_ik,billing_unit,quantity,unit_price_cents,gross_amount_cents,performance_note,deviations,employee_profile_id,employee_name_snapshot,evidence_snapshot)
 VALUES(t,p_client_id,NULLIF(p_payload->>'documentationEntryId','')::UUID,(p_payload->>'serviceDate')::DATE,start_value,end_value,GREATEST(1,round(EXTRACT(EPOCH FROM(end_value-start_value))/60)),trim(p_payload->>'serviceCode'),trim(p_payload->>'serviceLabel'),basis,COALESCE(p_payload->>'prescriptionReference',''),COALESCE(p_payload->>'costCarrierName',''),COALESCE(p_payload->>'costCarrierIk',''),COALESCE(NULLIF(p_payload->>'billingUnit',''),'minute'),COALESCE((p_payload->>'quantity')::NUMERIC,1),COALESCE((p_payload->>'unitPriceCents')::INTEGER,0),amount_value,trim(p_payload->>'performanceNote'),COALESCE(p_payload->>'deviations',''),public.clinical_actor_id(),public.clinical_actor_name(),jsonb_build_object('createdPayload',p_payload,'serverCreatedAt',clock_timestamp())) RETURNING * INTO r;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name) VALUES(t,p_client_id,'pflege_service_proof',r.id,'created','Pflege-Leistungsnachweis live erfasst.',to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.advance_pfleger_service_proof(p_proof_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS pfleger_service_proofs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.pfleger_service_proofs; old JSONB; t UUID:=public.current_tenant_id(); current_status TEXT; next_status TEXT;
BEGIN
 SELECT to_jsonb(p),p.status INTO old,current_status FROM public.pfleger_service_proofs p WHERE p.id=p_proof_id AND p.tenant_id=t FOR UPDATE;
 IF old IS NULL THEN RAISE EXCEPTION 'Leistungsnachweis nicht gefunden.'; END IF;
 IF p_action='submit' THEN
  IF NOT public.has_permission('pflege.proofs.create') OR current_status<>'draft' THEN RAISE EXCEPTION 'Einreichung nicht zulässig.' USING ERRCODE='42501'; END IF; next_status:='submitted';
 ELSIF p_action='sign' THEN
  IF NOT public.has_permission('pflege.proofs.sign') OR current_status NOT IN('draft','submitted') OR trim(COALESCE(p_payload->>'signatureName',''))='' OR trim(COALESCE(p_payload->>'signatureRef',''))='' THEN RAISE EXCEPTION 'Signatur nicht zulässig oder unvollständig.' USING ERRCODE='42501'; END IF; next_status:='signed';
 ELSIF p_action IN('approve','reject') THEN
  IF NOT public.has_permission('pflege.proofs.review') OR current_status<>'signed' THEN RAISE EXCEPTION 'Prüfentscheidung nicht zulässig.' USING ERRCODE='42501'; END IF; next_status:=CASE WHEN p_action='approve' THEN 'approved' ELSE 'rejected' END;
  IF p_action='reject' AND trim(COALESCE(p_payload->>'reason',''))='' THEN RAISE EXCEPTION 'Zurückweisung benötigt eine Begründung.' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'Unbekannte Aktion.' USING ERRCODE='23514'; END IF;
 UPDATE public.pfleger_service_proofs SET status=next_status,
  client_signature_name=CASE WHEN p_action='sign' THEN trim(p_payload->>'signatureName') ELSE client_signature_name END,
  client_signed_at=CASE WHEN p_action='sign' THEN clock_timestamp() ELSE client_signed_at END,
  signature_ref=CASE WHEN p_action='sign' THEN COALESCE(p_payload->>'signatureRef','') ELSE signature_ref END,
  rejection_reason=CASE WHEN p_action='reject' THEN trim(p_payload->>'reason') ELSE rejection_reason END,
  reviewed_by=CASE WHEN p_action IN('approve','reject') THEN public.clinical_actor_id() ELSE reviewed_by END,
  reviewed_by_name=CASE WHEN p_action IN('approve','reject') THEN public.clinical_actor_name() ELSE reviewed_by_name END,
  reviewed_at=CASE WHEN p_action IN('approve','reject') THEN clock_timestamp() ELSE reviewed_at END,updated_at=clock_timestamp()
 WHERE id=p_proof_id AND tenant_id=t RETURNING * INTO r;
 IF p_action='approve' THEN
  INSERT INTO public.pfleger_billing_cases(tenant_id,client_id,service_proof_id,legal_basis,payer_type,cost_carrier_name,cost_carrier_ik,service_code,service_date,amount_cents,validation_checks,status,blocker_reason)
  VALUES(t,r.client_id,r.id,r.legal_basis,CASE r.legal_basis WHEN 'sgb_v' THEN 'krankenkasse' WHEN 'sgb_xi' THEN 'pflegekasse' WHEN 'private' THEN 'self_payer' ELSE 'mixed' END,r.cost_carrier_name,r.cost_carrier_ik,r.service_code,r.service_date,r.gross_amount_cents,
   jsonb_build_object('signed',r.client_signed_at IS NOT NULL,'amountPositive',r.gross_amount_cents>0,'serviceCode',trim(r.service_code)<>'','payerPresent',r.legal_basis='private' OR trim(r.cost_carrier_name)<>''),
   CASE WHEN r.gross_amount_cents>0 AND trim(r.service_code)<>'' AND (r.legal_basis='private' OR trim(r.cost_carrier_name)<>'') THEN 'ready' ELSE 'blocked' END,
   CASE WHEN r.gross_amount_cents<=0 THEN 'Betrag fehlt.' WHEN trim(r.service_code)='' THEN 'Leistungscode fehlt.' WHEN r.legal_basis<>'private' AND trim(r.cost_carrier_name)='' THEN 'Kostenträger fehlt.' ELSE '' END)
  ON CONFLICT(service_proof_id) DO UPDATE SET validation_checks=EXCLUDED.validation_checks,status=EXCLUDED.status,blocker_reason=EXCLUDED.blocker_reason,updated_at=clock_timestamp();
 END IF;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,before_data,after_data,actor_id,actor_name) VALUES(t,r.client_id,'pflege_service_proof',r.id,p_action,'Pflege-Leistungsnachweis fortgeschrieben.',old,to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.release_pfleger_billing_case(p_case_id uuid)
 RETURNS pfleger_billing_cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.pfleger_billing_cases; t UUID:=public.current_tenant_id();
BEGIN
 IF NOT public.has_permission('pflege.billing.release') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 UPDATE public.pfleger_billing_cases SET status='released',released_by=public.clinical_actor_id(),released_by_name=public.clinical_actor_name(),released_at=clock_timestamp(),updated_at=clock_timestamp()
 WHERE id=p_case_id AND tenant_id=t AND status='ready' RETURNING * INTO r;
 IF r.id IS NULL THEN RAISE EXCEPTION 'Abrechnungsfall ist nicht freigabefähig.' USING ERRCODE='23514'; END IF;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name) VALUES(t,r.client_id,'pflege_billing_case',r.id,'released','Pflege-Abrechnungsfall verbindlich freigegeben.',to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.create_pfleger_invoice_foundation(p_client_id uuid, p_period_from date, p_period_to date)
 RETURNS pfleger_invoice_foundations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.pfleger_invoice_foundations; t UUID:=public.current_tenant_id(); ids UUID[]; count_value INTEGER; total_value INTEGER; payer_value TEXT; recipient_value TEXT; ik_value TEXT;
BEGIN
 IF NOT public.has_permission('pflege.invoices.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 SELECT array_agg(id ORDER BY service_date),count(*),sum(amount_cents),min(payer_type),min(cost_carrier_name),min(cost_carrier_ik)
 INTO ids,count_value,total_value,payer_value,recipient_value,ik_value FROM public.pfleger_billing_cases
 WHERE tenant_id=t AND client_id=p_client_id AND status='released' AND service_date BETWEEN p_period_from AND p_period_to AND invoice_foundation_id IS NULL;
 IF COALESCE(count_value,0)=0 THEN RAISE EXCEPTION 'Keine freigegebenen Abrechnungsfälle im Zeitraum.' USING ERRCODE='23514'; END IF;
 IF (SELECT count(DISTINCT payer_type) FROM public.pfleger_billing_cases WHERE id=ANY(ids))<>1 THEN RAISE EXCEPTION 'Unterschiedliche Kostenträgerarten müssen getrennt abgerechnet werden.' USING ERRCODE='23514'; END IF;
 INSERT INTO public.pfleger_invoice_foundations(tenant_id,client_id,foundation_number,period_from,period_to,payer_type,recipient_name,recipient_ik,proof_count,total_amount_cents,billing_case_ids,validation_snapshot,created_by,created_by_name)
 VALUES(t,p_client_id,'PF-'||to_char(p_period_to,'YYYYMM')||'-'||upper(substr(replace(gen_random_uuid()::TEXT,'-',''),1,8)),p_period_from,p_period_to,payer_value,CASE WHEN payer_value='self_payer' THEN 'Selbstzahler:in' ELSE recipient_value END,ik_value,count_value,total_value,ids,jsonb_build_object('allReleased',TRUE,'singlePayerType',TRUE,'generatedAt',clock_timestamp()),public.clinical_actor_id(),public.clinical_actor_name()) RETURNING * INTO r;
 UPDATE public.pfleger_billing_cases SET status='invoiced',invoice_foundation_id=r.id,updated_at=clock_timestamp() WHERE id=ANY(ids) AND tenant_id=t;
 INSERT INTO public.care_audit_events(tenant_id,client_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name) VALUES(t,p_client_id,'pflege_invoice_foundation',r.id,'created','Rechnungsgrundlage aus freigegebenen Pflegeleistungen erzeugt.',to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.accept_pfleger_billing_period(p_period_from date, p_period_to date, p_exception_note text DEFAULT ''::text)
 RETURNS pfleger_period_acceptances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.pfleger_period_acceptances; t UUID:=public.current_tenant_id(); proofs INTEGER; approved INTEGER; released INTEGER; blocked INTEGER; foundations INTEGER; total_value INTEGER;
BEGIN
 IF NOT public.has_permission('pflege.acceptance.manage') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501'; END IF;
 SELECT count(*),count(*) FILTER(WHERE status='approved') INTO proofs,approved FROM public.pfleger_service_proofs WHERE tenant_id=t AND service_date BETWEEN p_period_from AND p_period_to AND status<>'cancelled';
 SELECT count(*) FILTER(WHERE status IN('released','invoiced')),count(*) FILTER(WHERE status IN('pending','blocked','ready')),COALESCE(sum(amount_cents) FILTER(WHERE status IN('released','invoiced')),0) INTO released,blocked,total_value FROM public.pfleger_billing_cases WHERE tenant_id=t AND service_date BETWEEN p_period_from AND p_period_to AND status<>'cancelled';
 SELECT count(*) INTO foundations FROM public.pfleger_invoice_foundations WHERE tenant_id=t AND period_from>=p_period_from AND period_to<=p_period_to AND status<>'cancelled';
 IF proofs=0 OR approved<>proofs OR blocked>0 OR foundations=0 THEN RAISE EXCEPTION 'Gesamtabnahme blockiert: Nachweise, Abrechnungsfälle oder Rechnungsgrundlagen sind unvollständig.' USING ERRCODE='23514'; END IF;
 INSERT INTO public.pfleger_period_acceptances(tenant_id,period_from,period_to,proof_count,approved_proof_count,released_case_count,blocked_case_count,invoice_foundation_count,total_amount_cents,status,exception_note,accepted_by,accepted_by_name,evidence_snapshot)
 VALUES(t,p_period_from,p_period_to,proofs,approved,released,blocked,foundations,total_value,'accepted',COALESCE(p_exception_note,''),public.clinical_actor_id(),public.clinical_actor_name(),jsonb_build_object('allProofsApproved',TRUE,'noBlockedCases',TRUE,'invoiceFoundationsPresent',TRUE,'acceptedAt',clock_timestamp()))
 ON CONFLICT(tenant_id,period_from,period_to) DO UPDATE SET proof_count=EXCLUDED.proof_count,approved_proof_count=EXCLUDED.approved_proof_count,released_case_count=EXCLUDED.released_case_count,blocked_case_count=EXCLUDED.blocked_case_count,invoice_foundation_count=EXCLUDED.invoice_foundation_count,total_amount_cents=EXCLUDED.total_amount_cents,status='accepted',exception_note=EXCLUDED.exception_note,accepted_by=EXCLUDED.accepted_by,accepted_by_name=EXCLUDED.accepted_by_name,accepted_at=clock_timestamp(),evidence_snapshot=EXCLUDED.evidence_snapshot RETURNING * INTO r;
 INSERT INTO public.care_audit_events(tenant_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name) VALUES(t,'pflege_period_acceptance',r.id,'accepted','Pflege-Abrechnungsperiode vollständig abgenommen.',to_jsonb(r),public.clinical_actor_id(),public.clinical_actor_name());
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.sync_employee_logbook_to_payroll()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_log_id UUID;
  v_changed BOOLEAN;
BEGIN
  SELECT id INTO v_log_id FROM public.assist_driving_log
    WHERE tenant_id=NEW.tenant_id AND employee_id=NEW.employee_id
      AND notes=('employee_logbook_trip:'||NEW.id::text) LIMIT 1 FOR UPDATE;
  v_changed := TG_OP='INSERT' OR ROW(NEW.started_at,NEW.ended_at,NEW.distance_final_km,NEW.route_type,NEW.assignment_id,NEW.mileage_amount_cents,NEW.purpose)
    IS DISTINCT FROM ROW(OLD.started_at,OLD.ended_at,OLD.distance_final_km,OLD.route_type,OLD.assignment_id,OLD.mileage_amount_cents,OLD.purpose)
    OR (NEW.status IN ('completed','corrected','confirmed')) IS DISTINCT FROM (OLD.status IN ('completed','corrected','confirmed'));
  IF v_log_id IS NOT NULL AND v_changed AND EXISTS (
    SELECT 1 FROM public.employee_expense_claims WHERE tenant_id=NEW.tenant_id AND driving_log_id=v_log_id AND status='reimbursed'
  ) THEN
    RAISE EXCEPTION 'Die Fahrt wurde bereits erstattet. Bitte eine gesonderte Erstattungskorrektur veranlassen.' USING ERRCODE='55000';
  END IF;
  IF NEW.status NOT IN ('completed','corrected','confirmed') OR NEW.ended_at IS NULL THEN
    IF v_log_id IS NOT NULL THEN
      UPDATE public.assist_driving_log SET payroll_eligible=FALSE,work_time_eligible=FALSE,updated_at=NOW() WHERE id=v_log_id;
      UPDATE public.employee_expense_claims SET status='rejected',approved_amount_cents=NULL,
        rejection_reason='Die zugehörige Fahrt ist storniert oder noch nicht abgeschlossen.',updated_at=NOW()
        WHERE tenant_id=NEW.tenant_id AND driving_log_id=v_log_id AND status<>'reimbursed';
    END IF;
    RETURN NEW;
  END IF;
  IF v_log_id IS NULL THEN
    INSERT INTO public.assist_driving_log(tenant_id,visit_id,employee_id,purpose,travel_type,started_at,ended_at,distance_km,start_address,end_address,status,notes,payroll_eligible,work_time_eligible,logbook_eligible,mileage_rate_cents,mileage_amount_cents)
    VALUES(NEW.tenant_id,NULL,NEW.employee_id,NEW.purpose,NEW.route_type,NEW.started_at,NEW.ended_at,NEW.distance_final_km,NEW.start_address,NEW.end_address,CASE WHEN NEW.status='corrected' THEN 'corrected' ELSE 'completed' END,'employee_logbook_trip:'||NEW.id::text,NEW.route_type<>'private_non_business',NEW.counts_as_work_time,TRUE,NEW.mileage_rate_cents,NEW.mileage_amount_cents)
    RETURNING id INTO v_log_id;
  ELSE
    UPDATE public.assist_driving_log SET purpose=NEW.purpose,travel_type=NEW.route_type,started_at=NEW.started_at,ended_at=NEW.ended_at,distance_km=NEW.distance_final_km,start_address=NEW.start_address,end_address=NEW.end_address,status=CASE WHEN NEW.status='corrected' THEN 'corrected' ELSE 'completed' END,payroll_eligible=NEW.route_type<>'private_non_business',work_time_eligible=NEW.counts_as_work_time,mileage_rate_cents=NEW.mileage_rate_cents,mileage_amount_cents=NEW.mileage_amount_cents,updated_at=NOW() WHERE id=v_log_id;
  END IF;
  IF NEW.route_type <> 'private_non_business' AND NEW.mileage_amount_cents > 0 THEN
    INSERT INTO public.employee_expense_claims(
      tenant_id,employee_id,expense_date,category,description,amount_cents,approved_amount_cents,
      mileage_km,mileage_rate_cents,origin,destination,business_purpose,tax_treatment,status,
      submitted_at,assignment_id,driving_log_id,travel_type,automatic_source
    ) VALUES(
      NEW.tenant_id,NEW.employee_id,(NEW.started_at AT TIME ZONE 'Europe/Berlin')::date,'mileage','Automatische Kilometervergütung aus Mitarbeiter-Fahrtenbuch',
      NEW.mileage_amount_cents,NULL,NEW.distance_final_km,NEW.mileage_rate_cents,
      NEW.start_address,NEW.end_address,NEW.purpose,'review','submitted',NOW(),NEW.assignment_id,v_log_id,NEW.route_type,TRUE
    ) ON CONFLICT(tenant_id,driving_log_id) WHERE driving_log_id IS NOT NULL DO UPDATE SET
      expense_date=EXCLUDED.expense_date,assignment_id=EXCLUDED.assignment_id,travel_type=EXCLUDED.travel_type,
      amount_cents=EXCLUDED.amount_cents,
      approved_amount_cents=CASE WHEN v_changed THEN NULL ELSE public.employee_expense_claims.approved_amount_cents END,
      mileage_km=EXCLUDED.mileage_km,mileage_rate_cents=EXCLUDED.mileage_rate_cents,
      origin=EXCLUDED.origin,destination=EXCLUDED.destination,business_purpose=EXCLUDED.business_purpose,
      status=CASE WHEN v_changed THEN 'submitted' ELSE public.employee_expense_claims.status END,
      tax_treatment=CASE WHEN v_changed THEN 'review' ELSE public.employee_expense_claims.tax_treatment END,
      reviewed_at=CASE WHEN v_changed THEN NULL ELSE public.employee_expense_claims.reviewed_at END,
      reviewed_by=CASE WHEN v_changed THEN NULL ELSE public.employee_expense_claims.reviewed_by END,
      rejection_reason=NULL,updated_at=NOW();
  ELSE
    UPDATE public.employee_expense_claims SET status='rejected',approved_amount_cents=NULL,
      rejection_reason='Für die geänderte Fahrt ist keine Kilometervergütung vorgesehen.',updated_at=NOW()
      WHERE tenant_id=NEW.tenant_id AND driving_log_id=v_log_id AND status<>'reimbursed';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_employee_logbook_completed_trip()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_corrected BOOLEAN;
  v_open_visit UUID;
BEGIN
  IF NOT public.is_employee_portal_rls_context(OLD.tenant_id) THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
    OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.employee_id IS DISTINCT FROM OLD.employee_id
    OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id
    OR NEW.assignment_id IS DISTINCT FROM OLD.assignment_id
    OR NEW.client_id IS DISTINCT FROM OLD.client_id
    OR NEW.route_type IS DISTINCT FROM OLD.route_type
    OR NEW.purpose IS DISTINCT FROM OLD.purpose
    OR NEW.started_at IS DISTINCT FROM OLD.started_at
    OR NEW.start_address IS DISTINCT FROM OLD.start_address
    OR NEW.source IS DISTINCT FROM OLD.source
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'Die Zuordnung einer Fahrt darf im Mitarbeitendenportal nicht verändert werden.';
  END IF;

  IF OLD.status = 'recording' AND NEW.status = 'review_required' THEN
    IF (OLD.started_at AT TIME ZONE 'Europe/Berlin')::date >= (NOW() AT TIME ZONE 'Europe/Berlin')::date
      OR NEW.ended_at IS NULL OR NEW.ended_at < OLD.started_at
      OR (NEW.ended_at AT TIME ZONE 'Europe/Berlin')::date <> (OLD.started_at AT TIME ZONE 'Europe/Berlin')::date
      OR NEW.employee_confirmed_at IS NOT NULL OR NEW.employee_confirmation_reason IS NOT NULL
      OR length(trim(coalesce(NEW.notes,''))) < 10
    THEN
      RAISE EXCEPTION 'Nur alte offene Fahrten dürfen mit einem vorläufigen Fahrtende zur Verwaltungsprüfung abgeschlossen werden.';
    END IF;
    -- Review never approves kilometres or changes employee/tenant ownership.
    NEW.distance_final_km := OLD.distance_final_km;
    NEW.mileage_rate_cents := OLD.mileage_rate_cents;
    NEW.mileage_amount_cents := OLD.mileage_amount_cents;
    NEW.counts_as_work_time := OLD.counts_as_work_time;
    NEW.worktime_deduction_minutes := OLD.worktime_deduction_minutes;
    NEW.previous_values := jsonb_build_object('status', OLD.status, 'ended_at', OLD.ended_at, 'distance_final_km', OLD.distance_final_km);
    RETURN NEW;
  END IF;

  IF OLD.status = 'recording' THEN
    IF NEW.status NOT IN ('recording', 'confirmation_required', 'cancelled') THEN
      RAISE EXCEPTION 'Eine Fahrt muss zuerst beendet und anschließend mit Kilometern bestätigt werden.';
    END IF;
    IF NEW.employee_confirmed_at IS NOT NULL OR NEW.employee_confirmation_reason IS NOT NULL THEN
      RAISE EXCEPTION 'Kilometer dürfen erst nach dem Fahrtende bestätigt werden.';
    END IF;
    IF NEW.status = 'confirmation_required' AND (
      NEW.ended_at IS NULL OR NEW.ended_at < OLD.started_at
      OR NEW.distance_final_km IS NULL OR NEW.distance_final_km < 0
      OR NEW.distance_final_km::TEXT IN ('NaN', 'Infinity', '-Infinity')
    ) THEN
      RAISE EXCEPTION 'Für die Kilometerprüfung fehlen ein gültiges Fahrtende oder gültige Kilometer.';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status IN ('completed','confirmed','corrected') AND NEW.status = 'confirmed' AND OLD.assignment_id IS NOT NULL THEN
    SELECT v.id INTO v_open_visit FROM public.assist_visits v
      WHERE v.tenant_id=OLD.tenant_id AND v.employee_id=OLD.employee_id
        AND (v.id=OLD.assignment_id OR v.legacy_assignment_id=OLD.assignment_id)
        AND v.canonical_status NOT IN ('completed','cancelled','no_show')
        AND v.planning_status NOT IN ('cancelled','draft')
        AND NOT EXISTS (SELECT 1 FROM public.assist_visit_execution_state es
          WHERE es.tenant_id=v.tenant_id AND es.visit_id=v.id AND es.finalized_at IS NOT NULL)
        AND NOT EXISTS (SELECT 1 FROM public.assignments a WHERE a.tenant_id=v.tenant_id
          AND a.id=v.legacy_assignment_id AND a.status::text IN ('completed','cancelled','no_show'))
      FOR UPDATE;
  END IF;
  IF (OLD.status <> 'confirmation_required' AND v_open_visit IS NULL) OR NEW.status <> 'confirmed' THEN
    RAISE EXCEPTION 'Der zugehörige Einsatz ist abgeschlossen. Diese Fahrt kann nur die Verwaltung korrigieren.';
  END IF;

  -- Confirmation must not change the trip, GPS evidence or office decisions.
  -- prepare_employee_logbook_trip runs before this guard; keep the rate from
  -- the finished trip and calculate the resulting amount server-side.
  NEW.mileage_rate_cents := OLD.mileage_rate_cents;
  NEW.mileage_amount_cents := CASE WHEN OLD.route_type = 'private_non_business' THEN 0
    ELSE ROUND(NEW.distance_final_km * OLD.mileage_rate_cents)::INTEGER END;
  IF (to_jsonb(NEW) - ARRAY[
      'status','distance_final_km','distance_source','route_quality_status',
      'employee_confirmed_at','employee_confirmation_reason','previous_values',
      'updated_at','mileage_amount_cents'
    ]) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY[
      'status','distance_final_km','distance_source','route_quality_status',
      'employee_confirmed_at','employee_confirmation_reason','previous_values',
      'updated_at','mileage_amount_cents'
    ]) THEN
    RAISE EXCEPTION 'Bei der Kilometerbestätigung dürfen nur Kilometer und ihre Begründung geändert werden.';
  END IF;

  IF OLD.ended_at IS NULL OR NEW.employee_confirmed_at IS NULL
    OR NEW.distance_final_km IS NULL OR NEW.distance_final_km < 0
    OR NEW.distance_final_km::TEXT IN ('NaN', 'Infinity', '-Infinity') THEN
    RAISE EXCEPTION 'Die Kilometerbestätigung ist unvollständig.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.employee_logbook_segments segment
    WHERE segment.trip_id = OLD.id AND segment.tenant_id = OLD.tenant_id
      AND segment.employee_id = OLD.employee_id AND segment.ended_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Vor der Kilometerbestätigung müssen die offenen Teilstrecken beendet werden.';
  END IF;

  v_corrected := ABS(NEW.distance_final_km - OLD.distance_final_km) >= 0.005;
  IF v_corrected AND LENGTH(BTRIM(COALESCE(NEW.employee_confirmation_reason, ''))) < 3 THEN
    RAISE EXCEPTION 'Bitte die Kilometerkorrektur kurz begründen.';
  END IF;
  NEW.distance_source := CASE WHEN v_corrected THEN 'manual' ELSE OLD.distance_source END;
  NEW.route_quality_status := CASE WHEN v_corrected THEN 'corrected' ELSE OLD.route_quality_status END;
  NEW.previous_values := CASE WHEN v_corrected THEN jsonb_build_object(
    'distance_final_km', OLD.distance_final_km, 'status', OLD.status
  ) ELSE NULL END;
  NEW.employee_confirmation_reason := CASE WHEN v_corrected
    THEN BTRIM(NEW.employee_confirmation_reason) ELSE NULL END;
  IF v_open_visit IS NOT NULL AND v_corrected THEN
    UPDATE public.assist_visit_signatures SET is_valid=FALSE, invalidated_at=now(),
      invalidation_reason='Kilometer vor Einsatzabschluss korrigiert.', updated_at=now()
      WHERE tenant_id=OLD.tenant_id AND visit_id=v_open_visit AND is_valid;
    UPDATE public.assist_visit_proofs SET signature_id=NULL, portal_visible=FALSE,
      portal_release_status='none', updated_at=now() WHERE tenant_id=OLD.tenant_id AND visit_id=v_open_visit;
    UPDATE public.assist_visit_execution_state SET signature_complete=FALSE,proof_generated=FALSE,updated_at=now()
      WHERE tenant_id=OLD.tenant_id AND visit_id=v_open_visit;
  END IF;
  NEW.employee_confirmed_at := NOW();
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_client_offboarding(p_tenant_id uuid, p_client_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_case public.client_offboarding_cases%ROWTYPE;
  v_failed INTEGER;
  v_message TEXT;
BEGIN
  PERFORM public.client_offboarding_assert_admin(p_tenant_id);
  PERFORM public.refresh_client_offboarding_checks(p_tenant_id,p_client_id,p_actor_id);
  SELECT * INTO v_case FROM public.client_offboarding_cases
  WHERE tenant_id=p_tenant_id AND client_id=p_client_id
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF v_case.effective_date>CURRENT_DATE THEN
    RAISE EXCEPTION 'Die Endfreigabe ist erst am Beendigungsdatum möglich.';
  END IF;
  IF v_case.portal_closure_mode='read_only_grace' AND v_case.portal_grace_until>NOW() THEN
    RAISE EXCEPTION 'Die Endfreigabe ist erst nach Ablauf der Portal-Nachfrist möglich.';
  END IF;
  SELECT COUNT(*),STRING_AGG(message,'; ' ORDER BY check_key)
  INTO v_failed,v_message FROM public.client_offboarding_checks
  WHERE case_id=v_case.id AND severity='required' AND status='failed';
  IF v_failed>0 THEN RAISE EXCEPTION 'Endfreigabe blockiert: %',v_message; END IF;

  PERFORM public.lock_client_offboarding_portal(p_tenant_id,p_client_id,p_actor_id);
  UPDATE public.client_offboarding_actions SET status='completed',completed_at=NOW(),completed_by=p_actor_id,
    notes='Operative Nutzung beendet; Akte erhalten',updated_at=NOW()
  WHERE case_id=v_case.id AND action_key='archive_client_record';
  UPDATE public.clients SET status='archived',updated_at=NOW() WHERE tenant_id=p_tenant_id AND id=p_client_id;
  UPDATE public.client_offboarding_cases SET status='completed',completed_at=NOW(),archived_at=NOW(),updated_at=NOW()
  WHERE id=v_case.id;
  INSERT INTO public.client_offboarding_audit_events(case_id,tenant_id,client_id,action,detail,metadata,actor_id)
  VALUES(v_case.id,p_tenant_id,p_client_id,'offboarding_completed',
    'Klient:innenakte archiviert; operative Nutzung und Zugänge beendet; Historie vollständig erhalten',
    jsonb_build_object('legal_hold',v_case.legal_hold,'effective_date',v_case.effective_date),p_actor_id);
  RETURN jsonb_build_object('case_id',v_case.id,'status','completed','archived',TRUE);
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_offboarding_invalidate_push_devices(p_tenant_id uuid, p_employee_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count INTEGER := 0;
BEGIN
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht mit der Sitzung überein.';
  END IF;
  IF NOT (public.is_tenant_admin() OR public.has_permission('office.employees.edit')) THEN
    RAISE EXCEPTION 'Keine Berechtigung für Mitarbeitenden-Offboarding.';
  END IF;
  UPDATE public.portal_push_devices SET enabled=FALSE,invalidated_at=NOW(),
    last_error='Mitarbeitenden-Offboarding',updated_at=NOW()
  WHERE tenant_id=p_tenant_id AND employee_id=p_employee_id AND enabled=TRUE;
  GET DIAGNOSTICS v_count=ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.portal_create_office_thread(p_tenant_id uuid, p_audience text, p_subject text, p_category_id uuid DEFAULT NULL::uuid, p_initial_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_tenant_id UUID := public.current_tenant_id();
  v_employee_id UUID;
  v_client_id UUID;
  v_thread public.message_threads%ROWTYPE;
  v_subject TEXT := btrim(COALESCE(p_subject, ''));
  v_message TEXT := btrim(COALESCE(p_initial_message, ''));
  v_now TIMESTAMPTZ := now();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Anmeldung erforderlich.' USING ERRCODE = '42501';
  END IF;
  IF v_tenant_id IS NULL OR p_tenant_id IS DISTINCT FROM v_tenant_id THEN
    RAISE EXCEPTION 'Mandant der Sitzung stimmt nicht überein.' USING ERRCODE = '42501';
  END IF;
  IF v_subject = '' THEN
    RAISE EXCEPTION 'Betreff darf nicht leer sein.' USING ERRCODE = '22023';
  END IF;
  IF p_audience NOT IN ('employee', 'client') THEN
    RAISE EXCEPTION 'Portaltyp ist ungültig.' USING ERRCODE = '22023';
  END IF;

  IF p_category_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.message_categories category
    WHERE category.id = p_category_id
      AND category.tenant_id = v_tenant_id
      AND category.is_active = TRUE
      AND category.audience::TEXT IN (p_audience, 'all')
  ) THEN
    RAISE EXCEPTION 'Das gewählte Thema ist nicht verfügbar.' USING ERRCODE = '22023';
  END IF;

  IF p_audience = 'employee' THEN
    v_employee_id := public.resolve_current_employee_id();
    IF v_employee_id IS NULL THEN
      RAISE EXCEPTION 'Kein Mitarbeitendenkonto mit dieser Sitzung verknüpft.' USING ERRCODE = '42501';
    END IF;
  ELSE
    v_client_id := public.current_client_id();
    IF v_client_id IS NULL THEN
      RAISE EXCEPTION 'Kein Klient:innenkonto mit dieser Sitzung verknüpft.' USING ERRCODE = '42501';
    END IF;
  END IF;

  INSERT INTO public.message_threads (
    tenant_id,
    thread_type,
    status,
    priority,
    subject,
    category_id,
    client_id,
    employee_id,
    created_by_client_id,
    created_by_employee_id,
    last_message_at,
    last_message_preview
  ) VALUES (
    v_tenant_id,
    CASE WHEN p_audience = 'employee'
      THEN 'employee'::public.message_thread_type
      ELSE 'client'::public.message_thread_type
    END,
    'new',
    'normal',
    v_subject,
    p_category_id,
    v_client_id,
    v_employee_id,
    v_client_id,
    v_employee_id,
    v_now,
    CASE WHEN v_message = '' THEN 'Neuer Chat' ELSE left(v_message, 120) END
  )
  RETURNING * INTO v_thread;

  IF v_message <> '' THEN
    INSERT INTO public.messages (
      tenant_id,
      thread_id,
      body,
      is_internal_note,
      is_system_message,
      sender_client_id,
      sender_employee_id,
      sent_at,
      status
    ) VALUES (
      v_tenant_id,
      v_thread.id,
      v_message,
      FALSE,
      FALSE,
      v_client_id,
      v_employee_id,
      v_now,
      'sent'
    );
  END IF;

  RETURN to_jsonb(v_thread);
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_employee_open_visit_documentation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v public.assist_visits%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
      OR NEW.visit_id IS DISTINCT FROM OLD.visit_id OR NEW.id IS DISTINCT FROM OLD.id) THEN
    IF public.is_employee_portal_rls_context(OLD.tenant_id) THEN
      RAISE EXCEPTION 'Die Dokumentation darf keinem anderen Einsatz zugeordnet werden.';
    END IF;
  END IF;
  IF NOT public.is_employee_portal_rls_context(NEW.tenant_id) THEN RETURN NEW; END IF;
  -- A pure lock/metadata update is not a new employee submission.
  IF TG_OP = 'UPDATE' AND
    (to_jsonb(NEW)-ARRAY['updated_at','locked','metadata']) IS NOT DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['updated_at','locked','metadata']) THEN RETURN NEW; END IF;
  SELECT * INTO v FROM public.assist_visits WHERE id=NEW.visit_id
    AND tenant_id=NEW.tenant_id AND tenant_id=public.current_tenant_id() FOR UPDATE;
  IF NOT FOUND OR v.employee_id IS DISTINCT FROM public.resolve_current_employee_id() THEN
    RAISE EXCEPTION 'Dieser Einsatz ist Ihnen nicht zugeordnet.';
  END IF;
  IF v.canonical_status IN ('completed','cancelled','no_show') OR v.planning_status IN ('cancelled','draft')
    OR EXISTS (SELECT 1 FROM public.assist_visit_execution_state es WHERE es.tenant_id=v.tenant_id
      AND es.visit_id=v.id AND es.finalized_at IS NOT NULL)
    OR EXISTS (SELECT 1 FROM public.assignments a WHERE a.tenant_id=v.tenant_id
      AND a.id=v.legacy_assignment_id AND a.status::text IN ('completed','cancelled','no_show')) THEN
    RAISE EXCEPTION 'Dieser Einsatz ist bereits abgeschlossen oder nicht zur Bearbeitung freigegeben.';
  END IF;
  UPDATE public.assist_visit_signatures SET is_valid=FALSE,invalidated_at=now(),
    invalidation_reason='Dokumentation vor Einsatzabschluss erneut gespeichert.',updated_at=now()
    WHERE tenant_id=v.tenant_id AND visit_id=v.id AND is_valid;
  UPDATE public.assist_visit_proofs SET signature_id=NULL,portal_visible=FALSE,
    portal_release_status='none',updated_at=now() WHERE tenant_id=v.tenant_id AND visit_id=v.id;
  UPDATE public.assist_visit_execution_state SET signature_complete=FALSE,proof_generated=FALSE,updated_at=now()
    WHERE tenant_id=v.tenant_id AND visit_id=v.id;
  IF TG_OP='UPDATE' THEN
    INSERT INTO public.assist_visit_admin_audit(tenant_id,visit_id,action,previous_value,new_value,reason)
    VALUES(v.tenant_id,v.id,'documentation_updated',to_jsonb(OLD),
      to_jsonb(NEW)||jsonb_build_object('actor_kind','employee_open_visit_edit'),
      'Dokumentation vom Mitarbeitenden vor Abschluss erneut gespeichert.');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_portal_release_deferred_signature(p_tenant_id uuid, p_proof_id uuid, p_client_id uuid, p_title text, p_payload_snapshot jsonb, p_payload_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_visit_id uuid;
  v_employee_id uuid;
  v_actor_profile_id uuid;
  v_signature_id uuid;
  v_doc_title text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: authentication required';
  END IF;
  IF p_tenant_id IS NULL OR p_proof_id IS NULL OR p_client_id IS NULL
     OR p_payload_snapshot IS NULL OR nullif(trim(coalesce(p_payload_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: missing required parameters';
  END IF;
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: tenant mismatch';
  END IF;
  IF NOT public.is_employee_portal_rls_context(p_tenant_id) THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: employee portal role required';
  END IF;

  v_employee_id := public.resolve_current_employee_id();
  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: employee not resolved';
  END IF;

  v_actor_profile_id := public.resolve_current_profile_id();
  IF v_actor_profile_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: profile not resolved';
  END IF;

  SELECT avp.visit_id, avp.signature_id
    INTO v_visit_id, v_signature_id
  FROM public.assist_visit_proofs avp
  WHERE avp.tenant_id = p_tenant_id
    AND avp.id = p_proof_id
  FOR UPDATE;

  IF v_visit_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: proof not found';
  END IF;
  IF v_signature_id IS NOT NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: proof already signed';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.assist_visits v
    WHERE v.tenant_id = p_tenant_id
      AND v.id = v_visit_id
      AND v.client_id = p_client_id
      AND v.employee_id = v_employee_id
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.assignments a
    JOIN public.assist_visits v
      ON v.tenant_id = a.tenant_id
     AND (v.legacy_assignment_id = a.id OR v.id = a.id)
    WHERE a.tenant_id = p_tenant_id
      AND v.id = v_visit_id
      AND a.client_id = p_client_id
      AND a.employee_id = v_employee_id
  ) THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: visit not assigned to employee';
  END IF;

  UPDATE public.assist_visit_proofs
  SET payload_snapshot = p_payload_snapshot,
      payload_hash = trim(p_payload_hash),
      signature_id = NULL,
      portal_visible = TRUE,
      portal_release_status = 'pending_client_signature',
      released_to_portal_at = now(),
      updated_by = v_actor_profile_id,
      updated_at = now()
  WHERE tenant_id = p_tenant_id
    AND id = p_proof_id
    AND signature_id IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: proof update failed';
  END IF;

  v_doc_title := coalesce(nullif(trim(p_title), ''), 'Leistungsnachweis') ||
    ' ÔÇö Unterschrift ausstehend';

  INSERT INTO public.client_documents (
    id, tenant_id, client_id, title, file_name, mime_type, category,
    storage_path, portal_visible, status, sensitivity, source, uploaded_by,
    signed_at, signature_required, updated_at
  ) VALUES (
    p_proof_id, p_tenant_id, p_client_id, v_doc_title,
    'unterschrift-' || p_proof_id::text || '.pending', 'application/pdf',
    'leistungsnachweis', NULL, TRUE, 'aktiv', 'care', 'assist_visit_proof',
    v_actor_profile_id, NULL, TRUE, now()
  )
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    file_name = EXCLUDED.file_name,
    storage_path = NULL,
    portal_visible = TRUE,
    status = 'aktiv',
    category = 'leistungsnachweis',
    signed_at = NULL,
    signature_required = TRUE,
    source = 'assist_visit_proof',
    updated_at = now()
  WHERE client_documents.tenant_id = EXCLUDED.tenant_id
    AND client_documents.client_id = EXCLUDED.client_id
    AND client_documents.source = 'assist_visit_proof';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: document id conflict';
  END IF;

  RETURN p_proof_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_release_deferred_signature(p_tenant_id uuid, p_proof_id uuid, p_client_id uuid, p_title text, p_payload_snapshot jsonb, p_payload_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid;
  v_proof public.assist_visit_proofs%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Anmeldung ist erforderlich';
  END IF;
  IF p_tenant_id IS NULL OR p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht überein';
  END IF;
  IF NOT coalesce(public.is_tenant_admin() OR public.has_permission('assist.execution.manage'), FALSE) THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  v_actor := public.resolve_current_profile_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Angemeldetes Verwaltungsprofil konnte nicht zugeordnet werden';
  END IF;
  IF p_proof_id IS NULL OR p_client_id IS NULL
     OR p_payload_snapshot IS NULL OR jsonb_typeof(p_payload_snapshot) <> 'object'
     OR nullif(trim(coalesce(p_payload_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Angaben zur Signaturanforderung sind unvollständig';
  END IF;

  SELECT * INTO v_proof
  FROM public.assist_visit_proofs
  WHERE tenant_id = p_tenant_id AND id = p_proof_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Nachweis nicht gefunden'; END IF;

  PERFORM 1 FROM public.assist_visits
  WHERE tenant_id = p_tenant_id AND id = v_proof.visit_id AND client_id = p_client_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Signaturanforderung ist nicht eindeutig dem Klienten zugeordnet';
  END IF;
  IF v_proof.signature_id IS NOT NULL OR v_proof.status IN ('approved', 'exported', 'archived') THEN
    RAISE EXCEPTION 'Der Nachweis ist bereits unterschrieben oder freigegeben';
  END IF;

  IF v_proof.portal_visible AND v_proof.portal_release_status = 'pending_client_signature' THEN
    IF EXISTS (
      SELECT 1 FROM public.client_documents
      WHERE id = p_proof_id AND tenant_id = p_tenant_id AND client_id = p_client_id
        AND source = 'assist_visit_proof' AND portal_visible
        AND signature_required AND signed_at IS NULL AND status = 'aktiv'
    ) THEN
      RETURN p_proof_id;
    END IF;
  ELSE
    UPDATE public.assist_visit_proofs
    SET payload_snapshot = p_payload_snapshot,
        payload_hash = trim(p_payload_hash),
        portal_visible = TRUE,
        portal_release_status = 'pending_client_signature',
        released_to_portal_at = now(),
        updated_by = v_actor,
        updated_at = now()
    WHERE id = p_proof_id AND tenant_id = p_tenant_id;
  END IF;

  INSERT INTO public.client_documents (
    id, tenant_id, client_id, title, file_name, mime_type, category,
    storage_path, portal_visible, status, sensitivity, source, uploaded_by,
    signed_at, signature_required, updated_at
  ) VALUES (
    p_proof_id, p_tenant_id, p_client_id,
    coalesce(nullif(trim(p_title), ''), 'Leistungsnachweis') || ' — Unterschrift ausstehend',
    'unterschrift-' || p_proof_id::text || '.pending', 'application/pdf',
    'leistungsnachweis', NULL, TRUE, 'aktiv', 'care', 'assist_visit_proof',
    v_actor, NULL, TRUE, now()
  )
  ON CONFLICT (id) DO UPDATE SET
    portal_visible = TRUE,
    signature_required = TRUE,
    status = 'aktiv',
    updated_at = now()
  WHERE client_documents.tenant_id = EXCLUDED.tenant_id
    AND client_documents.client_id = EXCLUDED.client_id
    AND client_documents.source = 'assist_visit_proof'
    AND client_documents.signed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Portal-Dokument ist bereits unterschrieben oder nicht eindeutig zugeordnet';
  END IF;
  RETURN p_proof_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.support_create_ticket(p_subject text, p_body text, p_category text, p_priority text, p_client_nonce uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_tenant uuid; v_ticket public.support_workspace_tickets%ROWTYPE; v_name text;
BEGIN
  SELECT p.tenant_id,trim(concat_ws(' ',p.first_name,p.last_name)) INTO v_tenant,v_name FROM public.profiles p
    WHERE p.auth_user_id=auth.uid() AND p.status='active' AND p.is_active LIMIT 1;
  IF NOT coalesce(public.support_is_tenant_member(v_tenant),false) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  IF p_client_nonce IS NULL OR coalesce(length(trim(p_body)),0) NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'support_invalid_message' USING ERRCODE='22023'; END IF;
  INSERT INTO public.support_workspace_tickets(tenant_id,created_by,client_nonce,subject,category,priority)
  VALUES(v_tenant,auth.uid(),p_client_nonce,trim(p_subject),p_category,p_priority)
  ON CONFLICT(created_by,client_nonce) DO NOTHING RETURNING * INTO v_ticket;
  IF NOT FOUND THEN
    SELECT * INTO v_ticket FROM public.support_workspace_tickets WHERE created_by=auth.uid() AND client_nonce=p_client_nonce AND tenant_id=v_tenant;
    IF NOT FOUND THEN RAISE EXCEPTION 'support_invalid_retry' USING ERRCODE='22023'; END IF;
    RETURN to_jsonb(v_ticket);
  END IF;
  INSERT INTO public.support_messages(ticket_id,tenant_id,author_id,author_kind,author_name,body,client_nonce)
    VALUES(v_ticket.id,v_tenant,auth.uid(),'tenant',coalesce(nullif(v_name,''),'Unternehmen'),trim(p_body),p_client_nonce);
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event) VALUES(v_ticket.id,auth.uid(),'ticket.created');
  RETURN to_jsonb(v_ticket);
END; $function$

CREATE OR REPLACE FUNCTION public.support_decide_access(p_request_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_request public.support_access_requests%ROWTYPE; v_ticket public.support_workspace_tickets%ROWTYPE;
BEGIN
  SELECT * INTO v_request FROM public.support_access_requests WHERE id=p_request_id;
  IF NOT FOUND OR NOT public.support_is_tenant_admin(v_request.tenant_id) THEN RAISE EXCEPTION 'support_tenant_approval_required' USING ERRCODE='42501'; END IF;
  -- Consistent lock order with ticket closure and protected workspace calls.
  SELECT * INTO v_ticket FROM public.support_workspace_tickets WHERE id=v_request.ticket_id FOR UPDATE;
  SELECT * INTO v_request FROM public.support_access_requests WHERE id=p_request_id FOR UPDATE;
  IF p_decision='approve' THEN
    IF v_request.status<>'requested' OR v_request.created_at<now()-interval '1 day' OR v_ticket.status IN ('resolved','closed') THEN RAISE EXCEPTION 'support_request_inactive' USING ERRCODE='22023'; END IF;
    UPDATE public.support_access_requests SET status='approved',approved_by=auth.uid(),approved_at=now(),expires_at=now()+make_interval(mins=>duration_minutes) WHERE id=p_request_id RETURNING * INTO v_request;
  ELSIF p_decision='reject' AND v_request.status='requested' THEN
    UPDATE public.support_access_requests SET status='rejected' WHERE id=p_request_id RETURNING * INTO v_request;
  ELSIF p_decision='revoke' AND v_request.status IN ('requested','approved') THEN
    UPDATE public.support_access_requests SET status='revoked',revoked_at=now() WHERE id=p_request_id RETURNING * INTO v_request;
  ELSE RAISE EXCEPTION 'support_invalid_decision' USING ERRCODE='22023'; END IF;
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event,details) VALUES(v_request.ticket_id,auth.uid(),'access.'||p_decision,jsonb_build_object('request',p_request_id,'scopes',v_request.scopes,'expires_at',v_request.expires_at));
  RETURN to_jsonb(v_request);
END; $function$

CREATE OR REPLACE FUNCTION public.support_request_access(p_ticket_id uuid, p_reason text, p_scopes text[], p_duration_minutes integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ticket public.support_workspace_tickets%ROWTYPE; v_operator public.platform_users%ROWTYPE; v_request public.support_access_requests%ROWTYPE;
BEGIN
  IF NOT public.platform_has_capability('support.write') THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_ticket FROM public.support_workspace_tickets WHERE id=p_ticket_id FOR UPDATE;
  IF NOT FOUND OR v_ticket.status IN ('resolved','closed') THEN RAISE EXCEPTION 'support_ticket_closed' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_operator FROM public.platform_users WHERE user_id=auth.uid() AND status='active';
  IF EXISTS(SELECT 1 FROM public.support_access_requests WHERE ticket_id=p_ticket_id AND platform_user_id=v_operator.id AND status='requested' AND created_at>now()-interval '1 day') THEN
    RAISE EXCEPTION 'support_request_pending' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.support_access_requests(ticket_id,tenant_id,platform_user_id,requester_name,reason,scopes,duration_minutes)
  VALUES(p_ticket_id,v_ticket.tenant_id,v_operator.id,coalesce(nullif(v_operator.full_name,''),v_operator.email),trim(p_reason),p_scopes,p_duration_minutes) RETURNING * INTO v_request;
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event,details) VALUES(p_ticket_id,auth.uid(),'access.requested',jsonb_build_object('request',v_request.id,'scopes',p_scopes,'minutes',p_duration_minutes));
  RETURN to_jsonb(v_request);
END; $function$

CREATE OR REPLACE FUNCTION public.support_set_ticket_status(p_ticket_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.support_can_write_ticket(p_ticket_id) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.support_workspace_tickets WHERE id=p_ticket_id FOR UPDATE;
  UPDATE public.support_workspace_tickets SET status=p_status,updated_at=now() WHERE id=p_ticket_id;
  IF p_status IN ('resolved','closed') THEN
    UPDATE public.support_access_requests SET status='revoked',revoked_at=now() WHERE ticket_id=p_ticket_id AND status IN ('requested','approved');
  END IF;
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event,details) VALUES(p_ticket_id,auth.uid(),'ticket.status',jsonb_build_object('status',p_status));
END; $function$

CREATE OR REPLACE FUNCTION public.support_begin_discard_attachment(p_attachment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_row public.support_attachments%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.support_attachments WHERE id=p_attachment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.support_workspace_tickets WHERE id=v_row.ticket_id FOR UPDATE;
  SELECT * INTO v_row FROM public.support_attachments WHERE id=p_attachment_id FOR UPDATE;
  IF v_row.created_by IS DISTINCT FROM auth.uid() OR v_row.message_id IS NOT NULL OR NOT public.support_can_write_ticket(v_row.ticket_id) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  UPDATE public.support_attachments SET state='discarding' WHERE id=p_attachment_id RETURNING * INTO v_row;
  RETURN to_jsonb(v_row);
END; $function$

CREATE OR REPLACE FUNCTION public.support_discard_attachment(p_attachment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_row public.support_attachments%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.support_attachments WHERE id=p_attachment_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_row.created_by IS DISTINCT FROM auth.uid() OR v_row.message_id IS NOT NULL OR NOT public.support_can_write_ticket(v_row.ticket_id) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='support-ticket-attachments' AND name=v_row.storage_path) THEN RAISE EXCEPTION 'support_upload_still_exists' USING ERRCODE='22023'; END IF;
  DELETE FROM public.support_attachments WHERE id=p_attachment_id;
END; $function$

CREATE OR REPLACE FUNCTION public.support_finalize_attachment(p_attachment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_row public.support_attachments%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.support_attachments WHERE id=p_attachment_id FOR UPDATE;
  IF NOT FOUND OR v_row.created_by<>auth.uid() OR v_row.message_id IS NOT NULL OR v_row.state='discarding' OR NOT public.support_can_write_ticket(v_row.ticket_id) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='support-ticket-attachments' AND name=v_row.storage_path AND (metadata->>'size')::bigint=v_row.byte_size AND metadata->>'mimetype'=v_row.mime_type) THEN
    RAISE EXCEPTION 'support_upload_incomplete' USING ERRCODE='22023';
  END IF;
  UPDATE public.support_attachments SET state='ready' WHERE id=p_attachment_id RETURNING * INTO v_row;
  RETURN to_jsonb(v_row);
END; $function$

CREATE OR REPLACE FUNCTION public.support_reserve_attachment(p_ticket_id uuid, p_file_name text, p_mime_type text, p_byte_size bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_tenant uuid; v_id uuid:=gen_random_uuid(); v_row public.support_attachments%ROWTYPE;
BEGIN
  IF NOT public.support_can_write_ticket(p_ticket_id) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  SELECT tenant_id INTO v_tenant FROM public.support_workspace_tickets WHERE id=p_ticket_id;
  IF (SELECT count(*) FROM public.support_attachments WHERE ticket_id=p_ticket_id AND created_by=auth.uid() AND message_id IS NULL AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'support_upload_limit' USING ERRCODE='22023'; END IF;
  INSERT INTO public.support_attachments(id,ticket_id,tenant_id,created_by,file_name,mime_type,byte_size,storage_path)
  VALUES(v_id,p_ticket_id,v_tenant,auth.uid(),left(regexp_replace(p_file_name,'[[:cntrl:]/\\]','_','g'),180),p_mime_type,p_byte_size,v_tenant::text||'/'||p_ticket_id::text||'/'||v_id::text) RETURNING * INTO v_row;
  RETURN to_jsonb(v_row);
END; $function$

CREATE OR REPLACE FUNCTION public.support_send_message(p_ticket_id uuid, p_body text, p_client_nonce uuid, p_attachment_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ticket public.support_workspace_tickets%ROWTYPE; v_message public.support_messages%ROWTYPE; v_name text; v_platform boolean;
BEGIN
  IF NOT public.support_can_write_ticket(p_ticket_id) THEN RAISE EXCEPTION 'support_forbidden' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_ticket FROM public.support_workspace_tickets WHERE id=p_ticket_id FOR UPDATE;
  SELECT * INTO v_message FROM public.support_messages WHERE author_id=auth.uid() AND client_nonce=p_client_nonce;
  IF FOUND THEN
    IF v_message.ticket_id<>p_ticket_id OR v_message.body<>trim(coalesce(p_body,'')) THEN RAISE EXCEPTION 'support_invalid_retry' USING ERRCODE='22023'; END IF;
    RETURN to_jsonb(v_message);
  END IF;
  IF p_client_nonce IS NULL OR p_attachment_ids IS NULL OR cardinality(p_attachment_ids)>5 OR length(coalesce(p_body,''))>10000 OR (trim(coalesce(p_body,''))='' AND cardinality(p_attachment_ids)=0) THEN RAISE EXCEPTION 'support_invalid_message' USING ERRCODE='22023'; END IF;
  IF cardinality(p_attachment_ids)<>(SELECT count(*) FROM public.support_attachments WHERE id=ANY(p_attachment_ids) AND ticket_id=p_ticket_id AND tenant_id=v_ticket.tenant_id AND created_by=auth.uid() AND state='ready' AND message_id IS NULL) THEN RAISE EXCEPTION 'support_invalid_attachment' USING ERRCODE='22023'; END IF;
  v_platform := public.platform_has_capability('support.write');
  IF v_platform THEN SELECT coalesce(nullif(full_name,''),email) INTO v_name FROM public.platform_users WHERE user_id=auth.uid() AND status='active';
  ELSE SELECT trim(concat_ws(' ',first_name,last_name)) INTO v_name FROM public.profiles WHERE auth_user_id=auth.uid() AND tenant_id=v_ticket.tenant_id AND status='active'; END IF;
  INSERT INTO public.support_messages(ticket_id,tenant_id,author_id,author_kind,author_name,body,client_nonce)
  VALUES(p_ticket_id,v_ticket.tenant_id,auth.uid(),CASE WHEN v_platform THEN 'platform' ELSE 'tenant' END,coalesce(nullif(v_name,''),'Unternehmen'),trim(coalesce(p_body,'')),p_client_nonce) RETURNING * INTO v_message;
  UPDATE public.support_attachments SET message_id=v_message.id WHERE id=ANY(p_attachment_ids);
  UPDATE public.support_workspace_tickets SET updated_at=now(),status=CASE WHEN v_platform THEN 'waiting_tenant' ELSE 'waiting_support' END WHERE id=p_ticket_id;
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event,details) VALUES(p_ticket_id,auth.uid(),'message.sent',jsonb_build_object('message',v_message.id,'attachments',cardinality(p_attachment_ids)));
  RETURN to_jsonb(v_message);
END; $function$

CREATE OR REPLACE FUNCTION public.support_workspace_read(p_request_id uuid, p_scope text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_request public.support_access_requests%ROWTYPE; v_rows jsonb; v_offset integer:=greatest(0,least(coalesce(p_offset,0),100000));
BEGIN
  v_request:=public.support_assert_access(p_request_id,p_scope);
  CASE p_scope
    WHEN 'company.read' THEN
      SELECT jsonb_build_array(jsonb_build_object('id',id,'name',name,'legal_name',legal_name,'street',street,'house_number',house_number,'postal_code',postal_code,'city',city,'email',email,'phone',phone,'website',website,'updated_at',updated_at)) INTO v_rows FROM public.tenants WHERE id=v_request.tenant_id;
    WHEN 'assignments.read' THEN
      SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO v_rows FROM (SELECT id,title,assignment_date,planned_start_at,planned_end_at,actual_start_at,actual_end_at,canonical_status,documentation_status,proof_status,internal_notes,updated_at FROM public.assist_visits WHERE tenant_id=v_request.tenant_id ORDER BY assignment_date DESC,id LIMIT 51 OFFSET v_offset) q;
    WHEN 'clients.read' THEN
      SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO v_rows FROM (SELECT id,client_number,first_name,last_name,status,updated_at FROM public.clients WHERE tenant_id=v_request.tenant_id AND deleted_at IS NULL ORDER BY last_name,id LIMIT 51 OFFSET v_offset) q;
    WHEN 'employees.read' THEN
      SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]') INTO v_rows FROM (SELECT id,employee_number,first_name,last_name,status,portal_enabled,updated_at FROM public.employees WHERE tenant_id=v_request.tenant_id AND deleted_at IS NULL ORDER BY last_name,id LIMIT 51 OFFSET v_offset) q;
    ELSE RAISE EXCEPTION 'support_scope_invalid' USING ERRCODE='22023';
  END CASE;
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event,details) VALUES(v_request.ticket_id,auth.uid(),'workspace.read',jsonb_build_object('request',p_request_id,'scope',p_scope));
  RETURN jsonb_build_object('rows',coalesce(v_rows,'[]'),'expires_at',v_request.expires_at,'scope',p_scope);
END; $function$

CREATE OR REPLACE FUNCTION public.support_workspace_update(p_request_id uuid, p_scope text, p_record_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_request public.support_access_requests%ROWTYPE; v_key text; v_count integer; v_legacy uuid;
BEGIN
  v_request:=public.support_assert_access(p_request_id,p_scope);
  IF jsonb_typeof(p_patch) IS DISTINCT FROM 'object' OR p_patch='{}'::jsonb OR p_expected_updated_at IS NULL THEN RAISE EXCEPTION 'support_patch_invalid' USING ERRCODE='22023'; END IF;
  IF p_scope='company.write' THEN
    IF p_record_id<>v_request.tenant_id THEN RAISE EXCEPTION 'support_access_denied' USING ERRCODE='42501'; END IF;
    FOR v_key IN SELECT jsonb_object_keys(p_patch) LOOP
      IF NOT(v_key=ANY(ARRAY['name','legal_name','street','house_number','postal_code','city','email','phone','website'])) OR jsonb_typeof(p_patch->v_key)<>'string' OR length(p_patch->>v_key)>200 THEN RAISE EXCEPTION 'support_patch_invalid' USING ERRCODE='22023'; END IF;
    END LOOP;
    IF p_patch ? 'name' AND trim(p_patch->>'name')='' THEN RAISE EXCEPTION 'support_patch_invalid' USING ERRCODE='22023'; END IF;
    UPDATE public.tenants SET name=coalesce(p_patch->>'name',name),legal_name=coalesce(p_patch->>'legal_name',legal_name),street=coalesce(p_patch->>'street',street),house_number=coalesce(p_patch->>'house_number',house_number),postal_code=coalesce(p_patch->>'postal_code',postal_code),city=coalesce(p_patch->>'city',city),email=coalesce(p_patch->>'email',email),phone=coalesce(p_patch->>'phone',phone),website=coalesce(p_patch->>'website',website),updated_at=now()
    WHERE id=v_request.tenant_id AND updated_at=p_expected_updated_at;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count=1 THEN UPDATE public.platform_tenants SET tenant_name=coalesce(p_patch->>'name',tenant_name),legal_name=coalesce(p_patch->>'legal_name',legal_name),updated_at=now() WHERE tenant_id=v_request.tenant_id; END IF;
  ELSIF p_scope='assignments.notes.write' THEN
    IF (SELECT count(*) FROM jsonb_object_keys(p_patch))<>1 OR NOT(p_patch ? 'internal_notes') OR jsonb_typeof(p_patch->'internal_notes')<>'string' OR length(p_patch->>'internal_notes')>10000 THEN RAISE EXCEPTION 'support_patch_invalid' USING ERRCODE='22023'; END IF;
    UPDATE public.assist_visits SET internal_notes=p_patch->>'internal_notes',updated_at=now() WHERE id=p_record_id AND tenant_id=v_request.tenant_id AND updated_at=p_expected_updated_at RETURNING legacy_assignment_id INTO v_legacy;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count=1 AND v_legacy IS NOT NULL THEN UPDATE public.assignments SET internal_notes=p_patch->>'internal_notes',updated_at=now() WHERE id=v_legacy AND tenant_id=v_request.tenant_id; END IF;
  ELSE RAISE EXCEPTION 'support_scope_invalid' USING ERRCODE='22023'; END IF;
  IF v_count<>1 THEN RAISE EXCEPTION 'support_record_changed' USING ERRCODE='40001'; END IF;
  INSERT INTO public.support_audit_events(ticket_id,actor_id,event,details) VALUES(v_request.ticket_id,auth.uid(),'workspace.updated',jsonb_build_object('request',p_request_id,'scope',p_scope,'record',p_record_id,'fields',(SELECT jsonb_agg(key) FROM jsonb_object_keys(p_patch) key)));
END; $function$

CREATE OR REPLACE FUNCTION public.wfm_save_office_time_entry(p_tenant_id uuid, p_employee_id uuid, p_work_date date, p_entry_kind text, p_reference_id uuid, p_reference_key text, p_office_entry jsonb, p_reason text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS SETOF workforce_time_entry_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_previous public.workforce_time_entry_reviews%ROWTYPE;
  v_review public.workforce_time_entry_reviews%ROWTYPE;
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
  v_pause NUMERIC;
  v_status TEXT;
  v_snapshot JSONB;
BEGIN
  IF auth.uid() IS NULL OR p_tenant_id IS DISTINCT FROM public.current_tenant_id()
    OR NOT (public.has_permission('time.tracking.admin.correct') OR public.is_tenant_admin()) THEN
    RAISE EXCEPTION 'Keine Berechtigung für Arbeitszeitkorrekturen in diesem Mandanten' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.employees WHERE tenant_id = p_tenant_id AND id = p_employee_id) THEN
    RAISE EXCEPTION 'Mitarbeitende sind diesem Mandanten nicht zugeordnet' USING ERRCODE = '23503';
  END IF;
  IF p_entry_kind NOT IN ('session', 'visit', 'manual', 'meeting')
    OR p_reference_key IS DISTINCT FROM concat_ws(':', p_tenant_id, p_employee_id, p_work_date, p_entry_kind, p_reference_id)
    OR p_reference_id IS NULL OR p_work_date IS NULL THEN
    RAISE EXCEPTION 'Ungültige Buchungsreferenz' USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(p_reason), '') IS NULL OR jsonb_typeof(p_office_entry) IS DISTINCT FROM 'object'
    OR NULLIF(p_office_entry->>'id', '') IS NULL
    OR jsonb_typeof(p_office_entry->'flags') IS DISTINCT FROM 'array'
    OR COALESCE(p_office_entry->>'source', '') NOT IN ('correction', 'manual_addition')
    OR COALESCE(p_office_entry->>'workKind', '') NOT IN ('einsatz','buero','homeoffice','fahrt','pause','korrektur','nachtrag','sonstige') THEN
    RAISE EXCEPTION 'Buchungsdaten und Begründung sind erforderlich' USING ERRCODE = '22023';
  END IF;
  v_start := (p_office_entry->>'actualStartAt')::timestamptz;
  v_end := (p_office_entry->>'actualEndAt')::timestamptz;
  v_pause := (p_office_entry->>'pauseMinutes')::numeric;
  IF v_start IS NULL OR v_end IS NULL OR NOT isfinite(v_start) OR NOT isfinite(v_end)
    OR v_end <= v_start OR v_pause IS NULL OR v_pause <> trunc(v_pause)
    OR v_pause < 0 OR v_pause > round(extract(epoch FROM (v_end - v_start)) / 60) THEN
    RAISE EXCEPTION 'Beginn, Ende oder Pause sind ungültig' USING ERRCODE = '22023';
  END IF;
  v_status := CASE WHEN p_office_entry->>'source' = 'manual_addition' THEN 'pending_review' ELSE 'corrected' END;
  v_snapshot := (p_office_entry - 'officeRevision') || jsonb_build_object(
    'tenantId', p_tenant_id, 'employeeId', p_employee_id, 'workDate', p_work_date,
    'officeComment', btrim(p_reason), 'reviewStatus', v_status, 'status', v_status,
    'exportStatus', 'not_exported');

  -- Covers both competing first inserts and edits of an existing review.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_reference_key, 0));
  SELECT * INTO v_previous FROM public.workforce_time_entry_reviews
    WHERE tenant_id = p_tenant_id AND reference_key = p_reference_key FOR UPDATE;
  IF v_previous.review_status IN ('locked','superseded')
    OR v_previous.export_status IN ('exported','changed_after_export') THEN
    RAISE EXCEPTION 'Exportierte oder gesperrte Buchungen benötigen den gesonderten Korrekturablauf' USING ERRCODE = '55000';
  END IF;
  -- Retrying the exact same request after a lost response creates no duplicate.
  IF v_previous.metadata->'office_time_entry' = v_snapshot AND v_previous.review_status = v_status THEN
    RETURN NEXT v_previous;
    RETURN;
  END IF;
  IF v_previous.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Die Buchung wurde inzwischen geändert. Bitte erneut laden.' USING ERRCODE = '40001';
  END IF;

  SELECT * INTO STRICT v_review FROM public.wfm_upsert_time_review(
    p_tenant_id, p_employee_id, p_work_date, p_entry_kind, p_reference_id, p_reference_key,
    v_status, TRUE, btrim(p_reason), btrim(p_reason), btrim(p_reason));
  UPDATE public.workforce_time_entry_reviews SET
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('office_time_entry', v_snapshot, 'office_time_entry_version', 1),
    export_status = 'not_exported', updated_at = clock_timestamp()
    WHERE tenant_id = p_tenant_id AND id = v_review.id RETURNING * INTO v_review;
  INSERT INTO public.workforce_time_review_actions (
    tenant_id, entry_review_id, action, prev_status, new_status, reason, comment,
    old_value, new_value, actor_id, source, metadata
  ) VALUES (
    p_tenant_id, v_review.id, 'comment_added', v_previous.review_status, v_status,
    btrim(p_reason), 'Zeitwerte dauerhaft gespeichert',
    v_previous.metadata->'office_time_entry', v_snapshot, auth.uid(), 'office',
    jsonb_build_object('source', 'wfm_office_time_entry_v1', 'entryId', p_office_entry->>'id'));
  RETURN NEXT v_review;
END;
$function$

CREATE OR REPLACE FUNCTION public.client_portal_finalize_assist_proof(p_tenant_id uuid, p_proof_id uuid, p_signature_id uuid, p_expected_payload_hash text, p_signed_payload_hash text, p_pdf_storage_path text, p_pdf_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_proof public.assist_visit_proofs%ROWTYPE;
  v_signature public.assist_visit_signatures%ROWTYPE;
  v_visit public.assist_visits%ROWTYPE;
  v_snapshot jsonb;
BEGIN
  IF auth.uid() IS NULL OR p_tenant_id IS DISTINCT FROM public.current_tenant_id()
     OR NOT coalesce(public.is_client_portal_rls_context(p_tenant_id), false)
     OR public.current_client_id() IS NULL THEN
    RAISE EXCEPTION 'Keine Berechtigung für diese Unterschrift';
  END IF;
  SELECT * INTO v_proof FROM public.assist_visit_proofs
    WHERE tenant_id = p_tenant_id AND id = p_proof_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Nachweis nicht gefunden'; END IF;
  SELECT * INTO v_visit FROM public.assist_visits
    WHERE tenant_id = p_tenant_id AND id = v_proof.visit_id
      AND client_id = public.current_client_id() AND planning_status <> 'draft' FOR SHARE;
  IF NOT FOUND OR NOT v_proof.portal_visible
     OR v_proof.portal_release_status NOT IN ('pending_client_signature', 'released') THEN
    RAISE EXCEPTION 'Nachweis nicht für Sie freigegeben';
  END IF;
  -- Repeated or concurrent delivery returns the existing receipt without overwriting it.
  IF v_proof.signature_id IS NOT NULL AND v_proof.pdf_storage_path IS NOT NULL
     AND v_proof.portal_release_status = 'released'
     AND v_proof.payload_snapshot->>'signedViaClientPortal' = 'true'
     AND v_proof.payload_snapshot->>'clientPortalPdfSignatureId' = v_proof.signature_id::text
     AND EXISTS (SELECT 1 FROM public.assist_visit_signatures WHERE id = v_proof.signature_id AND tenant_id = p_tenant_id AND is_valid) THEN
    RETURN jsonb_build_object('proofId', v_proof.id, 'signatureId', v_proof.signature_id,
      'signedAt', v_proof.payload_snapshot->>'clientPortalSignedAt', 'proofPersisted', true);
  END IF;
  IF v_visit.canonical_status IN ('cancelled', 'no_show') THEN RAISE EXCEPTION 'Einsatz ist nicht zur Bestätigung freigegeben'; END IF;
  IF v_proof.payload_hash IS DISTINCT FROM p_expected_payload_hash THEN
    RAISE EXCEPTION 'Der Nachweis wurde geändert. Bitte neu laden und prüfen';
  END IF;
  IF v_proof.portal_release_status = 'released' AND
     (v_proof.signature_id IS DISTINCT FROM p_signature_id OR
      v_proof.payload_snapshot->>'signedViaClientPortal' IS DISTINCT FROM 'true') THEN
    RAISE EXCEPTION 'Nachweis ist nicht zur Fertigstellung freigegeben';
  END IF;
  SELECT * INTO v_signature FROM public.assist_visit_signatures
    WHERE tenant_id = p_tenant_id AND id = p_signature_id AND visit_id = v_proof.visit_id
      AND is_valid AND signer_role = 'client'
      AND metadata->>'proofId' = p_proof_id::text
      AND metadata->>'signedVia' = 'client_portal' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Gültige Unterschrift fehlt'; END IF;
  IF v_signature.metadata->>'proofPayloadHash' IS NOT NULL
     AND v_signature.metadata->>'proofPayloadHash' IS DISTINCT FROM v_proof.payload_hash
     AND v_proof.signature_id IS DISTINCT FROM v_signature.id THEN
    RAISE EXCEPTION 'Unterschrift gehört zu einer früheren Nachweisfassung';
  END IF;
  IF p_pdf_storage_path NOT LIKE ('tenant/' || p_tenant_id || '/assist/visits/' || v_proof.visit_id || '/proofs/' || p_proof_id || '-' || p_signature_id || '-%.pdf')
     OR p_pdf_hash !~ '^(sha256:)?[a-f0-9]{64}$' OR p_signed_payload_hash !~ '^(sha256:)?[a-f0-9]{64}$'
     OR p_pdf_storage_path IS NULL OR p_pdf_hash IS NULL OR p_signed_payload_hash IS NULL THEN
    RAISE EXCEPTION 'Nachweisdatei ist ungültig';
  END IF;
  PERFORM 1 FROM storage.objects WHERE bucket_id = 'office-documents' AND name = p_pdf_storage_path;
  IF NOT FOUND THEN RAISE EXCEPTION 'Nachweisdatei wurde noch nicht übertragen'; END IF;
  PERFORM 1 FROM storage.objects WHERE bucket_id = 'office-documents' AND name = v_signature.storage_path;
  IF NOT FOUND THEN RAISE EXCEPTION 'Signaturbild fehlt'; END IF;

  v_snapshot := v_proof.payload_snapshot || jsonb_build_object(
    'signatureDeferredToClientPortal', false, 'clientPortalSignedAt', to_char(v_signature.signed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'signedViaClientPortal', true, 'clientPortalPdfSignatureId', p_signature_id::text, 'signerName', v_signature.signer_name,
    'signedAt', to_char(v_signature.signed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'signature', jsonb_build_object('signerName', v_signature.signer_name,
      'signedAt', to_char(v_signature.signed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'signerRole', 'client'));

  INSERT INTO public.client_documents (id, tenant_id, client_id, title, file_name, mime_type,
    category, storage_path, portal_visible, status, sensitivity, source, signed_at, signature_required, updated_at)
  VALUES (p_proof_id, p_tenant_id, v_visit.client_id,
    coalesce(nullif(v_snapshot->>'title', ''), nullif(v_snapshot->>'serviceName', ''), 'Leistungsnachweis'),
    'Leistungsnachweis-' || coalesce(v_proof.proof_number, p_proof_id::text) || '.pdf', 'application/pdf',
    'leistungsnachweis', p_pdf_storage_path, true, 'aktiv', 'care', 'assist_visit_proof', v_signature.signed_at, false, now())
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, file_name = excluded.file_name,
    mime_type = excluded.mime_type, category = excluded.category, storage_path = excluded.storage_path,
    portal_visible = true, status = 'aktiv', signed_at = excluded.signed_at,
    signature_required = false, updated_at = now()
  WHERE client_documents.tenant_id = excluded.tenant_id AND client_documents.client_id = excluded.client_id
    AND client_documents.source = 'assist_visit_proof';
  IF NOT FOUND THEN RAISE EXCEPTION 'Portal-Dokument ist nicht eindeutig zugeordnet'; END IF;

  UPDATE public.assist_visit_proofs SET signature_id = p_signature_id, payload_snapshot = v_snapshot,
    payload_hash = p_signed_payload_hash, pdf_storage_path = p_pdf_storage_path, pdf_hash = p_pdf_hash,
    portal_release_status = 'released', status = 'pending_review', updated_at = now()
  WHERE id = p_proof_id AND tenant_id = p_tenant_id;

  INSERT INTO public.assist_visit_execution_state
    (tenant_id, visit_id, current_step, assignment_status, signature_complete, proof_generated, finalized_at, updated_at)
  VALUES (p_tenant_id, v_visit.id, 'completed', 'abgeschlossen', true, true, v_signature.signed_at, now())
  ON CONFLICT (tenant_id, visit_id) DO UPDATE SET
    current_step = 'completed', assignment_status = 'abgeschlossen', signature_complete = true,
    proof_generated = true, finalized_at = excluded.finalized_at, updated_at = now();

  INSERT INTO public.audit_logs (tenant_id, action, record_id, table_name, title, new_data)
    VALUES (p_tenant_id, 'signature', p_proof_id, 'assist_visit_proofs', 'Leistungsnachweis im Klientenportal unterzeichnet',
      jsonb_build_object('event', 'client_portal_proof_signed', 'signature_id', p_signature_id, 'signed_at', v_signature.signed_at, 'actor_user_id', auth.uid()));

  RETURN jsonb_build_object('proofId', p_proof_id, 'signatureId', p_signature_id,
    'signedAt', v_snapshot->>'clientPortalSignedAt', 'proofPersisted', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.client_portal_sign_document_request(p_tenant_id uuid, p_request_id uuid, p_signer_role text, p_signer_name text, p_signature_data_url text, p_expected_updated_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request public.cs_document_requests%ROWTYPE;
  v_signed_at timestamptz := now();
  v_html text;
  v_image text;
  v_anchor text;
  v_pattern text;
  v_all_done boolean;
BEGIN
  IF auth.uid() IS NULL OR p_tenant_id IS DISTINCT FROM public.current_tenant_id()
     OR NOT coalesce(public.is_client_portal_rls_context(p_tenant_id), false)
     OR public.current_client_id() IS NULL OR p_signer_role NOT IN ('client', 'representative')
     OR p_signer_role IS NULL THEN RAISE EXCEPTION 'Keine Berechtigung für diese Unterschrift'; END IF;
  SELECT * INTO v_request FROM public.cs_document_requests
    WHERE id = p_request_id AND owner_tenant_id = p_tenant_id
      AND client_id = public.current_client_id() AND portal_visible
      AND recipient_scope IN ('client', 'both') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dokument nicht für Sie freigegeben'; END IF;
  IF EXISTS (SELECT 1 FROM public.cs_document_request_signatures
      WHERE request_id = p_request_id AND signer_role = p_signer_role AND status = 'signed')
     AND NOT EXISTS (SELECT 1 FROM public.cs_document_request_signatures
      WHERE request_id = p_request_id AND signer_role = p_signer_role AND status = 'pending') THEN
    RETURN p_request_id;
  END IF;
  IF v_request.status NOT IN ('sent', 'opened', 'partially_signed')
     OR v_request.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Dokument wurde geändert. Bitte neu laden und prüfen';
  END IF;
  IF nullif(trim(p_signer_name), '') IS NULL OR length(p_signer_name) > 300
     OR p_signature_data_url IS NULL OR length(p_signature_data_url) > 3000000
     OR p_signature_data_url !~ '^data:image/png;base64,[A-Za-z0-9+/]+={0,2}$'
     OR nullif(trim(v_request.rendered_html), '') IS NULL THEN
    RAISE EXCEPTION 'Signatur oder Dokumentvorschau ist unvollständig';
  END IF;
  UPDATE public.cs_document_request_signatures SET status = 'signed', signer_name = trim(p_signer_name),
    signature_data_url = p_signature_data_url, signed_at = v_signed_at, updated_at = v_signed_at
    WHERE request_id = p_request_id AND signer_role = p_signer_role AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Keine offene Unterschrift für diese Rolle'; END IF;
  -- Derive the HTML from the locked original. The portal cannot replace document text.
  v_anchor := p_signer_role || '_signature';
  v_image := '<img src="' || p_signature_data_url || '" alt="Unterschrift" style="max-height:80px;max-width:240px;" /><br/><small>'
    || replace(replace(replace(trim(p_signer_name), '&', '&amp;'), '<', '&lt;'), '>', '&gt;')
    || ' · ' || to_char(v_signed_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI:SS') || '</small>';
  v_pattern := '(<span[^>]*data-signature-anchor="' || v_anchor || '"[^>]*>)(\[SIGNATURE:[^]]+\])(</span>)';
  IF v_request.rendered_html ~* v_pattern THEN
    v_html := regexp_replace(v_request.rendered_html, v_pattern, '\1' || replace(v_image, E'\\', E'\\\\') || '\3', 'i');
  ELSE
    v_html := v_request.rendered_html || '<p data-signature-anchor="' || v_anchor || '">' || v_image || '</p>';
  END IF;
  SELECT NOT EXISTS (SELECT 1 FROM public.cs_document_request_signatures
    WHERE request_id = p_request_id AND status NOT IN ('signed', 'not_required')) INTO v_all_done;
  UPDATE public.cs_document_requests SET status = CASE WHEN v_all_done THEN 'completed' ELSE 'partially_signed' END,
    rendered_html = v_html, completed_at = CASE WHEN v_all_done THEN v_signed_at ELSE NULL END, updated_at = v_signed_at
    WHERE id = p_request_id AND owner_tenant_id = p_tenant_id;
  INSERT INTO public.audit_logs (tenant_id, action, record_id, table_name, title, new_data)
    VALUES (p_tenant_id, 'signature', p_request_id, 'cs_document_requests', 'Dokument im Klientenportal unterzeichnet',
      jsonb_build_object('event', 'document_request_signed', 'signer_role', p_signer_role, 'signed_at', v_signed_at, 'actor_user_id', auth.uid()));
  RETURN p_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_reconcile_complete_assist_visit_follow_up(p_visit_id uuid, p_task_states jsonb, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v public.assist_visits%ROWTYPE;
  v_actor UUID := public.resolve_current_profile_id();
  v_assignment_id UUID;
  v_item JSONB;
  v_match JSONB;
  v_visit_task_id UUID;
  v_assignment_task_id UUID;
  v_source_id UUID;
  v_title TEXT;
  v_sort_order INTEGER;
  v_status TEXT;
  v_assignment_status TEXT;
  v_signature_deferred BOOLEAN := FALSE;
  v_open_titles TEXT;
BEGIN
  IF NOT (public.is_tenant_admin() OR public.has_permission('assist.execution.manage')) THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  IF length(trim(coalesce(p_reason, ''))) = 0 THEN
    RAISE EXCEPTION 'Begründung ist erforderlich';
  END IF;
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Angemeldetes Verwaltungsprofil konnte nicht zugeordnet werden';
  END IF;
  IF p_task_states IS NULL OR jsonb_typeof(p_task_states) <> 'array' THEN
    RAISE EXCEPTION 'Aufgabenstatus ist ungültig';
  END IF;

  SELECT * INTO v
  FROM public.assist_visits
  WHERE id = p_visit_id AND tenant_id = public.current_tenant_id()
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden'; END IF;

  v_assignment_id := coalesce(v.legacy_assignment_id, v.id);

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_task_states)
  LOOP
    v_title := NULL;
    v_sort_order := NULL;
    BEGIN
      v_source_id := nullif(v_item->>'task_id', '')::UUID;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Ungültige Aufgaben-ID';
    END;
    v_status := v_item->>'status';
    IF v_source_id IS NULL OR v_status NOT IN (
      'open', 'done', 'partial', 'not_requested',
      'not_possible', 'cancelled', 'deferred'
    ) THEN
      RAISE EXCEPTION 'Ungültiger Aufgabenstatus';
    END IF;

    v_match := public.resolve_admin_visit_task_ids(v.id,v_source_id);
    v_visit_task_id := (v_match->>'visit_task_id')::uuid;
    v_assignment_task_id := (v_match->>'assignment_task_id')::uuid;
    IF v_visit_task_id IS NULL AND v_assignment_task_id IS NULL THEN RAISE EXCEPTION 'Aufgabe nicht gefunden'; END IF;

    UPDATE public.assist_visit_tasks t
    SET
      status = v_status,
      not_done_reason = CASE WHEN v_status = 'done' THEN NULL ELSE trim(p_reason) END,
      completed_at = CASE WHEN v_status = 'done' THEN coalesce(t.completed_at, now()) ELSE NULL END,
      updated_at = now()
    WHERE t.tenant_id = v.tenant_id
      AND t.visit_id = v.id
      AND t.id = v_visit_task_id;

    IF to_regclass('public.assignment_tasks') IS NOT NULL THEN
      v_assignment_status := CASE v_status
        WHEN 'not_possible' THEN 'not_done'
        WHEN 'deferred' THEN 'not_done'
        ELSE v_status
      END;
      UPDATE public.assignment_tasks t
      SET
        status = v_assignment_status,
        not_done_reason = CASE WHEN v_status = 'done' THEN NULL ELSE trim(p_reason) END,
        updated_at = now()
      WHERE t.tenant_id = v.tenant_id
        AND t.assignment_id = v_assignment_id
        AND t.id = v_assignment_task_id;
    END IF;
  END LOOP;

  IF v.actual_start_at IS NULL OR v.actual_end_at IS NULL
     OR coalesce(v.duration_minutes, 0) <= 0 THEN
    RAISE EXCEPTION 'Gültige Ist-Zeiten fehlen';
  END IF;

  SELECT string_agg(t.title, ', ' ORDER BY t.sort_order) INTO v_open_titles
  FROM public.assist_visit_tasks t
  WHERE t.tenant_id = v.tenant_id AND t.visit_id = v.id
    AND t.is_required AND t.status = 'open';

  IF v_open_titles IS NULL AND to_regclass('public.assignment_tasks') IS NOT NULL THEN
    SELECT string_agg(t.title, ', ' ORDER BY t.sort_order) INTO v_open_titles
    FROM public.assignment_tasks t
    WHERE t.tenant_id = v.tenant_id AND t.assignment_id = v_assignment_id
      AND t.is_required AND t.status = 'open';
  END IF;
  IF v_open_titles IS NOT NULL THEN
    RAISE EXCEPTION 'Pflichtaufgaben sind noch offen: %', v_open_titles;
  END IF;

  IF v.documentation_status <> 'complete' THEN
    RAISE EXCEPTION 'Dokumentation ist nicht vollständig';
  END IF;

  IF v.proof_status NOT IN ('signed', 'verified') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.assist_visit_signature_requests
      WHERE tenant_id = v.tenant_id AND visit_id = v.id AND status = 'open'
      UNION ALL
      SELECT 1 FROM public.assist_visit_proofs
      WHERE tenant_id = v.tenant_id AND visit_id = v.id
        AND portal_visible = TRUE
        AND portal_release_status = 'pending_client_signature'
    ) INTO v_signature_deferred;
    IF NOT v_signature_deferred THEN
      RAISE EXCEPTION 'Signatur oder verifizierter Nachweis fehlt';
    END IF;
  END IF;

  UPDATE public.assist_visits
  SET
    execution_status = 'completed',
    canonical_status = 'completed',
    billing_status = CASE WHEN v_signature_deferred THEN 'blocked' ELSE 'ready' END,
    finished_at = coalesce(finished_at, actual_end_at),
    updated_by = v_actor,
    updated_at = now()
  WHERE id = v.id AND tenant_id = v.tenant_id;

  UPDATE public.assignments
  SET status = 'completed', updated_at = now()
  WHERE id = v_assignment_id AND tenant_id = v.tenant_id;

  INSERT INTO public.assist_visit_admin_audit (
    tenant_id, visit_id, action, previous_value, new_value, reason
  ) VALUES (
    v.tenant_id, v.id, 'follow_up_completed_reconciled',
    jsonb_build_object('canonical_status', v.canonical_status),
    jsonb_build_object(
      'canonical_status', 'completed',
      'signature_deferred_to_client_portal', v_signature_deferred,
      'billing_status', CASE WHEN v_signature_deferred THEN 'blocked' ELSE 'ready' END,
      'task_state_count', jsonb_array_length(p_task_states)
    ), trim(p_reason)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_set_feature_flag(p_flag_key text, p_enabled boolean, p_reason text, p_scope text DEFAULT 'global'::text, p_tenant_id uuid DEFAULT NULL::uuid, p_rollout_percentage integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.platform_feature_flags%ROWTYPE;v_after public.platform_feature_flags%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('flags.write');PERFORM public.platform_assert_reason(p_reason);
  IF p_flag_key IS NULL OR p_flag_key !~ '^[a-z0-9_.-]{3,100}$' OR p_enabled IS NULL
    OR p_scope IS NULL OR p_scope NOT IN ('global','tenant')
    OR (p_scope='global' AND p_tenant_id IS NOT NULL) OR (p_scope='tenant' AND p_tenant_id IS NULL)
    OR (p_rollout_percentage IS NOT NULL AND (p_rollout_percentage<0 OR p_rollout_percentage>100)) THEN
    RAISE EXCEPTION 'invalid_flag_scope_or_rollout' USING ERRCODE='22023';
  END IF;
  IF p_scope='tenant' AND NOT EXISTS(SELECT 1 FROM public.platform_tenants WHERE tenant_id=p_tenant_id) THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE='P0002';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('platform-flag:'||p_flag_key||':'||coalesce(p_tenant_id::text,'global'),0));
  SELECT * INTO v_before FROM public.platform_feature_flags
    WHERE flag_key=p_flag_key AND tenant_id IS NOT DISTINCT FROM p_tenant_id
      AND (p_tenant_id IS NOT NULL OR scope='global') FOR UPDATE;
  IF FOUND THEN
    IF v_before.scope<>p_scope THEN RAISE EXCEPTION 'invalid_flag_scope_or_rollout' USING ERRCODE='23514';END IF;
    UPDATE public.platform_feature_flags SET enabled=p_enabled,rollout_percentage=p_rollout_percentage,
      updated_by=auth.uid(),updated_at=now() WHERE id=v_before.id RETURNING * INTO v_after;
  ELSE
    INSERT INTO public.platform_feature_flags(flag_key,scope,tenant_id,enabled,rollout_percentage,created_by,updated_by)
      VALUES(p_flag_key,p_scope,p_tenant_id,p_enabled,p_rollout_percentage,auth.uid(),auth.uid()) RETURNING * INTO v_after;
  END IF;
  PERFORM public.platform_write_audit_log('feature_flag.changed','platform_feature_flag',v_after.id,p_tenant_id,
    CASE WHEN v_before.id IS NULL THEN NULL ELSE to_jsonb(v_before) END,to_jsonb(v_after),trim(p_reason));
  RETURN to_jsonb(v_after);
END $function$

CREATE OR REPLACE FUNCTION public.platform_save_module_catalog(p_key text, p_name text, p_description text, p_category text, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.platform_modules%ROWTYPE; v_after public.platform_modules%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('modules.write');
  PERFORM public.platform_assert_reason(p_reason);
  IF p_key IS NULL OR p_key !~ '^[a-z0-9_-]{3,100}$' OR lower(p_key) LIKE '%bodymap%' THEN
    RAISE EXCEPTION 'invalid_module_key' USING ERRCODE='22023';
  END IF;
  IF length(trim(coalesce(p_name,'')))<2 OR p_status IS NULL OR p_status NOT IN ('available','beta','internal','deprecated','disabled') THEN
    RAISE EXCEPTION 'invalid_module_record' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('platform-module:'||p_key,0));
  SELECT * INTO v_before FROM public.platform_modules WHERE module_key=p_key FOR UPDATE;
  IF v_before.is_core AND p_status NOT IN ('available','beta') THEN
    RAISE EXCEPTION 'core_module_protected' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.platform_modules(module_key,module_name,description,category,status,is_beta,is_internal)
    VALUES(p_key,trim(p_name),nullif(trim(p_description),''),nullif(trim(p_category),''),p_status,p_status='beta',p_status='internal')
    ON CONFLICT(module_key) DO UPDATE SET module_name=excluded.module_name,description=excluded.description,
      category=excluded.category,status=excluded.status,is_beta=excluded.is_beta,is_internal=excluded.is_internal,updated_at=now()
    RETURNING * INTO v_after;
  PERFORM public.platform_write_audit_log('module.catalog_saved','platform_module',v_after.id,NULL,
    CASE WHEN v_before.id IS NULL THEN NULL ELSE to_jsonb(v_before) END,to_jsonb(v_after),trim(p_reason));
  RETURN to_jsonb(v_after);
END $function$

CREATE OR REPLACE FUNCTION public.platform_update_system_setting(p_setting_key text, p_value jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.platform_system_settings%ROWTYPE;v_after public.platform_system_settings%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('system.write');PERFORM public.platform_assert_reason(p_reason);
  IF p_setting_key IN ('free_platform_enabled','default_trial_days','invoice_due_days') THEN
    RAISE EXCEPTION 'free_usage_policy_locked' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_before FROM public.platform_system_settings WHERE setting_key=p_setting_key FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'setting_not_found' USING ERRCODE='P0002';END IF;
  IF v_before.is_sensitive OR p_setting_key ~* '(secret|token|password|api[_-]?key|private|credential)'
    OR public.platform_redact_console_value(v_before.value) IS DISTINCT FROM v_before.value THEN
    RAISE EXCEPTION 'protected_setting' USING ERRCODE='42501';
  END IF;
  IF p_value IS NULL OR jsonb_typeof(p_value)<>jsonb_typeof(v_before.value) THEN
    RAISE EXCEPTION 'setting_type_mismatch' USING ERRCODE='22023';
  END IF;
  IF p_setting_key IN ('default_trial_days','support_session_minutes','invoice_due_days')
     AND (jsonb_typeof(p_value)<>'number' OR (p_value#>>'{}')::numeric<0 OR (p_value#>>'{}')::numeric<>trunc((p_value#>>'{}')::numeric)) THEN
    RAISE EXCEPTION 'invalid_setting_value' USING ERRCODE='22023';
  END IF;
  UPDATE public.platform_system_settings SET value=p_value,updated_by=auth.uid(),updated_at=now()
    WHERE id=v_before.id RETURNING * INTO v_after;
  PERFORM public.platform_write_audit_log('system_setting.changed','platform_system_setting',v_after.id,NULL,to_jsonb(v_before),to_jsonb(v_after),trim(p_reason));
  RETURN to_jsonb(v_after);
END $function$

CREATE OR REPLACE FUNCTION public.platform_add_operator_user(p_email text, p_role text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user UUID;v_row public.platform_users%ROWTYPE;
BEGIN
  PERFORM public.platform_assert_capability('users.write');PERFORM public.platform_assert_reason(p_reason);
  IF p_role IS NULL OR p_role NOT IN ('platform_owner','platform_admin','platform_billing','platform_support','platform_developer','platform_readonly') THEN
    RAISE EXCEPTION 'invalid_platform_role' USING ERRCODE='22023';END IF;
  SELECT id INTO v_user FROM auth.users WHERE lower(email)=lower(trim(p_email)) AND deleted_at IS NULL;
  IF v_user IS NULL THEN RAISE EXCEPTION 'existing_auth_user_required' USING ERRCODE='P0002';END IF;
  IF EXISTS(SELECT 1 FROM public.platform_users WHERE user_id=v_user) THEN
    RAISE EXCEPTION 'platform_user_already_exists' USING ERRCODE='23505';END IF;
  INSERT INTO public.platform_users(user_id,email,role,status,created_by)
    VALUES(v_user,lower(trim(p_email)),p_role,'active',auth.uid()) RETURNING * INTO v_row;
  PERFORM public.platform_write_audit_log('platform_user.created','platform_user',v_row.id,NULL,NULL,
    jsonb_build_object('email',v_row.email,'role',v_row.role,'status',v_row.status),trim(p_reason));
  RETURN jsonb_build_object('id',v_row.id,'email',v_row.email,'role',v_row.role,'status',v_row.status);
END $function$

CREATE OR REPLACE FUNCTION public.platform_update_payment_status(p_payment_id uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.platform_payments%ROWTYPE;v_after public.platform_payments%ROWTYPE;v_invoice UUID;
BEGIN
  PERFORM public.platform_assert_capability('payments.write');PERFORM public.platform_assert_reason(p_reason);
  IF p_status IS NULL OR p_status NOT IN ('pending','succeeded','failed','cancelled','refunded','chargeback') THEN
    RAISE EXCEPTION 'invalid_payment_status' USING ERRCODE='22023';END IF;
  -- All payment operations lock invoice first, then payment, to avoid deadlocks.
  SELECT invoice_id INTO v_invoice FROM public.platform_payments WHERE id=p_payment_id;
  IF v_invoice IS NOT NULL THEN PERFORM 1 FROM public.platform_invoices WHERE id=v_invoice FOR UPDATE;END IF;
  SELECT * INTO v_before FROM public.platform_payments WHERE id=p_payment_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'payment_not_found' USING ERRCODE='P0002';END IF;
  IF v_before.provider IS DISTINCT FROM 'manual' THEN RAISE EXCEPTION 'provider_payment_readonly' USING ERRCODE='42501';END IF;
  UPDATE public.platform_payments SET status=p_status,
    paid_at=CASE WHEN p_status='succeeded' THEN coalesce(paid_at,now()) ELSE NULL END,
    failed_at=CASE WHEN p_status='failed' THEN now() ELSE NULL END,updated_at=now()
    WHERE id=p_payment_id RETURNING * INTO v_after;
  PERFORM public.platform_write_audit_log('payment.status_changed','platform_payment',v_after.id,v_after.tenant_id,to_jsonb(v_before),to_jsonb(v_after),trim(p_reason));
  PERFORM public.platform_reconcile_console_invoice(v_after.invoice_id,trim(p_reason));
  RETURN to_jsonb(v_after);
END $function$

CREATE OR REPLACE FUNCTION public.platform_record_console_finance(p_request_id uuid, p_operation text, p_payload jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_request public.platform_console_requests%ROWTYPE;v_result JSONB;
BEGIN
  IF p_operation='payment' THEN PERFORM public.platform_assert_capability('payments.write');
  ELSIF p_operation='invoice' THEN PERFORM public.platform_assert_capability('billing.write');
  ELSE RAISE EXCEPTION 'invalid_finance_operation' USING ERRCODE='22023';END IF;
  PERFORM public.platform_assert_reason(p_reason);
  IF p_request_id IS NULL OR p_payload IS NULL THEN RAISE EXCEPTION 'request_required' USING ERRCODE='22023';END IF;
  INSERT INTO public.platform_console_requests(actor_id,request_id,operation,payload)
    VALUES(auth.uid(),p_request_id,p_operation,p_payload) ON CONFLICT DO NOTHING;
  SELECT * INTO v_request FROM public.platform_console_requests WHERE actor_id=auth.uid() AND request_id=p_request_id FOR UPDATE;
  IF v_request.operation<>p_operation OR v_request.payload<>p_payload THEN RAISE EXCEPTION 'request_payload_changed' USING ERRCODE='23514';END IF;
  IF v_request.result IS NOT NULL THEN RETURN v_request.result;END IF;
  IF p_operation='payment' THEN
    v_result=public.platform_record_manual_payment((p_payload->>'tenant_id')::uuid,(p_payload->>'invoice_id')::uuid,
      (p_payload->>'amount_cents')::integer,'succeeded',p_reason,p_payload->>'payment_method');
  ELSE
    IF p_payload->>'due_date' IS NULL OR p_payload->>'tenant_id' IS NULL
      OR p_payload->>'amount_cents' IS NULL OR p_payload->>'tax_cents' IS NULL
      OR (p_payload->>'amount_cents')::integer<=0 OR (p_payload->>'tax_cents')::integer<0
      OR (p_payload->>'tax_cents')::integer>(p_payload->>'amount_cents')::integer THEN
      RAISE EXCEPTION 'invalid_invoice_values' USING ERRCODE='22023';END IF;
    v_result=public.platform_create_manual_invoice((p_payload->>'tenant_id')::uuid,(p_payload->>'amount_cents')::integer,
      (p_payload->>'tax_cents')::integer,(p_payload->>'due_date')::date,p_reason);
  END IF;
  UPDATE public.platform_console_requests SET result=v_result WHERE actor_id=auth.uid() AND request_id=p_request_id;
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.platform_update_invoice_status(p_invoice_id uuid, p_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before public.platform_invoices%ROWTYPE;v_after public.platform_invoices%ROWTYPE;v_received BIGINT;
BEGIN
  PERFORM public.platform_assert_capability('billing.write');PERFORM public.platform_assert_reason(p_reason);
  IF p_status IS NULL OR p_status NOT IN ('draft','open','past_due','cancelled','failed') THEN
    RAISE EXCEPTION 'invoice_status_payment_managed' USING ERRCODE='22023';END IF;
  SELECT * INTO v_before FROM public.platform_invoices WHERE id=p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'invoice_not_found' USING ERRCODE='P0002';END IF;
  IF v_before.provider IS NOT NULL AND v_before.provider<>'manual' THEN
    RAISE EXCEPTION 'provider_invoice_readonly' USING ERRCODE='42501';END IF;
  SELECT coalesce(sum(amount_cents),0) INTO v_received FROM public.platform_payments
    WHERE invoice_id=p_invoice_id AND tenant_id=v_before.tenant_id AND currency=v_before.currency AND status='succeeded';
  IF v_received>0 OR v_before.status IN ('paid','partially_paid','refunded') THEN
    RAISE EXCEPTION 'invoice_status_payment_managed' USING ERRCODE='23514';END IF;
  IF p_status='past_due' AND (v_before.due_date IS NULL OR v_before.due_date>=current_date) THEN
    RAISE EXCEPTION 'invoice_not_past_due' USING ERRCODE='23514';END IF;
  UPDATE public.platform_invoices SET status=p_status,paid_at=NULL,
    cancelled_at=CASE WHEN p_status='cancelled' THEN coalesce(cancelled_at,now()) ELSE NULL END,
    failed_at=CASE WHEN p_status='failed' THEN coalesce(failed_at,now()) ELSE NULL END,updated_at=now()
    WHERE id=p_invoice_id RETURNING * INTO v_after;
  PERFORM public.platform_write_audit_log('invoice.status_changed','platform_invoice',v_after.id,v_after.tenant_id,to_jsonb(v_before),to_jsonb(v_after),trim(p_reason));
  RETURN to_jsonb(v_after);
END $function$
